/**
 * Toggle para alternar entre modo claro e escuro
 */

import React, { useEffect, useState } from 'react'
import { Sun, Moon } from 'lucide-react'

export function ThemeToggle() {
  const [theme, setTheme] = useState<'light' | 'dark'>('light')

  useEffect(() => {
    // Carregar tema salvo ou preferência do sistema
    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark' | null
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches

    const initialTheme = savedTheme || (prefersDark ? 'dark' : 'light')
    setTheme(initialTheme)
    applyTheme(initialTheme)
  }, [])

  const applyTheme = (newTheme: 'light' | 'dark') => {
    const root = document.documentElement

    if (newTheme === 'dark') {
      root.classList.add('dark')
      root.setAttribute('data-theme', 'dark')
    } else {
      root.classList.remove('dark')
      root.setAttribute('data-theme', 'light')
    }

    localStorage.setItem('theme', newTheme)
  }

  const toggleTheme = () => {
    const newTheme = theme === 'light' ? 'dark' : 'light'
    setTheme(newTheme)
    applyTheme(newTheme)
  }

  return (
    <button
      onClick={toggleTheme}
      className="
        relative
        w-14 h-7
        bg-gray-200 dark:bg-gray-700
        rounded-full
        transition-colors duration-300
        focus:outline-none focus:ring-4 focus:ring-blue-500/30
        group
      "
      aria-label={`Mudar para modo ${theme === 'light' ? 'escuro' : 'claro'}`}
    >
      {/* Track */}
      <div className="absolute inset-0 rounded-full overflow-hidden">
        <div
          className={`
            absolute inset-0
            bg-gradient-to-r from-blue-600 to-purple-600
            transition-opacity duration-300
            ${theme === 'dark' ? 'opacity-100' : 'opacity-0'}
          `}
        />
      </div>

      {/* Thumb */}
      <div
        className={`
          absolute top-0.5 left-0.5
          w-6 h-6
          bg-white dark:bg-gray-900
          rounded-full
          shadow-lg
          flex items-center justify-center
          transition-all duration-300
          ${theme === 'dark' ? 'translate-x-7' : 'translate-x-0'}
          group-hover:scale-110
        `}
      >
        {/* Ícones */}
        <Sun
          className={`
            absolute w-3.5 h-3.5 text-yellow-500
            transition-all duration-300
            ${theme === 'light' ? 'opacity-100 rotate-0' : 'opacity-0 rotate-180'}
          `}
        />
        <Moon
          className={`
            absolute w-3.5 h-3.5 text-blue-500
            transition-all duration-300
            ${theme === 'dark' ? 'opacity-100 rotate-0' : 'opacity-0 -rotate-180'}
          `}
        />
      </div>
    </button>
  )
}

/**
 * Hook personalizado para usar o tema
 */
export function useTheme() {
  const [theme, setTheme] = useState<'light' | 'dark'>('light')

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark' | null
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches
    const initialTheme = savedTheme || (prefersDark ? 'dark' : 'light')
    setTheme(initialTheme)
  }, [])

  const toggleTheme = () => {
    const newTheme = theme === 'light' ? 'dark' : 'light'
    setTheme(newTheme)

    if (newTheme === 'dark') {
      document.documentElement.classList.add('dark')
      document.documentElement.setAttribute('data-theme', 'dark')
    } else {
      document.documentElement.classList.remove('dark')
      document.documentElement.setAttribute('data-theme', 'light')
    }

    localStorage.setItem('theme', newTheme)
  }

  return { theme, toggleTheme, isDark: theme === 'dark' }
}

import { useEffect, useState, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon } from "lucide-react";
import { format, isSameDay } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { Agendamento, useAgendamentos } from "@/hooks/useAgendamentos";
import { usePacientes } from "@/hooks/usePacientes";
import { useDentistas } from "@/hooks/useDentistas";
import { useConvenios } from "@/hooks/useConvenios";
import { useHorariosDisponiveis } from "@/hooks/useHorariosDisponiveis";
import { useProteticos } from "@/hooks/useProteticos";

interface AgendamentoFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: any) => Promise<void>;
  agendamento?: Agendamento | null;
}

export function AgendamentoForm({ open, onOpenChange, onSubmit, agendamento }: AgendamentoFormProps) {
  const { pacientes, refetch: refetchPacientes } = usePacientes();
  const { dentistas, refetch: refetchDentistas } = useDentistas();
  const { convenios, refetch: refetchConvenios } = useConvenios();
  const { data: proteticos = [], refetch: refetchProteticos } = useProteticos();
  const { agendamentos: todosAgendamentos, fetchAgendamentos } = useAgendamentos();
  const { horarios: horariosConfigurados } = useHorariosDisponiveis();

  const [tipoProfissional, setTipoProfissional] = useState<"Dentista" | "Protetico">("Dentista");
  const [formData, setFormData] = useState({
    paciente_id: "",
    dentista_id: "",
    protetico_id: "",
    data_agendamento: new Date(),
    hora: "09:00",
    duracao: 30,
    procedimento: "",
    tipo_atendimento: "Consulta",
    status: "Agendado",
    convenio_id: "particular",
    valor: 0,
    observacoes: "",
    confirmado: false,
  });

  useEffect(() => {
    if (open) {
      refetchPacientes();
      refetchDentistas();
      refetchConvenios();
      refetchProteticos();
    }
  }, [open]);

  // Buscar agendamentos quando a data mudar
  useEffect(() => {
    if (formData.data_agendamento) {
      const startOfDay = new Date(formData.data_agendamento);
      startOfDay.setHours(0, 0, 0, 0);
      const endOfDay = new Date(formData.data_agendamento);
      endOfDay.setHours(23, 59, 59, 999);
      fetchAgendamentos(startOfDay, endOfDay);
    }
  }, [formData.data_agendamento, formData.dentista_id, formData.protetico_id]);

  // Calcular horários disponíveis baseado na configuração e agendamentos
  const horariosDisponiveis = useMemo(() => {
    if (!formData.data_agendamento || (tipoProfissional === "Dentista" && !formData.dentista_id) || (tipoProfissional === "Protetico" && !formData.protetico_id)) {
      return [];
    }

    // Obter dia da semana (0 = Domingo, 1 = Segunda, etc.)
    const diaSemana = formData.data_agendamento.getDay();

    // Filtros de horários
    const horariosConfiguradosDoDia = horariosConfigurados
      .filter(h => h.dia_semana === diaSemana && h.ativo)
      .map(h => h.hora.substring(0, 5))
      .sort();

    if (horariosConfiguradosDoDia.length === 0) {
      return [];
    }

    // Filtrar agendamentos do mesmo profissional na mesma data
    const agendamentosDoDia = todosAgendamentos.filter(apt => {
      const aptDate = new Date(apt.data_agendamento);
      const statusOcupado = ["Agendado", "Confirmado", "Realizado"];

      const isProfissionalMatch = tipoProfissional === "Dentista" 
        ? apt.dentista_id === formData.dentista_id 
        : apt.protetico_id?.toString() === formData.protetico_id;

      return (
        isProfissionalMatch &&
        isSameDay(aptDate, formData.data_agendamento) &&
        statusOcupado.includes(apt.status) &&
        apt.id !== agendamento?.id
      );
    });

    // Remover horários já ocupados
    return horariosConfiguradosDoDia.filter(horario => {
      return !agendamentosDoDia.some(apt => {
        const aptDate = new Date(apt.data_agendamento);
        const aptHora = format(aptDate, "HH:mm");
        return aptHora === horario;
      });
    });
  }, [horariosConfigurados, todosAgendamentos, formData.data_agendamento, formData.dentista_id, formData.protetico_id, tipoProfissional, agendamento?.id]);

  useEffect(() => {
    if (agendamento) {
      const dataAgendamento = new Date(agendamento.data_agendamento);
      const isProtetico = !!agendamento.protetico_id;
      setTipoProfissional(isProtetico ? "Protetico" : "Dentista");
      setFormData({
        paciente_id: agendamento.paciente_id,
        dentista_id: agendamento.dentista_id || "",
        protetico_id: agendamento.protetico_id ? agendamento.protetico_id.toString() : "",
        data_agendamento: dataAgendamento,
        hora: format(dataAgendamento, "HH:mm"),
        duracao: agendamento.duracao,
        procedimento: agendamento.procedimento,
        tipo_atendimento: agendamento.tipo_atendimento,
        status: agendamento.status,
        convenio_id: agendamento.convenio_id || "particular",
        valor: agendamento.valor || 0,
        observacoes: agendamento.observacoes || "",
        confirmado: agendamento.confirmado,
      });
    } else {
      setTipoProfissional("Dentista");
      setFormData({
        paciente_id: "",
        dentista_id: "",
        protetico_id: "",
        data_agendamento: new Date(),
        hora: "09:00",
        duracao: 30,
        procedimento: "",
        tipo_atendimento: "Consulta",
        status: "Agendado",
        convenio_id: "particular",
        valor: 0,
        observacoes: "",
        confirmado: false,
      });
    }
  }, [agendamento]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const [hour, minute] = formData.hora.split(':');
    const dataAgendamento = new Date(formData.data_agendamento);
    dataAgendamento.setHours(parseInt(hour), parseInt(minute), 0, 0);

    // Remove hora do objeto pois não existe no banco
    const { hora, ...dataToSubmit } = formData;

    const submitData = {
      ...dataToSubmit,
      dentista_id: tipoProfissional === "Dentista" ? (formData.dentista_id || null) : null,
      protetico_id: tipoProfissional === "Protetico" ? (formData.protetico_id ? parseInt(formData.protetico_id) : null) : null,
      data_agendamento: dataAgendamento.toISOString(),
      convenio_id: formData.convenio_id === "particular" ? null : formData.convenio_id,
      valor: formData.valor || null,
    };

    await onSubmit(submitData);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {agendamento ? "Editar Agendamento" : "Novo Agendamento"}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2 col-span-2">
              <Label htmlFor="paciente_id">Paciente *</Label>
              <Select value={formData.paciente_id} onValueChange={(value) => setFormData({ ...formData, paciente_id: value })}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione o paciente" />
                </SelectTrigger>
                <SelectContent>
                  {pacientes.map((paciente) => (
                    <SelectItem key={paciente.id} value={paciente.id}>
                      {paciente.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2 col-span-2">
              <Label>Profissional</Label>
              <Select value={tipoProfissional} onValueChange={(val: "Dentista" | "Protetico") => setTipoProfissional(val)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Dentista">Dentista</SelectItem>
                  <SelectItem value="Protetico">Protético</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {tipoProfissional === "Dentista" ? (
              <div className="space-y-2 col-span-2">
                <Label htmlFor="dentista_id">Dentista *</Label>
                <Select value={formData.dentista_id} onValueChange={(value) => setFormData({ ...formData, dentista_id: value })}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione o dentista" />
                  </SelectTrigger>
                  <SelectContent>
                    {dentistas.map((dentista) => (
                      <SelectItem key={dentista.id} value={dentista.id}>
                        {dentista.nome} - {dentista.especialidade}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <div className="space-y-2 col-span-2">
                <Label htmlFor="protetico_id">Protético *</Label>
                <Select value={formData.protetico_id} onValueChange={(value) => setFormData({ ...formData, protetico_id: value })}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione o protético" />
                  </SelectTrigger>
                  <SelectContent>
                    {proteticos.map((protetico: any) => (
                      <SelectItem key={protetico.id} value={protetico.id.toString()}>
                        {protetico.nome} {protetico.laboratorio ? `- ${protetico.laboratorio}` : ''}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="space-y-2">
              <Label>Data *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.data_agendamento && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.data_agendamento ? format(formData.data_agendamento, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.data_agendamento}
                    onSelect={(date) => date && setFormData({ ...formData, data_agendamento: date })}
                    initialFocus
                    className="pointer-events-auto"
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label htmlFor="hora">Horário *</Label>
              <Select 
                value={formData.hora} 
                onValueChange={(value) => setFormData({ ...formData, hora: value })}
                disabled={!(tipoProfissional === "Dentista" ? formData.dentista_id : formData.protetico_id) || !formData.data_agendamento}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione o horário" />
                </SelectTrigger>
                <SelectContent>
                  {horariosDisponiveis.length === 0 ? (
                    <SelectItem value="none" disabled>
                      {!formData.data_agendamento 
                        ? "Selecione uma data primeiro" 
                        : "Nenhum horário configurado para este dia"}
                    </SelectItem>
                  ) : (
                    horariosDisponiveis.map((horario) => (
                      <SelectItem key={horario} value={horario}>
                        {horario}
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
              {!formData.dentista_id && tipoProfissional === "Dentista" && (
                <p className="text-xs text-muted-foreground">
                  Selecione um dentista primeiro
                </p>
              )}
              {((tipoProfissional === "Dentista" && formData.dentista_id) || (tipoProfissional === "Protetico" && formData.protetico_id)) && formData.data_agendamento && horariosDisponiveis.length === 0 && (
                <p className="text-xs text-destructive">
                  Nenhum horário disponível para este dia. Configure os horários na agenda do profissional ou clínica.
                </p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="duracao">Duração (min) *</Label>
              <Input
                id="duracao"
                type="number"
                min="15"
                step="15"
                value={formData.duracao}
                onChange={(e) => setFormData({ ...formData, duracao: parseInt(e.target.value) })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="tipo_atendimento">Tipo de Atendimento *</Label>
              <Select value={formData.tipo_atendimento} onValueChange={(value) => setFormData({ ...formData, tipo_atendimento: value })}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Consulta">Consulta</SelectItem>
                  <SelectItem value="Retorno">Retorno</SelectItem>
                  <SelectItem value="Emergência">Emergência</SelectItem>
                  <SelectItem value="Procedimento">Procedimento</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="procedimento">Procedimento *</Label>
              <Input
                id="procedimento"
                value={formData.procedimento}
                onChange={(e) => setFormData({ ...formData, procedimento: e.target.value })}
                placeholder="Ex: Limpeza, Obturação, etc."
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="status">Status *</Label>
              <Select value={formData.status} onValueChange={(value) => setFormData({ ...formData, status: value })}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Agendado">Agendado</SelectItem>
                  <SelectItem value="Confirmado">Confirmado</SelectItem>
                  <SelectItem value="Realizado">Realizado</SelectItem>
                  <SelectItem value="Cancelado">Cancelado</SelectItem>
                  <SelectItem value="Faltou">Faltou</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="convenio_id">Convênio</Label>
              <Select value={formData.convenio_id} onValueChange={(value) => setFormData({ ...formData, convenio_id: value })}>
                <SelectTrigger>
                  <SelectValue placeholder="Particular" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="particular">Particular</SelectItem>
                  {convenios.map((convenio) => (
                    <SelectItem key={convenio.id} value={convenio.id}>
                      {convenio.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="valor">Valor (R$)</Label>
              <Input
                id="valor"
                type="number"
                step="0.01"
                min="0"
                value={formData.valor}
                onChange={(e) => setFormData({ ...formData, valor: parseFloat(e.target.value) || 0 })}
              />
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
              />
            </div>
          </div>

          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button type="submit">
              {agendamento ? "Atualizar" : "Cadastrar"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React from 'react';
import { AlertCircle, Package, Clock, Calendar, CheckCircle2 } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { useNavigate } from 'react-router-dom';

interface DashboardAlertsProps {
  stats: {
    osAtrasadas: number;
    produtosFalta: number;
    agendamentosHoje: { total: number; pendentes: number };
  };
  isLoading: boolean;
}

interface AlertItem {
  id: string;
  title: string;
  description: string;
  icon: any;
  variant: 'destructive' | 'warning' | 'medical';
  action: () => void;
  actionLabel: string;
}

export function DashboardAlerts({ stats, isLoading }: DashboardAlertsProps) {
  const navigate = useNavigate();

  if (isLoading) return null;

  const alerts: AlertItem[] = [];

  // Alerta de OS Atrasadas
  if (stats.osAtrasadas > 0) {
    alerts.push({
      id: 'os-atrasadas',
      title: 'Atenção: Ordens de Serviço Atrasadas',
      description: `Existem ${stats.osAtrasadas} ordens de serviço com data de entrega vencida.`,
      icon: Clock,
      variant: 'destructive',
      action: () => navigate('/procedimentos'),
      actionLabel: 'Ver Procedimentos'
    });
  }

  // Alerta de Estoque
  if (stats.produtosFalta > 0) {
    alerts.push({
      id: 'estoque-baixo',
      title: 'Reposição Necessária',
      description: `${stats.produtosFalta} itens do estoque estão abaixo do nível mínimo recomendado.`,
      icon: Package,
      variant: 'warning',
      action: () => navigate('/estoque'),
      actionLabel: 'Gerenciar Estoque'
    });
  }

  // Alerta de Agendamentos Pendentes (se for começo do dia ou houver muitos)
  if (stats.agendamentosHoje.pendentes > 0) {
    alerts.push({
      id: 'agendamentos-pendentes',
      title: 'Confirmações Pendentes',
      description: `Ainda existem ${stats.agendamentosHoje.pendentes} pacientes que não confirmaram consulta hoje.`,
      icon: Calendar,
      variant: 'medical',
      action: () => navigate('/appointments'),
      actionLabel: 'Ver Agenda'
    });
  }

  if (alerts.length === 0) {
    return (
      <div className="flex items-center gap-3 p-4 bg-green-50 border border-green-200 rounded-xl mb-6">
        <div className="p-2 bg-green-500 rounded-full">
          <CheckCircle2 className="w-5 h-5 text-white" />
        </div>
        <div>
          <h3 className="font-semibold text-green-800">Tudo em dia!</h3>
          <p className="text-sm text-green-600">Não existem alertas críticos ou urgências no momento.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 mb-8">
      {alerts.map((alert) => (
        <Alert 
          key={alert.id} 
          className={`border-2 shadow-sm animate-in fade-in slide-in-from-top-4 duration-300 ${
            alert.variant === 'destructive' ? 'border-red-200 bg-red-50' : 
            alert.variant === 'warning' ? 'border-orange-200 bg-orange-50' : 
            'border-blue-200 bg-blue-50'
          }`}
        >
          <alert.icon className={`h-5 w-5 ${
            alert.variant === 'destructive' ? 'text-red-600' : 
            alert.variant === 'warning' ? 'text-orange-600' : 
            'text-blue-600'
          }`} />
          <div className="ml-2 flex-1">
            <AlertTitle className={`font-bold ${
              alert.variant === 'destructive' ? 'text-red-800' : 
              alert.variant === 'warning' ? 'text-orange-800' : 
              'text-blue-800'
            }`}>
              {alert.title}
            </AlertTitle>
            <AlertDescription className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mt-1">
              <span className="text-gray-700">{alert.description}</span>
              <Button 
                variant="outline" 
                size="sm" 
                onClick={alert.action}
                className="h-8 border-current hover:bg-current hover:text-white transition-all font-semibold"
              >
                {alert.actionLabel}
              </Button>
            </AlertDescription>
          </div>
        </Alert>
      ))}
    </div>
  );
}

import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { type Estoque } from "@/hooks/useEstoque";

const estoqueSchema = z.object({
  item: z.string().min(1, "Item é obrigatório").max(200, "Nome muito longo"),
  codigo: z.string().min(1, "Código é obrigatório").max(50, "Código muito longo"),
  categoria: z.string().min(1, "Categoria é obrigatória"),
  estoque: z.string().min(1, "Quantidade é obrigatória"),
  minimo: z.string().min(1, "Estoque mínimo é obrigatório"),
  maximo: z.string().min(1, "Estoque máximo é obrigatório"),
  valor_unitario: z.string().min(1, "Valor unitário é obrigatório"),
  observacoes: z.string().optional(),
});

type EstoqueFormData = z.infer<typeof estoqueSchema>;

interface EstoqueFormProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: any) => void;
  estoque?: Estoque | null;
}

export function EstoqueForm({
  open,
  onClose,
  onSubmit,
  estoque,
}: EstoqueFormProps) {
  const form = useForm<EstoqueFormData>({
    resolver: zodResolver(estoqueSchema),
    defaultValues: {
      item: "",
      codigo: "",
      categoria: "",
      estoque: "",
      minimo: "",
      maximo: "",
      valor_unitario: "",
      observacoes: "",
    },
  });

  // Reset form when estoque changes
  useEffect(() => {
    if (open) {
      form.reset({
        item: estoque?.item || "",
        codigo: estoque?.codigo || "",
        categoria: estoque?.categoria || "",
        estoque: estoque?.estoque?.toString() || "",
        minimo: estoque?.minimo?.toString() || "",
        maximo: estoque?.maximo?.toString() || "",
        valor_unitario: estoque?.valor_unitario?.toString() || "",
        observacoes: estoque?.observacoes || "",
      });
    }
  }, [open, estoque, form]);

  const handleSubmit = (data: EstoqueFormData) => {
    onSubmit({
      ...data,
      estoque: parseInt(data.estoque),
      minimo: parseInt(data.minimo),
      maximo: parseInt(data.maximo),
      valor_unitario: parseFloat(data.valor_unitario),
      ...(estoque?.id && { id: estoque.id }),
    });
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {estoque ? "Editar Item" : "Novo Item"}
          </DialogTitle>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="item"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Item *</FormLabel>
                  <FormControl>
                    <Input placeholder="Nome do item" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="codigo"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Código *</FormLabel>
                    <FormControl>
                      <Input placeholder="Ex: EST-001" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="categoria"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Categoria *</FormLabel>
                    <Select
                      onValueChange={field.onChange}
                      value={field.value}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Selecione" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="Restaurador">Restaurador</SelectItem>
                        <SelectItem value="Anestésico">Anestésico</SelectItem>
                        <SelectItem value="EPI">EPI</SelectItem>
                        <SelectItem value="Descartável">Descartável</SelectItem>
                        <SelectItem value="Instrumental">Instrumental</SelectItem>
                        <SelectItem value="Biossegurança">Biossegurança</SelectItem>
                        <SelectItem value="Outro">Outro</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <FormField
                control={form.control}
                name="estoque"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Quantidade Atual *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        placeholder="0"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="minimo"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Estoque Mínimo *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        placeholder="0"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="maximo"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Estoque Máximo *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        placeholder="0"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="valor_unitario"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Valor Unitário (R$) *</FormLabel>
                  <FormControl>
                    <Input
                      type="number"
                      step="0.01"
                      placeholder="0.00"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="observacoes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Observações</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="Informações adicionais..."
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-2">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit">
                {estoque ? "Atualizar" : "Cadastrar"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { Cheque } from "@/hooks/useCheques";

interface ChequeFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: any) => Promise<void>;
  cheque?: Cheque | null;
}

export function ChequeForm({ open, onOpenChange, onSubmit, cheque }: ChequeFormProps) {
  const [formData, setFormData] = useState({
    numero_cheque: "",
    banco: "",
    agencia: "",
    conta: "",
    emitente: "",
    cpf_cnpj: "",
    valor: 0,
    data_emissao: new Date(),
    data_vencimento: new Date(),
    data_compensacao: undefined as Date | undefined,
    status: "A Compensar" as "A Compensar" | "Compensado" | "Devolvido" | "Cancelado",
    observacoes: "",
  });

  useEffect(() => {
    if (cheque) {
      setFormData({
        numero_cheque: cheque.numero_cheque,
        banco: cheque.banco,
        agencia: cheque.agencia,
        conta: cheque.conta,
        emitente: cheque.emitente,
        cpf_cnpj: cheque.cpf_cnpj || "",
        valor: cheque.valor,
        data_emissao: new Date(cheque.data_emissao),
        data_vencimento: new Date(cheque.data_vencimento),
        data_compensacao: cheque.data_compensacao ? new Date(cheque.data_compensacao) : undefined,
        status: cheque.status,
        observacoes: cheque.observacoes || "",
      });
    } else {
      setFormData({
        numero_cheque: "",
        banco: "",
        agencia: "",
        conta: "",
        emitente: "",
        cpf_cnpj: "",
        valor: 0,
        data_emissao: new Date(),
        data_vencimento: new Date(),
        data_compensacao: undefined,
        status: "A Compensar",
        observacoes: "",
      });
    }
  }, [cheque]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const submitData = {
      ...formData,
      cpf_cnpj: formData.cpf_cnpj || undefined,
      data_emissao: format(formData.data_emissao, 'yyyy-MM-dd'),
      data_vencimento: format(formData.data_vencimento, 'yyyy-MM-dd'),
      data_compensacao: formData.data_compensacao ? format(formData.data_compensacao, 'yyyy-MM-dd') : undefined,
      observacoes: formData.observacoes || undefined,
    };

    await onSubmit(submitData);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {cheque ? "Editar Cheque" : "Novo Cheque"}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="numero_cheque">Número do Cheque *</Label>
              <Input
                id="numero_cheque"
                value={formData.numero_cheque}
                onChange={(e) => setFormData({ ...formData, numero_cheque: e.target.value })}
                placeholder="Ex: 123456"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="valor">Valor (R$) *</Label>
              <Input
                id="valor"
                type="number"
                step="0.01"
                min="0.01"
                value={formData.valor}
                onChange={(e) => setFormData({ ...formData, valor: parseFloat(e.target.value) || 0 })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="banco">Banco *</Label>
              <Input
                id="banco"
                value={formData.banco}
                onChange={(e) => setFormData({ ...formData, banco: e.target.value })}
                placeholder="Ex: Banco do Brasil"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="agencia">Agência *</Label>
              <Input
                id="agencia"
                value={formData.agencia}
                onChange={(e) => setFormData({ ...formData, agencia: e.target.value })}
                placeholder="Ex: 1234-5"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="conta">Conta *</Label>
              <Input
                id="conta"
                value={formData.conta}
                onChange={(e) => setFormData({ ...formData, conta: e.target.value })}
                placeholder="Ex: 12345-6"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="emitente">Emitente *</Label>
              <Input
                id="emitente"
                value={formData.emitente}
                onChange={(e) => setFormData({ ...formData, emitente: e.target.value })}
                placeholder="Nome do emitente"
                required
              />
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="cpf_cnpj">CPF/CNPJ</Label>
              <Input
                id="cpf_cnpj"
                value={formData.cpf_cnpj}
                onChange={(e) => setFormData({ ...formData, cpf_cnpj: e.target.value })}
                placeholder="CPF ou CNPJ do emitente"
              />
            </div>

            <div className="space-y-2">
              <Label>Data de Emissão *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.data_emissao && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.data_emissao ? format(formData.data_emissao, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.data_emissao}
                    onSelect={(date) => date && setFormData({ ...formData, data_emissao: date })}
                    locale={ptBR}
                    initialFocus
                    className="pointer-events-auto"
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label>Data de Vencimento *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.data_vencimento && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.data_vencimento ? format(formData.data_vencimento, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.data_vencimento}
                    onSelect={(date) => date && setFormData({ ...formData, data_vencimento: date })}
                    locale={ptBR}
                    initialFocus
                    className="pointer-events-auto"
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label htmlFor="status">Status *</Label>
              <Select value={formData.status} onValueChange={(value: any) => setFormData({ ...formData, status: value })} required>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="A Compensar">A Compensar</SelectItem>
                  <SelectItem value="Compensado">Compensado</SelectItem>
                  <SelectItem value="Devolvido">Devolvido</SelectItem>
                  <SelectItem value="Cancelado">Cancelado</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {(formData.status === "Compensado" || formData.data_compensacao) && (
              <div className="space-y-2">
                <Label>Data de Compensação</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left font-normal",
                        !formData.data_compensacao && "text-muted-foreground"
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4" />
                      {formData.data_compensacao ? format(formData.data_compensacao, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0">
                    <Calendar
                      mode="single"
                      selected={formData.data_compensacao}
                      onSelect={(date) => setFormData({ ...formData, data_compensacao: date })}
                      locale={ptBR}
                      initialFocus
                      className="pointer-events-auto"
                    />
                  </PopoverContent>
                </Popover>
              </div>
            )}

            <div className="space-y-2 col-span-2">
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
              />
            </div>
          </div>

          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button type="submit">
              {cheque ? "Atualizar" : "Cadastrar"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { Comissao } from "@/hooks/useComissoes";
import { useDentistas } from "@/hooks/useDentistas";

interface ComissaoFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: any) => Promise<void>;
  comissao?: Comissao | null;
}

const formasPagamento = [
  "Dinheiro",
  "PIX",
  "Cartão de Crédito",
  "Cartão de Débito",
  "Boleto",
  "Transferência"
];

export function ComissaoForm({ open, onOpenChange, onSubmit, comissao }: ComissaoFormProps) {
  const { dentistas } = useDentistas();

  const [formData, setFormData] = useState({
    dentista_id: "",
    referencia: "",
    valor_total_procedimentos: 0,
    percentual_comissao: 0,
    valor_comissao: 0,
    data_inicio: new Date(),
    data_fim: new Date(),
    status: "Pendente" as "Pendente" | "Paga" | "Cancelada",
    data_pagamento: undefined as Date | undefined,
    forma_pagamento: "",
    observacoes: "",
  });

  useEffect(() => {
    if (comissao) {
      setFormData({
        dentista_id: comissao.dentista_id,
        referencia: comissao.referencia,
        valor_total_procedimentos: comissao.valor_total_procedimentos,
        percentual_comissao: comissao.percentual_comissao,
        valor_comissao: comissao.valor_comissao,
        data_inicio: new Date(comissao.data_inicio),
        data_fim: new Date(comissao.data_fim),
        status: comissao.status,
        data_pagamento: comissao.data_pagamento ? new Date(comissao.data_pagamento) : undefined,
        forma_pagamento: comissao.forma_pagamento || "",
        observacoes: comissao.observacoes || "",
      });
    } else {
      setFormData({
        dentista_id: "",
        referencia: "",
        valor_total_procedimentos: 0,
        percentual_comissao: 0,
        valor_comissao: 0,
        data_inicio: new Date(),
        data_fim: new Date(),
        status: "Pendente",
        data_pagamento: undefined,
        forma_pagamento: "",
        observacoes: "",
      });
    }
  }, [comissao]);

  // Calcular valor da comissão automaticamente
  useEffect(() => {
    const valorComissao = (formData.valor_total_procedimentos * formData.percentual_comissao) / 100;
    setFormData(prev => ({ ...prev, valor_comissao: valorComissao }));
  }, [formData.valor_total_procedimentos, formData.percentual_comissao]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const submitData = {
      ...formData,
      data_inicio: format(formData.data_inicio, 'yyyy-MM-dd'),
      data_fim: format(formData.data_fim, 'yyyy-MM-dd'),
      data_pagamento: formData.data_pagamento ? format(formData.data_pagamento, 'yyyy-MM-dd') : undefined,
      forma_pagamento: formData.forma_pagamento || undefined,
      observacoes: formData.observacoes || undefined,
    };

    await onSubmit(submitData);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {comissao ? "Editar Comissão" : "Nova Comissão"}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2 col-span-2">
              <Label htmlFor="dentista_id">Dentista *</Label>
              <Select value={formData.dentista_id} onValueChange={(value) => setFormData({ ...formData, dentista_id: value })} required>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione o dentista" />
                </SelectTrigger>
                <SelectContent>
                  {dentistas.map((dentista) => (
                    <SelectItem key={dentista.id} value={dentista.id}>
                      {dentista.nome} - {dentista.especialidade}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="referencia">Referência *</Label>
              <Input
                id="referencia"
                value={formData.referencia}
                onChange={(e) => setFormData({ ...formData, referencia: e.target.value })}
                placeholder="Ex: Janeiro/2025"
                required
              />
            </div>

            <div className="space-y-2">
              <Label>Período - Data Início *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.data_inicio && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.data_inicio ? format(formData.data_inicio, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.data_inicio}
                    onSelect={(date) => date && setFormData({ ...formData, data_inicio: date })}
                    initialFocus
                    className="pointer-events-auto"
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label>Período - Data Fim *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.data_fim && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.data_fim ? format(formData.data_fim, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.data_fim}
                    onSelect={(date) => date && setFormData({ ...formData, data_fim: date })}
                    initialFocus
                    className="pointer-events-auto"
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label htmlFor="valor_total_procedimentos">Valor Total Procedimentos (R$) *</Label>
