        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { FluxoCaixa } from "@/hooks/useFluxoCaixa";

interface FluxoCaixaFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: any) => Promise<void>;
  movimentacao?: FluxoCaixa | null;
}

const categoriasEntrada = [
  "Consulta",
  "Tratamento",
  "Ortodontia",
  "Implante",
  "Prótese",
  "Outros Recebimentos"
];

const categoriasSaida = [
  "Aluguel",
  "Água",
  "Luz",
  "Internet",
  "Telefone",
  "Material Odontológico",
  "Laboratório",
  "Salários",
  "Impostos",
  "Manutenção",
  "Limpeza",
  "Marketing",
  "Outras Despesas"
];

const formasPagamento = [
  "Dinheiro",
  "PIX",
  "Cartão de Crédito",
  "Cartão de Débito",
  "Boleto",
  "Transferência"
];

export function FluxoCaixaForm({ open, onOpenChange, onSubmit, movimentacao }: FluxoCaixaFormProps) {
  const [formData, setFormData] = useState({
    tipo: "Entrada" as "Entrada" | "Saída",
    descricao: "",
    categoria: "",
    valor: 0,
    data_movimentacao: new Date(),
    forma_pagamento: "",
    observacoes: "",
  });

  useEffect(() => {
    if (movimentacao) {
      setFormData({
        tipo: movimentacao.tipo,
        descricao: movimentacao.descricao,
        categoria: movimentacao.categoria,
        valor: movimentacao.valor,
        data_movimentacao: new Date(movimentacao.data_movimentacao),
        forma_pagamento: movimentacao.forma_pagamento || "",
        observacoes: movimentacao.observacoes || "",
      });
    } else {
      setFormData({
        tipo: "Entrada",
        descricao: "",
        categoria: "",
        valor: 0,
        data_movimentacao: new Date(),
        forma_pagamento: "",
        observacoes: "",
      });
    }
  }, [movimentacao]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const submitData = {
      ...formData,
      data_movimentacao: format(formData.data_movimentacao, 'yyyy-MM-dd'),
      forma_pagamento: formData.forma_pagamento || undefined,
      observacoes: formData.observacoes || undefined,
    };

    await onSubmit(submitData);
    onOpenChange(false);
  };

  const categorias = formData.tipo === "Entrada" ? categoriasEntrada : categoriasSaida;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {movimentacao ? "Editar Movimentação" : "Nova Movimentação"}
          </DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="tipo">Tipo *</Label>
              <Select value={formData.tipo} onValueChange={(value: "Entrada" | "Saída") => setFormData({ ...formData, tipo: value, categoria: "" })} required>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Entrada">Entrada</SelectItem>
                  <SelectItem value="Saída">Saída</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="categoria">Categoria *</Label>
              <Select value={formData.categoria} onValueChange={(value) => setFormData({ ...formData, categoria: value })} required>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione a categoria" />
                </SelectTrigger>
                <SelectContent>
                  {categorias.map((cat) => (
                    <SelectItem key={cat} value={cat}>
                      {cat}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="descricao">Descrição *</Label>
              <Input
                id="descricao"
                value={formData.descricao}
                onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
                placeholder="Ex: Recebimento de consulta"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="valor">Valor (R$) *</Label>
              <Input
                id="valor"
                type="number"
                step="0.01"
                min="0.01"
                value={formData.valor}
                onChange={(e) => setFormData({ ...formData, valor: parseFloat(e.target.value) || 0 })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label>Data *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.data_movimentacao && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.data_movimentacao ? format(formData.data_movimentacao, "PPP", { locale: ptBR }) : <span>Selecione a data</span>}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.data_movimentacao}
                    onSelect={(date) => date && setFormData({ ...formData, data_movimentacao: date })}
                    locale={ptBR}
                    initialFocus
                    className="pointer-events-auto"
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="forma_pagamento">Forma de Pagamento</Label>
              <Select value={formData.forma_pagamento} onValueChange={(value) => setFormData({ ...formData, forma_pagamento: value })}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione" />
                </SelectTrigger>
                <SelectContent>
                  {formasPagamento.map((forma) => (
                    <SelectItem key={forma} value={forma}>
                      {forma}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
              />
            </div>
          </div>

          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button type="submit">
              {movimentacao ? "Atualizar" : "Cadastrar"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { type Laboratorio } from "@/hooks/useLaboratorio";

const laboratorioSchema = z.object({
  paciente: z.string().min(1, "Paciente é obrigatório").max(200, "Nome muito longo"),
  procedimento: z.string().min(1, "Procedimento é obrigatório").max(200, "Procedimento muito longo"),
  laboratorio: z.string().min(1, "Laboratório é obrigatório").max(200, "Nome muito longo"),
  data_envio: z.string().min(1, "Data de envio é obrigatória"),
  data_retorno: z.string().min(1, "Data de retorno é obrigatória"),
  status: z.string().min(1, "Status é obrigatório"),
  valor: z.string().min(1, "Valor é obrigatório"),
  observacoes: z.string().optional(),
});

type LaboratorioFormData = z.infer<typeof laboratorioSchema>;

interface LaboratorioFormProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: any) => void;
  laboratorio?: Laboratorio | null;
}

export function LaboratorioForm({
  open,
  onClose,
  onSubmit,
  laboratorio,
}: LaboratorioFormProps) {
  const form = useForm<LaboratorioFormData>({
    resolver: zodResolver(laboratorioSchema),
    defaultValues: {
      paciente: "",
      procedimento: "",
      laboratorio: "",
      data_envio: "",
      data_retorno: "",
      status: "Enviado",
      valor: "",
      observacoes: "",
    },
  });

  // Reset form when laboratorio changes
  useEffect(() => {
    if (open) {
      form.reset({
        paciente: laboratorio?.paciente || "",
        procedimento: laboratorio?.procedimento || "",
        laboratorio: laboratorio?.laboratorio || "",
        data_envio: laboratorio?.data_envio || "",
        data_retorno: laboratorio?.data_retorno || "",
        status: laboratorio?.status || "Enviado",
        valor: laboratorio?.valor?.toString() || "",
        observacoes: laboratorio?.observacoes || "",
      });
    }
  }, [open, laboratorio, form]);

  const handleSubmit = (data: LaboratorioFormData) => {
    onSubmit({
      ...data,
      valor: parseFloat(data.valor),
      ...(laboratorio?.id && { id: laboratorio.id }),
    });
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {laboratorio ? "Editar Serviço" : "Novo Serviço"}
          </DialogTitle>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="paciente"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Paciente *</FormLabel>
                  <FormControl>
                    <Input placeholder="Nome do paciente" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="procedimento"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Procedimento *</FormLabel>
                    <FormControl>
                      <Input placeholder="Ex: Prótese Total" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="laboratorio"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Laboratório *</FormLabel>
                    <FormControl>
                      <Input placeholder="Nome do laboratório" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="data_envio"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Data de Envio *</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="data_retorno"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Data de Retorno *</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="status"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Status *</FormLabel>
                    <Select
                      onValueChange={field.onChange}
                      value={field.value}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Selecione" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="Enviado">Enviado</SelectItem>
                        <SelectItem value="Em Produção">Em Produção</SelectItem>
                        <SelectItem value="Concluído">Concluído</SelectItem>
                        <SelectItem value="Cancelado">Cancelado</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="valor"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Valor (R$) *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        step="0.01"
                        placeholder="0.00"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="observacoes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Observações</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="Informações adicionais..."
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-2">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit">
                {laboratorio ? "Atualizar" : "Cadastrar"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Search, User, LogOut, Calendar, Users, Loader2, Home, Bell, AlertTriangle, CheckCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SidebarTrigger } from "@/components/ui/sidebar";
import { ThemeToggle } from "@/components/ui/theme-toggle";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import { useNavigate, Link } from "react-router-dom";
import { useProfile } from "@/hooks/useProfile";
import { useGlobalSearch } from "@/hooks/useGlobalSearch";
import { useNotificacoes } from "@/hooks/useNotificacoes";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";

// Dashboard header component with authentication
export function DashboardHeader() {
  const { signOut, user } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { profile } = useProfile();
  const [searchQuery, setSearchQuery] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const { results, isLoading } = useGlobalSearch(searchQuery);
  const { data: notificacoes = [] } = useNotificacoes();

  const handleSignOut = async () => {
    try {
      await signOut();
      toast({
        title: "Logout realizado",
        description: "Até logo!",
      });
      // Força navegação para tela de login
      navigate("/auth", { replace: true });
    } catch (error) {
      toast({
        title: "Erro ao fazer logout",
        description: "Tente novamente",
        variant: "destructive",
      });
    }
  };

  const handleResultClick = (result: any) => {
    if (result.type === "paciente") {
      navigate("/patients");
    } else if (result.type === "agendamento") {
      navigate("/appointments");
    }
    setSearchQuery("");
    setSearchOpen(false);
  };
    return (
      <header className="h-14 sm:h-16 border-b border-border/50 glass sticky top-0 z-10 transition-all duration-200">
        <div className="flex items-center justify-between h-full px-3 sm:px-4 md:px-6">
          <div className="flex items-center gap-2 sm:gap-4">
            <SidebarTrigger className="hover-scale" />
            <Button
              variant="ghost"
              size="sm"
              onClick={() => navigate("/")}
              className="gap-2 hover-scale"
            >
              <Home className="w-4 h-4" />
              <span className="hidden sm:inline">Menu Principal</span>
            </Button>
            <div className="hidden md:flex items-center gap-2 max-w-md w-full">
              <Popover open={searchOpen} onOpenChange={setSearchOpen}>
                <PopoverTrigger asChild>
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground w-4 h-4" />
                    <Input
                      placeholder="Buscar pacientes, agendamentos..."
                      className="pl-9 bg-background"
                      value={searchQuery}
                      onChange={(e) => {
                        setSearchQuery(e.target.value);
                        setSearchOpen(e.target.value.length >= 2);
                      }}
                      onFocus={() => {
                        if (searchQuery.length >= 2) {
                          setSearchOpen(true);
                        }
                      }}
                    />
                  </div>
                </PopoverTrigger>
                <PopoverContent className="w-96 p-0" align="start">
                  <div className="max-h-96 overflow-y-auto">
                    {isLoading ? (
                      <div className="flex items-center justify-center p-4">
                        <Loader2 className="w-5 h-5 animate-spin text-muted-foreground" />
                      </div>
                    ) : results.length === 0 ? (
                      <div className="p-4 text-sm text-muted-foreground text-center">
                        {searchQuery.length >= 2
                          ? "Nenhum resultado encontrado"
                          : "Digite ao menos 2 caracteres"}
                      </div>
                    ) : (
                      <div className="py-2">
                        {results.map((result) => (
                          <button
                            key={result.id}
                            onClick={() => handleResultClick(result)}
                            className={cn(
                              "w-full px-4 py-3 text-left hover:bg-accent transition-colors",
                              "flex items-start gap-3 border-b border-border last:border-0"
                            )}
                          >
                            <div className="mt-0.5">
                              {result.type === "paciente" ? (
                                <Users className="w-4 h-4 text-primary" />
                              ) : (
                                <Calendar className="w-4 h-4 text-primary" />
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="font-medium text-sm truncate">
                                {result.title}
                              </div>
                              {result.subtitle && (
                                <div className="text-xs text-muted-foreground truncate">
                                  {result.subtitle}
                                </div>
                              )}
                            </div>
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </PopoverContent>
              </Popover>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
            {/* Notificações */}
            <Popover open={notifOpen} onOpenChange={setNotifOpen}>
              <PopoverTrigger asChild>
                <Button variant="ghost" size="icon" className="relative hover:bg-muted/50 transition-colors">
                  <Bell className="w-5 h-5 text-gray-600" />
                  {notificacoes.length > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4 shrink-0 -translate-y-1/2 translate-x-1/2 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white shadow ring-2 ring-white">
                      {notificacoes.length}
                    </span>
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-80 p-0 mr-4" align="end">
                <div className="flex items-center justify-between p-4 border-b">
                  <h4 className="font-semibold flex items-center gap-2">
                    <Bell className="w-4 h-4" /> Notificações
                  </h4>
                  <Badge variant="secondary" className="bg-red-100 text-red-700 hover:bg-red-100">{notificacoes.length} novas</Badge>
                </div>
                <div className="max-h-80 overflow-y-auto">
                  {notificacoes.length === 0 ? (
                    <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
