                        >
                          <div className={`mt-1 flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${notif.tipo === 'FALTA' ? 'bg-orange-100 text-orange-600' : 'bg-red-100 text-red-600'}`}>
