                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent className="w-56" align="end" forceMount>
                <DropdownMenuLabel className="font-normal">
                  <div className="flex flex-col space-y-1">
                    <p className="text-sm font-medium leading-none">
                      {profile?.nome_exibicao || 'Usuário'}
                    </p>
                    <p className="text-xs leading-none text-muted-foreground truncate">
                      {user?.email}
                    </p>
                  </div>
                </DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuItem asChild>
                  <Link to="/profile">
                    <User className="mr-2 h-4 w-4" />
                    <span>Perfil</span>
                  </Link>
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem className="text-destructive" onClick={handleSignOut}>
                  <LogOut className="mr-2 h-4 w-4" />
                  <span>Sair</span>
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
      </header>
    );
}

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Download, ShieldCheck, Loader2 } from 'lucide-react';
import { Paciente } from '@/hooks/usePacientes';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

interface ExportacaoLGPDProps {
  paciente: Paciente;
}

export function ExportacaoLGPD({ paciente }: ExportacaoLGPDProps) {
  const [isExporting, setIsExporting] = useState(false);
  const { user } = useAuth();

  const handleExport = async () => {
    setIsExporting(true);

    try {
      // Registrar log de auditoria no supabase
      const supabaseAny = supabase as any;
      const { error: logError } = await supabaseAny
        .from('auditoria')
        .insert([{
          user_id: user?.id,
          acao: 'EXPORTACAO_DADOS_LGPD',
          tabela: 'pacientes',
          registro_id: paciente.id,
          detalhes: `Exportação de dados solicitada pelo titular (LGPD Art. 18)`,
          ip_address: null, // Obtido backend-side via trigger
        }]);

        if (logError && logError.code !== '42P01') { 
            console.warn("Auditoria não disponível nativamente ou tabela ausente, mas exportação continua", logError);
        }

      // Preparar os dados (Num cenário real, puxaria também de PRONTUÁRIOS e FOTOS)
      const dataToExport = {
        dados_pessoais: {
          nome: paciente.nome,
          email: paciente.email,
          telefone: paciente.telefone,
          cpf: paciente.cpf || 'Não informado',
          endereco: paciente.endereco || 'Não informado',
          data_nascimento: paciente.data_nascimento || 'Não informado',
        },
        conformidade_lgpd: {
          aceite_termos: (paciente as any).aceitou_lgpd ? 'Sim' : 'Não',
          data_aceite: (paciente as any).data_aceite_lgpd || 'Não registrado',
          ip_aceite: (paciente as any).ip_aceite_lgpd || 'Não registrado',
        },
        historico_clinico: {
          ultima_consulta: paciente.ultima_consulta || 'Nenhuma',
          status_cadastro: paciente.status,
        },
        meta: {
          gerado_em: new Date().toISOString(),
          sistema: 'Odonto PRO - Exportador Titular de Dados',
          lei_referencia: 'Lei Geral de Proteção de Dados Pessoais (Lei nº 13.709/2018)'
        }
      };

      // Transformar para HTML para a impressão amigável ao paciente
      const htmlContent = `
        <!DOCTYPE html>
        <html>
        <head>
          <title>Relatório de Dados do Paciente - Odonto PRO</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 40px; color: #333; line-height: 1.6; }
            h1 { color: #2563eb; border-bottom: 2px solid #e5e7eb; padding-bottom: 10px; }
            h2 { color: #4b5563; margin-top: 30px; }
            .section { background: #f9fafb; padding: 20px; border-radius: 8px; margin-bottom: 20px; border: 1px solid #e5e7eb; }
            .row { display: flex; margin-bottom: 8px; }
            .label { font-weight: bold; width: 200px; color: #6b7280; }
            .value { flex: 1; color: #111827; font-weight: 500;}
            .footer { margin-top: 50px; font-size: 12px; color: #9ca3af; text-align: center; border-top: 1px solid #e5e7eb; padding-top: 20px;}
            @media print {
                body { margin: 0; padding: 20px; }
                .section { break-inside: avoid; }
                button { display: none; }
            }
          </style>
        </head>
        <body>
          <h1>Relatório de Dados do Titular (LGPD)</h1>
          <p>Documento gerado em atendimento ao <strong>Art. 18 da Lei nº 13.709/2018 (LGPD)</strong> referente aos direitos do titular.</p>

          <div class="section">
            <h2>Dados Pessoais</h2>
            <div class="row"><div class="label">Nome Completo:</div><div class="value">${dataToExport.dados_pessoais.nome}</div></div>
            <div class="row"><div class="label">CPF:</div><div class="value">${dataToExport.dados_pessoais.cpf}</div></div>
            <div class="row"><div class="label">Email:</div><div class="value">${dataToExport.dados_pessoais.email}</div></div>
            <div class="row"><div class="label">Telefone:</div><div class="value">${dataToExport.dados_pessoais.telefone}</div></div>
            <div class="row"><div class="label">Endereço:</div><div class="value">${dataToExport.dados_pessoais.endereco}</div></div>
            <div class="row"><div class="label">Data de Nasc.:</div><div class="value">${dataToExport.dados_pessoais.data_nascimento}</div></div>
          </div>

          <div class="section">
            <h2>Histórico Clínico e Logs</h2>
            <div class="row"><div class="label">Status do Cadastro:</div><div class="value">${dataToExport.historico_clinico.status_cadastro}</div></div>
            <div class="row"><div class="label">Última Consulta:</div><div class="value">${dataToExport.historico_clinico.ultima_consulta}</div></div>
          </div>

          <div class="section">
            <h2>Conformidade e Sigilo</h2>
            <div class="row"><div class="label">Termos Aceitos:</div><div class="value">${dataToExport.conformidade_lgpd.aceite_termos}</div></div>
            <div class="row"><div class="label">Data de Registro:</div><div class="value">${dataToExport.conformidade_lgpd.data_aceite}</div></div>
            <div class="row"><div class="label">IP Localizador:</div><div class="value">${dataToExport.conformidade_lgpd.ip_aceite}</div></div>
          </div>

          <div class="footer">
            <p>Gerado por Odonto PRO Software. Emitido em ${new Date(dataToExport.meta.gerado_em).toLocaleString('pt-BR')}</p>
          </div>
          <script>
            window.onload = () => window.print();
          </script>
        </body>
        </html>
      `;

      // Abrir em nova janela para impressão como PDF via browser nativo
      const newWindow = window.open('', '_blank');
      if (newWindow) {
        newWindow.document.write(htmlContent);
        newWindow.document.close();
      } else {
          toast.info('Popup bloqueado. Por favor, permita popups para este site.');
      }

      toast.success('Relatório gerado com sucesso!');

    } catch (error) {
      console.error('Erro na exportação LGPD', error);
      toast.error('Ocorreu um erro ao processar os dados.');
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="bg-blue-50/50 border border-blue-200 rounded-lg p-4 flex flex-col sm:flex-row items-center justify-between gap-4 mt-6">
      <div className="flex items-start gap-3">
        <div className="p-2 bg-blue-100 rounded-full text-blue-600 shrink-0">
          <ShieldCheck className="h-5 w-5" />
        </div>
        <div>
          <h4 className="font-semibold text-blue-900">Portal de Privacidade (LGPD)</h4>
          <p className="text-sm text-blue-700 mt-1 max-w-xl">
            Exporte o prontuário completo, imagens e o histórico de dados como garantia legal aos direitos do titular. Esta ação será registrada por segurança.
          </p>
        </div>
      </div>
      <Button 
        onClick={handleExport}
        disabled={isExporting}
        variant="outline" 
        className="shrink-0 bg-white border-blue-300 text-blue-700 hover:bg-blue-50 w-full sm:w-auto"
      >
        {isExporting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Download className="mr-2 h-4 w-4" />}
        Extrair Documento
      </Button>
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { FileImage, Upload, Trash2, Edit } from "lucide-react";
import { usePacientes } from "@/hooks/usePacientes";
import { useRadiografias } from "@/hooks/useRadiografias";
import { useState, useRef } from "react";

export function Radiografias() {
  const { pacientes } = usePacientes();
  const [selectedPacienteId, setSelectedPacienteId] = useState<string>("");
  const { radiografias, loading, createRadiografia, updateRadiografia, deleteRadiografia } = useRadiografias(selectedPacienteId);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [laudoDialogOpen, setLaudoDialogOpen] = useState(false);
  const [selectedRadiografia, setSelectedRadiografia] = useState<any>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [newRadiografia, setNewRadiografia] = useState({
    titulo: "",
    tipo_exame: "",
    data_exame: "",
    laudo: "",
    observacoes: "",
    imagem_base64: "",
  });

  const [editLaudo, setEditLaudo] = useState("");

  const selectedPaciente = pacientes.find((p) => p.id === selectedPacienteId);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 50 * 1024 * 1024) {
        alert("Arquivo muito grande. Máximo 50MB");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setNewRadiografia((prev) => ({
          ...prev,
          imagem_base64: reader.result as string,
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    if (!selectedPacienteId || !newRadiografia.imagem_base64 || !newRadiografia.titulo) {
      return;
    }

    try {
      await createRadiografia({
        paciente_id: selectedPacienteId,
        ...newRadiografia,
      });
      setNewRadiografia({
        titulo: "",
        tipo_exame: "",
        data_exame: "",
        laudo: "",
        observacoes: "",
        imagem_base64: "",
      });
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
      setDialogOpen(false);
    } catch (error) {
      console.error("Erro ao salvar radiografia:", error);
    }
  };

  const handleSaveLaudo = async () => {
    if (!selectedRadiografia) return;

    try {
      await updateRadiografia(selectedRadiografia.id, {
        laudo: editLaudo,
      });
      setLaudoDialogOpen(false);
      setSelectedRadiografia(null);
      setEditLaudo("");
    } catch (error) {
      console.error("Erro ao salvar laudo:", error);
    }
  };

  const handleDelete = async () => {
    if (deleteId) {
      await deleteRadiografia(deleteId);
      setDeleteId(null);
    }
  };

  const openLaudoDialog = (radiografia: any) => {
    setSelectedRadiografia(radiografia);
    setEditLaudo(radiografia.laudo || "");
    setLaudoDialogOpen(true);
  };

  return (
    <div className="space-y-6">
      {/* Seletor de Paciente */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Selecionar Paciente</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="paciente">Paciente</Label>
            <Select value={selectedPacienteId} onValueChange={setSelectedPacienteId}>
              <SelectTrigger id="paciente">
                <SelectValue placeholder="Selecione um paciente" />
              </SelectTrigger>
              <SelectContent>
                {pacientes.map((paciente) => (
                  <SelectItem key={paciente.id} value={paciente.id}>
                    {paciente.nome}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {selectedPaciente && (
            <div className="p-4 bg-muted rounded-lg space-y-1">
              <p className="text-sm"><strong>Email:</strong> {selectedPaciente.email}</p>
              <p className="text-sm"><strong>Telefone:</strong> {selectedPaciente.telefone}</p>
              {selectedPaciente.cpf && <p className="text-sm"><strong>CPF:</strong> {selectedPaciente.cpf}</p>}
            </div>
          )}
        </CardContent>
      </Card>

      {selectedPacienteId && (
        <>
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h2 className="text-xl font-semibold">Radiografias</h2>
              <p className="text-sm text-muted-foreground">
                Exames radiográficos e laudos do paciente
              </p>
            </div>
            <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
              <DialogTrigger asChild>
                <Button>
                  <Upload className="w-4 h-4 mr-2" />
                  Adicionar Radiografia
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle>Adicionar Nova Radiografia</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <div>
                    <Label htmlFor="titulo">Título *</Label>
                    <Input
                      id="titulo"
                      value={newRadiografia.titulo}
                      onChange={(e) => setNewRadiografia({ ...newRadiografia, titulo: e.target.value })}
                      placeholder="Ex: Panorâmica Inicial"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="tipo_exame">Tipo de Exame</Label>
                      <Select value={newRadiografia.tipo_exame} onValueChange={(value) => setNewRadiografia({ ...newRadiografia, tipo_exame: value })}>
                        <SelectTrigger id="tipo_exame">
                          <SelectValue placeholder="Selecione o tipo" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Panorâmica">Panorâmica</SelectItem>
                          <SelectItem value="Telerradiografia Lateral">Telerradiografia Lateral</SelectItem>
                          <SelectItem value="Telerradiografia PA">Telerradiografia PA</SelectItem>
                          <SelectItem value="Periapical">Periapical</SelectItem>
                          <SelectItem value="Bite Wing">Bite Wing</SelectItem>
                          <SelectItem value="Oclusal">Oclusal</SelectItem>
                          <SelectItem value="Tomografia">Tomografia Computadorizada</SelectItem>
                          <SelectItem value="Ressonância">Ressonância Magnética</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div>
                      <Label htmlFor="data_exame">Data do Exame</Label>
                      <Input
                        id="data_exame"
                        type="date"
                        value={newRadiografia.data_exame}
                        onChange={(e) => setNewRadiografia({ ...newRadiografia, data_exame: e.target.value })}
                      />
                    </div>
                  </div>

                  <div>
                    <Label htmlFor="laudo">Laudo</Label>
                    <Textarea
                      id="laudo"
                      value={newRadiografia.laudo}
                      onChange={(e) => setNewRadiografia({ ...newRadiografia, laudo: e.target.value })}
                      placeholder="Laudo radiográfico detalhado..."
                      rows={4}
                    />
                  </div>

                  <div>
                    <Label htmlFor="observacoes">Observações</Label>
                    <Textarea
                      id="observacoes"
                      value={newRadiografia.observacoes}
                      onChange={(e) => setNewRadiografia({ ...newRadiografia, observacoes: e.target.value })}
                      placeholder="Observações adicionais..."
                      rows={2}
                    />
                  </div>

                  <div>
                    <Label htmlFor="imagem">Imagem * (Máx 50MB)</Label>
                    <div className="mt-2">
                      <Input
                        ref={fileInputRef}
                        id="imagem"
                        type="file"
                        accept="image/*"
                        onChange={handleFileChange}
                      />
                    </div>
                    {newRadiografia.imagem_base64 && (
                      <div className="mt-4">
                        <img
                          src={newRadiografia.imagem_base64}
                          alt="Preview"
                          className="max-h-64 rounded-lg mx-auto bg-black/90"
                        />
                      </div>
                    )}
                  </div>

                  <div className="flex justify-end gap-2">
                    <Button variant="outline" onClick={() => setDialogOpen(false)}>
                      Cancelar
                    </Button>
                    <Button 
                      onClick={handleSave}
                      disabled={!newRadiografia.titulo || !newRadiografia.imagem_base64 || loading}
                    >
                      Salvar Radiografia
                    </Button>
                  </div>
                </div>
              </DialogContent>
            </Dialog>
          </div>

          {/* Galeria de Radiografias */}
          {radiografias.length === 0 ? (
            <Card>
              <CardContent className="p-12 text-center">
                <FileImage className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <p className="text-muted-foreground">
                  Nenhuma radiografia adicionada ainda. Clique em "Adicionar Radiografia" para começar.
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {radiografias.map((radiografia) => (
                <Card key={radiografia.id} className="overflow-hidden">
                  <CardContent className="p-4 space-y-3">
                    <div className="aspect-square bg-black/90 rounded-lg overflow-hidden">
                      <img
                        src={radiografia.imagem_base64}
                        alt={radiografia.titulo}
                        className="w-full h-full object-contain cursor-pointer hover:scale-105 transition-transform"
                        onClick={() => window.open(radiografia.imagem_base64, '_blank')}
                      />
                    </div>
                    <div>
                      <div className="flex items-start justify-between mb-2 gap-2">
                        <h3 className="font-medium text-sm">{radiografia.titulo}</h3>
                        {radiografia.tipo_exame && (
                          <span className="text-xs px-2 py-1 bg-secondary text-secondary-foreground rounded shrink-0">
                            {radiografia.tipo_exame}
                          </span>
                        )}
                      </div>
                      {radiografia.data_exame && (
                        <p className="text-xs text-muted-foreground">
                          {new Date(radiografia.data_exame).toLocaleDateString("pt-BR")}
                        </p>
                      )}
                      {radiografia.laudo && (
                        <p className="text-xs mt-2 p-2 bg-muted/50 rounded line-clamp-3">
                          <strong>Laudo:</strong> {radiografia.laudo}
                        </p>
                      )}
                      {radiografia.observacoes && (
                        <p className="text-xs mt-1 text-muted-foreground line-clamp-2">{radiografia.observacoes}</p>
                      )}
                    </div>
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        className="flex-1"
                        onClick={() => openLaudoDialog(radiografia)}
                      >
                        <Edit className="w-4 h-4 mr-1" />
                        Editar Laudo
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                          const link = document.createElement("a");
                          link.href = radiografia.imagem_base64;
                          link.download = `${radiografia.titulo}.png`;
                          link.click();
                        }}
                      >
                        Baixar
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setDeleteId(radiografia.id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </>
      )}

      {/* Dialog de Edição de Laudo */}
      <Dialog open={laudoDialogOpen} onOpenChange={setLaudoDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Editar Laudo - {selectedRadiografia?.titulo}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="edit_laudo">Laudo Radiográfico</Label>
              <Textarea
                id="edit_laudo"
                value={editLaudo}
                onChange={(e) => setEditLaudo(e.target.value)}
                placeholder="Descreva os achados radiográficos..."
                rows={8}
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setLaudoDialogOpen(false)}>
                Cancelar
              </Button>
              <Button onClick={handleSaveLaudo}>
                Salvar Laudo
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar exclusão</AlertDialogTitle>
            <AlertDialogDescription>
              Tem certeza que deseja excluir esta radiografia? Esta ação não pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Excluir</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Separator } from "@/components/ui/separator";
import { Plus, Save, Printer, FileText, Pill, Clock, Calendar, Trash2, X } from "lucide-react";
import { usePacientes } from "@/hooks/usePacientes";
import { useReceituario, Medicamento } from "@/hooks/useReceituario";
import { useState } from "react";

export function Receituario() {
  const { pacientes } = usePacientes();
  const [selectedPacienteId, setSelectedPacienteId] = useState<string>("");
  const { receituarios, loading, createReceituario, deleteReceituario } = useReceituario(selectedPacienteId);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const [newReceituario, setNewReceituario] = useState({
    data_prescricao: new Date().toISOString().split('T')[0],
    diagnostico: "",
    observacoes: "",
    validade: "",
  });

  const [medicamentos, setMedicamentos] = useState<Medicamento[]>([]);
  const [currentMedicamento, setCurrentMedicamento] = useState<Medicamento>({
    nome: "",
    dosagem: "",
    frequencia: "",
    duracao: "",
    observacoes: "",
  });

  const selectedPaciente = pacientes.find((p) => p.id === selectedPacienteId);

  const addMedicamento = () => {
    if (!currentMedicamento.nome || !currentMedicamento.dosagem) return;

    setMedicamentos([...medicamentos, currentMedicamento]);
    setCurrentMedicamento({
      nome: "",
      dosagem: "",
      frequencia: "",
      duracao: "",
      observacoes: "",
    });
  };

  const removeMedicamento = (index: number) => {
    setMedicamentos(medicamentos.filter((_, i) => i !== index));
  };

  const handleSave = async () => {
    if (!selectedPacienteId || medicamentos.length === 0) {
      return;
    }

    try {
      await createReceituario({
        paciente_id: selectedPacienteId,
        ...newReceituario,
        medicamentos,
      });
      setNewReceituario({
        data_prescricao: new Date().toISOString().split('T')[0],
        diagnostico: "",
        observacoes: "",
        validade: "",
      });
      setMedicamentos([]);
      setDialogOpen(false);
    } catch (error) {
      console.error("Erro ao salvar receituário:", error);
    }
  };

  const handleDelete = async () => {
    if (deleteId) {
      await deleteReceituario(deleteId);
      setDeleteId(null);
    }
  };

  const handlePrint = (receituario: any) => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const medicamentosHTML = receituario.medicamentos
      .map((med: Medicamento) => `
        <div style="margin: 15px 0; padding: 10px; background: #f5f5f5; border-radius: 5px;">
          <strong>${med.nome}</strong><br/>
          Dosagem: ${med.dosagem}<br/>
          Frequência: ${med.frequencia}<br/>
          Duração: ${med.duracao}
          ${med.observacoes ? `<br/>Obs: ${med.observacoes}` : ''}
        </div>
      `)
      .join('');

    printWindow.document.write(`
      <html>
        <head>
          <title>Receituário - ${selectedPaciente?.nome}</title>
          <style>
            body { font-family: Arial, sans-serif; padding: 40px; }
            h1 { color: #333; border-bottom: 2px solid #333; padding-bottom: 10px; }
            .header { margin-bottom: 30px; }
            .info { margin: 10px 0; }
            .medicamentos { margin-top: 20px; }
            .footer { margin-top: 50px; text-align: center; font-size: 12px; color: #666; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>Receituário Odontológico</h1>
            <div class="info"><strong>Paciente:</strong> ${selectedPaciente?.nome}</div>
            <div class="info"><strong>Data:</strong> ${new Date(receituario.data_prescricao).toLocaleDateString('pt-BR')}</div>
            ${receituario.diagnostico ? `<div class="info"><strong>Diagnóstico:</strong> ${receituario.diagnostico}</div>` : ''}
          </div>

          <div class="medicamentos">
            <h2>Medicamentos Prescritos:</h2>
            ${medicamentosHTML}
          </div>

          ${receituario.observacoes ? `
            <div style="margin-top: 30px;">
              <strong>Observações:</strong>
              <p>${receituario.observacoes}</p>
            </div>
          ` : ''}

          <div class="footer">
            <p>___________________________________</p>
            <p>Assinatura do Profissional</p>
          </div>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.print();
  };

  return (
    <div className="space-y-6">
      {/* Seletor de Paciente */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Selecionar Paciente</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="paciente">Paciente</Label>
            <Select value={selectedPacienteId} onValueChange={setSelectedPacienteId}>
              <SelectTrigger id="paciente">
                <SelectValue placeholder="Selecione um paciente" />
              </SelectTrigger>
              <SelectContent>
                {pacientes.map((paciente) => (
                  <SelectItem key={paciente.id} value={paciente.id}>
                    {paciente.nome}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {selectedPaciente && (
            <div className="p-4 bg-muted rounded-lg space-y-1">
              <p className="text-sm"><strong>Email:</strong> {selectedPaciente.email}</p>
              <p className="text-sm"><strong>Telefone:</strong> {selectedPaciente.telefone}</p>
              {selectedPaciente.cpf && <p className="text-sm"><strong>CPF:</strong> {selectedPaciente.cpf}</p>}
            </div>
          )}
        </CardContent>
      </Card>

      {selectedPacienteId && (
        <>
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h2 className="text-xl font-semibold">Receituário</h2>
              <p className="text-sm text-muted-foreground">
                Prescrições médicas e medicamentos do paciente
              </p>
            </div>
            <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
              <DialogTrigger asChild>
                <Button>
                  <Plus className="w-4 h-4 mr-2" />
                  Nova Receita
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle>Nova Receita</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="data_prescricao">Data da Prescrição *</Label>
                      <Input
                        id="data_prescricao"
                        type="date"
                        value={newReceituario.data_prescricao}
                        onChange={(e) => setNewReceituario({ ...newReceituario, data_prescricao: e.target.value })}
                      />
                    </div>
                    <div>
                      <Label htmlFor="validade">Validade</Label>
                      <Input
                        id="validade"
                        type="date"
                        value={newReceituario.validade}
                        onChange={(e) => setNewReceituario({ ...newReceituario, validade: e.target.value })}
                      />
                    </div>
                  </div>

                  <div>
                    <Label htmlFor="diagnostico">Diagnóstico/CID</Label>
                    <Input
                      id="diagnostico"
                      value={newReceituario.diagnostico}
                      onChange={(e) => setNewReceituario({ ...newReceituario, diagnostico: e.target.value })}
                      placeholder="Ex: K04.1 - Necrose da polpa"
                    />
                  </div>

                  <Separator />

                  {/* Adicionar Medicamento */}
                  <div className="space-y-4">
                    <h4 className="font-medium flex items-center gap-2">
                      <Pill className="w-4 h-4" />
                      Adicionar Medicamento
                    </h4>

                    <div className="border rounded-md p-4 space-y-4 bg-muted/30">
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <Label htmlFor="medicamento">Medicamento *</Label>
                          <Input
                            id="medicamento"
                            value={currentMedicamento.nome}
                            onChange={(e) => setCurrentMedicamento({ ...currentMedicamento, nome: e.target.value })}
                            placeholder="Ex: Amoxicilina 500mg"
                          />
                        </div>
                        <div>
                          <Label htmlFor="dosagem">Dosagem *</Label>
                          <Input
                            id="dosagem"
                            value={currentMedicamento.dosagem}
                            onChange={(e) => setCurrentMedicamento({ ...currentMedicamento, dosagem: e.target.value })}
                            placeholder="Ex: 1 cápsula"
                          />
                        </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <Label htmlFor="frequencia">Frequência</Label>
                          <Input
                            id="frequencia"
                            value={currentMedicamento.frequencia}
                            onChange={(e) => setCurrentMedicamento({ ...currentMedicamento, frequencia: e.target.value })}
                            placeholder="Ex: 8/8h ou 3x ao dia"
                          />
                        </div>
                        <div>
                          <Label htmlFor="duracao">Duração</Label>
                          <Input
                            id="duracao"
                            value={currentMedicamento.duracao}
                            onChange={(e) => setCurrentMedicamento({ ...currentMedicamento, duracao: e.target.value })}
                            placeholder="Ex: 7 dias"
                          />
                        </div>
                      </div>

                      <div>
                        <Label htmlFor="obs_medicamento">Observações do Medicamento</Label>
                        <Input
                          id="obs_medicamento"
                          value={currentMedicamento.observacoes}
                          onChange={(e) => setCurrentMedicamento({ ...currentMedicamento, observacoes: e.target.value })}
                          placeholder="Ex: Tomar com alimentos"
                        />
                      </div>

                      <Button 
                        type="button" 
                        variant="outline" 
                        size="sm" 
                        className="w-full"
                        onClick={addMedicamento}
                        disabled={!currentMedicamento.nome || !currentMedicamento.dosagem}
                      >
                        <Plus className="w-4 h-4 mr-2" />
                        Adicionar à Lista
                      </Button>
                    </div>

                    {/* Lista de Medicamentos */}
                    {medicamentos.length > 0 && (
                      <div className="space-y-2">
                        <h5 className="font-medium text-sm">Medicamentos Adicionados:</h5>
                        {medicamentos.map((med, index) => (
                          <div key={index} className="flex items-start justify-between p-3 bg-muted rounded-md">
                            <div className="flex-1 text-sm">
                              <div className="font-medium">{med.nome}</div>
                              <div className="text-muted-foreground">
                                {med.dosagem} • {med.frequencia} • {med.duracao}
                              </div>
                              {med.observacoes && (
                                <div className="text-xs text-muted-foreground mt-1">Obs: {med.observacoes}</div>
                              )}
                            </div>
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              onClick={() => removeMedicamento(index)}
                            >
                              <X className="w-4 h-4" />
                            </Button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <Separator />

                  <div>
                    <Label htmlFor="observacoes">Observações e Orientações Gerais</Label>
                    <Textarea
                      id="observacoes"
                      value={newReceituario.observacoes}
                      onChange={(e) => setNewReceituario({ ...newReceituario, observacoes: e.target.value })}
                      placeholder="Orientações especiais, cuidados, contraindicações..."
                      rows={3}
                    />
                  </div>

                  <div className="flex justify-end gap-2">
                    <Button variant="outline" onClick={() => setDialogOpen(false)}>
                      Cancelar
                    </Button>
                    <Button 
                      onClick={handleSave}
                      disabled={medicamentos.length === 0 || loading}
                    >
                      <Save className="w-4 h-4 mr-2" />
                      Salvar Receita
                    </Button>
                  </div>
                </div>
              </DialogContent>
            </Dialog>
          </div>

          {/* Histórico de Receitas */}
          {receituarios.length === 0 ? (
            <Card>
              <CardContent className="p-12 text-center">
                <FileText className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <p className="text-muted-foreground">
                  Nenhuma receita emitida ainda. Clique em "Nova Receita" para começar.
                </p>
              </CardContent>
            </Card>
          ) : (
            <Card>
              <CardHeader>
                <CardTitle className="text-lg">Histórico de Receitas</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {receituarios.map((receituario) => (
                    <Card key={receituario.id} className="border-l-4 border-l-primary">
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between mb-3">
                          <div className="flex items-center gap-2">
                            <Calendar className="w-4 h-4 text-muted-foreground" />
                            <span className="font-medium">
                              {new Date(receituario.data_prescricao).toLocaleDateString('pt-BR')}
                            </span>
                          </div>
                        </div>

                        {receituario.diagnostico && (
                          <div className="mb-3 text-sm">
                            <strong>Diagnóstico:</strong> {receituario.diagnostico}
                          </div>
                        )}

                        <div className="space-y-3">
                          <h4 className="font-medium flex items-center gap-2 text-sm">
                            <Pill className="w-4 h-4" />
                            Medicamentos Prescritos
                          </h4>

                          {receituario.medicamentos.map((med, index) => (
                            <div key={index} className="bg-muted/50 rounded p-3 space-y-1">
                              <div className="font-medium text-sm">{med.nome}</div>
                              <div className="text-xs text-muted-foreground grid grid-cols-1 sm:grid-cols-3 gap-2">
                                <div>Dose: {med.dosagem}</div>
                                <div className="flex items-center gap-1">
                                  <Clock className="w-3 h-3" />
                                  {med.frequencia}
                                </div>
                                <div>Por: {med.duracao}</div>
                              </div>
                              {med.observacoes && (
                                <div className="text-xs text-muted-foreground">Obs: {med.observacoes}</div>
                              )}
                            </div>
                          ))}

                          {receituario.observacoes && (
                            <>
                              <Separator />
                              <div>
                                <h5 className="font-medium text-sm mb-1">Observações:</h5>
                                <p className="text-sm text-muted-foreground">{receituario.observacoes}</p>
                              </div>
                            </>
                          )}

                          <div className="flex justify-end gap-2 pt-2">
                            <Button 
                              variant="outline" 
                              size="sm"
                              onClick={() => handlePrint(receituario)}
                            >
                              <Printer className="w-4 h-4 mr-2" />
                              Imprimir
                            </Button>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => setDeleteId(receituario.id)}
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </>
      )}

      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar exclusão</AlertDialogTitle>
            <AlertDialogDescription>
              Tem certeza que deseja excluir esta receita? Esta ação não pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Excluir</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Patrimonio } from "@/hooks/usePatrimonio";

const patrimonioSchema = z.object({
  item: z.string().min(1, "Item é obrigatório").max(200, "Item muito longo"),
  codigo: z.string().min(1, "Código é obrigatório").max(50, "Código muito longo"),
  categoria: z.string().min(1, "Categoria é obrigatória"),
  valor: z.string().min(1, "Valor é obrigatório"),
  data_aquisicao: z.string().min(1, "Data de aquisição é obrigatória"),
  status: z.string().min(1, "Status é obrigatório"),
  observacoes: z.string().optional(),
});

type PatrimonioFormData = z.infer<typeof patrimonioSchema>;

interface PatrimonioFormProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: any) => void;
  patrimonio?: Patrimonio | null;
}

export function PatrimonioForm({
  open,
  onClose,
  onSubmit,
  patrimonio,
}: PatrimonioFormProps) {
  const form = useForm<PatrimonioFormData>({
    resolver: zodResolver(patrimonioSchema),
    defaultValues: {
      item: "",
      codigo: "",
      categoria: "",
      valor: "",
      data_aquisicao: "",
      status: "Ativo",
      observacoes: "",
    },
  });

  // Reset form when patrimonio changes
  useEffect(() => {
    if (open) {
      form.reset({
        item: patrimonio?.item || "",
        codigo: patrimonio?.codigo || "",
        categoria: patrimonio?.categoria || "",
        valor: patrimonio?.valor?.toString() || "",
        data_aquisicao: patrimonio?.data_aquisicao || "",
        status: patrimonio?.status || "Ativo",
        observacoes: patrimonio?.observacoes || "",
      });
    }
  }, [open, patrimonio, form]);

  const handleSubmit = (data: PatrimonioFormData) => {
    onSubmit({
      ...data,
      valor: parseFloat(data.valor),
      ...(patrimonio?.id && { id: patrimonio.id }),
    });
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {patrimonio ? "Editar Patrimônio" : "Novo Patrimônio"}
          </DialogTitle>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="item"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Item *</FormLabel>
                  <FormControl>
                    <Input placeholder="Ex: Cadeira Odontológica" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="codigo"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Código *</FormLabel>
                    <FormControl>
                      <Input placeholder="Ex: PAT-001" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="categoria"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Categoria *</FormLabel>
                    <Select
                      onValueChange={field.onChange}
                      value={field.value}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Selecione" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="Equipamento">Equipamento</SelectItem>
                        <SelectItem value="Móvel">Móvel</SelectItem>
                        <SelectItem value="Ferramenta">Ferramenta</SelectItem>
                        <SelectItem value="Eletrônico">Eletrônico</SelectItem>
                        <SelectItem value="Outro">Outro</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="valor"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Valor (R$) *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        step="0.01"
                        placeholder="0.00"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="data_aquisicao"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Data de Aquisição *</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="status"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Status *</FormLabel>
                  <Select
                    onValueChange={field.onChange}
                    value={field.value}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="Ativo">Ativo</SelectItem>
                      <SelectItem value="Manutenção">Manutenção</SelectItem>
                      <SelectItem value="Inativo">Inativo</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="observacoes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Observações</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="Informações adicionais..."
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-2">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit">
                {patrimonio ? "Atualizar" : "Cadastrar"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
