export interface BaseProcedimentoFormData {
  ordem_servico: string;
  paciente_id: string;
  nome_paciente: string;
  data_inicial: string;
  data_entrega?: string;
  dentista_id?: string;
  protetico_id?: string;
  [key: string]: any;
}

interface FormularioProcedimentoLayoutProps {
  title: string;
  basePath: string;
  baseName: string;
  formData: BaseProcedimentoFormData;
  setFormData: (fn: (prev: any) => any) => void;
  onSubmit: (e: React.FormEvent) => void;
  isPending: boolean;
  children: React.ReactNode;
  procedimentoId?: string;
  tipoProcedimento?: string;
}

export function FormularioProcedimentoLayout({
  title,
  basePath,
  baseName,
  formData,
  setFormData,
  onSubmit,
  isPending,
  children,
  procedimentoId,
  tipoProcedimento
}: FormularioProcedimentoLayoutProps) {
  const navigate = useNavigate();
  const { ordensServico, loading: loadingOS } = useOrdemServico();
  const { pacientes } = usePacientes();
  const { dentistas } = useDentistas();
  const { data: proteticos } = useProteticos();
  const { itens: historico, isLoading: loadingHistorico } = useHistorico(procedimentoId, tipoProcedimento);

  const [ordemServicoSelecionada, setOrdemServicoSelecionada] = useState('');
  const [modoManual, setModoManual] = useState(false);
  const [loadingGerarOs, setLoadingGerarOs] = useState(false);
  const { estoques } = useEstoque();
  const [materialSelecionado, setMaterialSelecionado] = useState('');
  const [quantidadeMaterial, setQuantidadeMaterial] = useState(1);

  // Sincronizar OS selecionada no dropdown
  useEffect(() => {
    if (ordemServicoSelecionada && ordensServico && pacientes && ordemServicoSelecionada !== 'none' && ordemServicoSelecionada !== 'loading') {
      const os = ordensServico.find(o => o.id === ordemServicoSelecionada);
      if (os) {
        const osNumero = os.numero_os ? String(os.numero_os).replace(/\D/g, '') : '';
        const paciente = pacientes.find(p => p.id === os.paciente_id);

        setFormData(prev => ({
          ...prev,
          ordem_servico: osNumero,
          paciente_id: os.paciente_id || '',
          nome_paciente: paciente?.nome || '',
        }));
      }
    }
  }, [ordemServicoSelecionada, ordensServico, pacientes, setFormData]);

  const handlePacienteChange = (pacienteId: string) => {
    const paciente = pacientes?.find((p) => p.id === pacienteId);
    setFormData((prev) => ({
      ...prev,
      paciente_id: pacienteId,
      nome_paciente: paciente?.nome || '',
    }));
  };

  const handleAutoGenerateOS = async () => {
    try {
      setLoadingGerarOs(true);
      const { data, error } = await supabase
        .from('ordem_servico')
        .select('numero_os')
        .order('numero_os', { ascending: false })
        .limit(1);

      let nextOs = 1000;
      if (data && data.length > 0) {
        const lastOs = parseInt(data[0].numero_os);
        if (!isNaN(lastOs)) {
          nextOs = lastOs + 1;
        }
      }
      setFormData(prev => ({ ...prev, ordem_servico: nextOs.toString() }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingGerarOs(false);
    }
  };

  const handleAddMaterial = () => {
    if (!materialSelecionado) return;
    const item = (estoques as any[]).find(e => e.id === materialSelecionado);
    if (!item) return;

    const novosMateriais = [...(formData.materiais || [])];
    const indexExistente = novosMateriais.findIndex((m: any) => m.item_id === materialSelecionado);

    if (indexExistente > -1) {
      novosMateriais[indexExistente].quantidade += quantidadeMaterial;
    } else {
      novosMateriais.push({
        item_id: materialSelecionado,
        nome: item.item,
        quantidade: quantidadeMaterial
      });
    }

    setFormData(prev => ({ ...prev, materiais: novosMateriais }));
    setMaterialSelecionado('');
    setQuantidadeMaterial(1);
  };

  const handleRemoveMaterial = (index: number) => {
    const novosMateriais = [...(formData.materiais || [])];
    novosMateriais.splice(index, 1);
    setFormData(prev => ({ ...prev, materiais: novosMateriais }));
  };

  return (
    <div className="p-4 sm:p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 mb-6">
          <Button
            type="button"
            variant="outline"
            onClick={() => navigate('/')}
            className="gap-2 border-2 hover:border-primary hover:bg-primary/5 transition-all duration-200 shadow-sm hover:shadow-md font-semibold"
          >
            <Home className="w-4 h-4" />
            <span className="hidden sm:inline">Voltar ao Menu</span>
            <span className="sm:hidden">Menu</span>
          </Button>
          <Button
            type="button"
            variant="ghost"
            onClick={() => navigate(basePath)}
            className="gap-2 hover:bg-gray-100 transition-all duration-200 font-semibold"
          >
            <ArrowLeft className="w-4 h-4" />
            <span className="hidden sm:inline">Voltar para {baseName}</span>
            <span className="sm:hidden">{baseName}</span>
          </Button>
        </div>

        <div className="p-6 bg-gradient-to-r from-primary/5 via-primary/3 to-transparent rounded-xl border-l-4 border-l-primary shadow-sm">
          <h1 className="text-2xl sm:text-3xl font-bold text-gray-900">{title}</h1>
          <p className="text-gray-600 mt-2 text-sm sm:text-base">
            Preencha os dados abaixo para cadastrar um novo procedimento
          </p>
        </div>
      </div>

      <form onSubmit={onSubmit}>
        {/* CARD 1: Informações Básicas */}
        <Card className="border-2 shadow-lg">
          <CardHeader className="bg-gradient-to-r from-primary/5 to-transparent border-b">
            <CardTitle className="text-xl flex items-center gap-3">
              <div className="p-2 bg-primary rounded-lg">
                <Save className="w-5 h-5 text-white" />
              </div>
              Informações Básicas
            </CardTitle>
            <p className="text-sm text-gray-600 mt-2">
              📋 Todos os campos marcados com <span className="text-red-500">*</span> são obrigatórios
            </p>
          </CardHeader>
          <CardContent className="space-y-6 pt-6">

            {!modoManual ? (
              <div className="space-y-3 p-4 bg-gradient-to-br from-blue-50 to-blue-100/30 rounded-xl border-2 border-blue-200">
                 <div className="flex items-center justify-between">
                  <Label htmlFor="os_selector" className="text-base font-semibold text-gray-800 flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-red-500"></div>
                     Selecionar Ordem de Serviço (OS) 
                  </Label>
                  <Button
                    type="button"
                    variant="link"
                    size="sm"
                    onClick={() => setModoManual(true)}
                    className="text-xs hover:underline font-semibold text-primary"
                  >
                    ✏️ Modo Manual (Nova OS)
                  </Button>
                </div>
                <Select
                  value={ordemServicoSelecionada}
                  onValueChange={setOrdemServicoSelecionada}
                  disabled={loadingOS}
                >
                  <SelectTrigger id="os_selector" className="h-12 border-2 hover:border-primary/50 transition-colors bg-white">
                    <SelectValue placeholder="Selecione uma ordem de serviço já aberta..." />
                  </SelectTrigger>
                  <SelectContent>
                    {loadingOS ? (
                      <SelectItem value="loading" disabled>Carregando...</SelectItem>
                    ) : ordensServico && ordensServico.length > 0 ? (
                      ordensServico
                        .filter(os => os.status !== 'Concluída')
                        .map((os) => {
                          const paciente = pacientes?.find(p => p.id === os.paciente_id);
                          return (
                            <SelectItem key={os.id} value={os.id}>
                              {os.numero_os} - {paciente?.nome || 'Sem nome'}
                            </SelectItem>
                          );
                        })
                    ) : (
                      <SelectItem value="none" disabled>Nenhuma OS disponível</SelectItem>
                    )}
                  </SelectContent>
                </Select>
                <p className="text-xs text-blue-700 font-medium">
                  💡 Aproveite uma Ordem de Serviço existente para vincular este procedimento.
                </p>
              </div>
            ) : (
              <div className="space-y-3 p-4 bg-gradient-to-br from-orange-50 to-orange-100/30 rounded-xl border-2 border-orange-200">
                <div className="flex items-center justify-between">
                  <Label className="text-base font-semibold text-gray-800 flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div>
                    ✏️ Entrada Manual (Criará nova OS no sistema)
                  </Label>
                  <Button
                    type="button"
                    variant="link"
                    size="sm"
                    onClick={() => {
                      setModoManual(false);
                      setFormData(prev => ({ ...prev, ordem_servico: '', paciente_id: '', nome_paciente: '' }));
                      setOrdemServicoSelecionada('');
                    }}
                    className="text-xs hover:underline font-semibold text-primary"
                  >
                    ⬅️ Voltar para Lista de OS
                  </Button>
                </div>
                <p className="text-xs text-orange-700 font-medium">
                  💡 Utilize esta área caso a OS desejada não apareça na lista ou seja a primeira vez.
                </p>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Número da OS */}
              <div className="space-y-3">
                 <Label htmlFor="ordem_servico" className="text-sm font-semibold text-gray-700 flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-red-500"></div>
                     Número da OS <span className="text-red-500">*</span>
                  </div>
                  {modoManual && (
                    <Button 
                      type="button" 
                      variant="ghost" 
                      size="sm" 
                      className="h-6 text-xs text-primary hover:bg-primary/10"
                      onClick={handleAutoGenerateOS}
                      disabled={loadingGerarOs}
                    >
                      {loadingGerarOs ? 'Gerando...' : '🎲 Auto-gerar'}
                    </Button>
                  )}
                </Label>
                <Input
                  id="ordem_servico"
                  type="text"
                  placeholder={modoManual ? "Digite o número ex: 12345" : "Selecione uma OS acima"}
                  value={formData.ordem_servico}
                  onChange={(e) => modoManual && setFormData(prev => ({ ...prev, ordem_servico: e.target.value }))}
                  readOnly={!modoManual}
                  className={`h-12 border-2 ${!modoManual ? "bg-gray-100 cursor-not-allowed" : "hover:border-primary/50"} transition-colors`}
                  required
                />
              </div>

              {/* Data Inicial */}
              <div className="space-y-3">
                <Label htmlFor="data_inicial" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-red-500"></div>
                  📅 Data Inicial <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="data_inicial"
                  type="date"
                  value={formData.data_inicial}
                  onChange={(e) => setFormData(prev => ({ ...prev, data_inicial: e.target.value }))}
                  className="h-12 border-2 hover:border-primary/50 transition-colors"
                  required
                />
              </div>
            </div>

            {/* Paciente */}
            <div className="space-y-3">
               <Label htmlFor="paciente_id" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full bg-red-500"></div>
                👤 Paciente <span className="text-red-500">*</span>
              </Label>
              {!modoManual ? (
                <Input
                  id="nome_paciente_read"
                  type="text"
                  placeholder="Será preenchido ao selecionar a OS"
                  value={formData.nome_paciente}
                  readOnly
                  className="h-12 border-2 bg-gray-100 cursor-not-allowed transition-colors"
                  required
                />
              ) : (
                <Select value={formData.paciente_id} onValueChange={handlePacienteChange}>
                  <SelectTrigger id="paciente_id" className="h-12 border-2 hover:border-primary/50 transition-colors bg-white">
                    <SelectValue placeholder="Selecione o paciente cadastrado" />
                  </SelectTrigger>
                  <SelectContent>
                    {pacientes?.map((paciente) => (
                      <SelectItem key={paciente.id} value={paciente.id}>
                        {paciente.nome}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>
          </CardContent>
        </Card>

        {/* CARD 2: Detalhes Técnicos (Injetados via children) */}
        <Card className="border-2 shadow-lg mt-6">
          <CardHeader className="bg-gradient-to-r from-primary/5 to-transparent border-b">
            <CardTitle className="text-xl flex items-center gap-3">
              <div className="p-2 bg-primary rounded-lg">
                <span className="text-white text-lg">🦷</span>
              </div>
              Detalhes Técnicos
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6 pt-6">
            {children}
          </CardContent>
        </Card>

        {/* CARD 3: Profissionais Responsáveis */}
        <Card className="border-2 shadow-lg mt-6">
          <CardHeader className="bg-gradient-to-r from-primary/5 to-transparent border-b">
            <CardTitle className="text-xl flex items-center gap-3">
              <div className="p-2 bg-primary rounded-lg">
                <span className="text-white text-lg">👥</span>
              </div>
              Profissionais & Datas Adicionais
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6 pt-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

              {/* Data de Entrega */}
              <div className="space-y-3">
                <Label htmlFor="data_entrega" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-gray-400"></div>
                  📅 Data de Entrega (Prevista)
                </Label>
                <Input
                  id="data_entrega"
                  type="date"
                  value={formData.data_entrega || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, data_entrega: e.target.value }))}
                  className="h-12 border-2 hover:border-primary/50 transition-colors"
                />
              </div>

               {/* Dentista */}
              <div className="space-y-3">
                <Label htmlFor="dentista_id" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-gray-400"></div>
                  👨‍⚕️ Dentista
                </Label>
                <Select
                  value={formData.dentista_id || ''}
                  onValueChange={(value) => setFormData((prev) => ({ ...prev, dentista_id: value }))}
                >
                  <SelectTrigger id="dentista_id" className="h-12 border-2 hover:border-primary/50 transition-colors bg-white">
                    <SelectValue placeholder="Selecione (Opcional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">Nenhum (Preencher depois)</SelectItem>
                    {dentistas?.map((dentista) => (
                      <SelectItem key={dentista.id} value={dentista.id}>
                        {dentista.nome} - CRO: {dentista.cro}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

            </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Protético */}
              <div className="space-y-3">
                <Label htmlFor="protetico_id" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-gray-400"></div>
                  🔧 Protético ou Laboratório
                </Label>
                <Select
                  value={formData.protetico_id || ''}
                  onValueChange={(value) => setFormData((prev) => ({ ...prev, protetico_id: value }))}
                >
                  <SelectTrigger id="protetico_id" className="h-12 border-2 hover:border-primary/50 transition-colors bg-white">
                    <SelectValue placeholder="Selecione (Opcional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">Nenhum (Preencher depois)</SelectItem>
                    {(proteticos as any[])?.map((protetico: any) => (
                      <SelectItem key={protetico.id} value={protetico.id.toString()}>
                        {protetico.nome}
                        {protetico.laboratorio && ` - ${protetico.laboratorio}`}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              </div>
            </CardContent>
          </Card>

          {/* Seção de Materiais (NOVO) */}
          <Card className="border-l-4 border-l-emerald-500 shadow-md">
            <CardHeader className="bg-emerald-50/50 pb-4">
              <CardTitle className="text-lg flex items-center gap-2">
                <Package className="w-5 h-5 text-emerald-600" />
                Materiais do Estoque
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-6 space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-12 gap-4 items-end">
                <div className="sm:col-span-7 space-y-2">
                  <Label>Selecionar Material</Label>
                  <Select value={materialSelecionado} onValueChange={setMaterialSelecionado}>
                    <SelectTrigger className="border-2 focus:ring-emerald-500">
                      <SelectValue placeholder="Escolha um material para consumir..." />
                    </SelectTrigger>
                    <SelectContent>
                      {estoques.map((item) => (
                        <SelectItem key={item.id} value={item.id} disabled={item.estoque <= 0}>
                          {item.item} ({item.estoque} itens) {item.estoque <= 0 ? '- ESGOTADO' : ''}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="sm:col-span-3 space-y-2">
                  <Label>Qtd</Label>
                  <Input 
                    type="number" 
                    min="1" 
                    className="border-2"
                    value={quantidadeMaterial}
                    onChange={(e) => setQuantidadeMaterial(Number(e.target.value))}
                  />
                </div>
                <div className="sm:col-span-2">
                  <Button 
                    type="button" 
                    onClick={handleAddMaterial}
                    disabled={!materialSelecionado}
                    className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold"
                  >
                    <PlusCircle className="w-4 h-4 mr-1" />
                    Add
                  </Button>
                </div>
              </div>

              {/* Lista de materiais adicionados */}
              <div className="space-y-3">
                {formData.materiais?.map((mat: any, idx: number) => (
                  <div key={idx} className="flex items-center justify-between p-3 rounded-lg bg-gray-50 border-2 border-gray-100 group hover:border-emerald-200 transition-all">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-emerald-100 rounded-lg">
                        <Package className="w-4 h-4 text-emerald-700" />
                      </div>
                      <div>
                        <p className="font-bold text-gray-800 text-sm">{mat.nome}</p>
                        <p className="text-xs text-gray-500">Quantidade: <span className="text-emerald-700 font-bold">{mat.quantidade}</span></p>
                      </div>
                    </div>
                    <Button 
                      type="button" 
                      variant="ghost" 
                      onClick={() => handleRemoveMaterial(idx)}
                      className="text-red-500 hover:text-red-700 hover:bg-red-50 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
                {(!formData.materiais || formData.materiais.length === 0) && (
                  <div className="text-center py-6 border-2 border-dashed rounded-xl bg-gray-50/30">
                    <p className="text-sm text-gray-400 italic">Nenhum material vinculado ainda</p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Conteúdo Específico */}
        <div className="flex flex-col sm:flex-row gap-4 pt-6 mt-4 border-t-2 border-dashed border-gray-200">
          <Button
            type="submit"
            disabled={isPending}
            className="flex-1 h-12 bg-gradient-to-r from-primary to-primary/80 hover:from-primary/90 hover:to-primary/70 shadow-md hover:shadow-lg transition-all duration-200 text-base font-semibold"
          >
            <Save className="w-5 h-5 mr-2" />
            {isPending ? '⏳ Salvando...' : '💾 Salvar Procedimento'}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => navigate(basePath)}
            className="flex-1 sm:flex-none h-12 border-2 hover:bg-gray-50 transition-all duration-200 text-base font-semibold px-8"
          >
            ❌ Cancelar
          </Button>
        </div>

      </form>

      {/* Histórico da OS - Mobile-first timeline */}
      {procedimentoId && (
        <Card className="border-2 shadow-lg mt-8 overflow-hidden">
          <CardHeader className="bg-gray-50 border-b">
            <CardTitle className="text-xl flex items-center gap-3 text-gray-800">
              <div className="p-2 bg-gray-200 rounded-lg">
                <Clock className="w-5 h-5 text-gray-600" />
              </div>
              Linha do Tempo da OS
            </CardTitle>
            <p className="text-sm text-gray-500 mt-1">
              Registro histórico de todas as movimentações e atualizações desta peça.
            </p>
          </CardHeader>
          <CardContent className="pt-8 px-6 pb-12">
            <HistoricoTimeline itens={historico} isLoading={loadingHistorico} />
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useQueryClient } from '@tanstack/react-query';

interface Protetico {
  id: number;
  nome: string;
  especialidade?: string | null;
  telefone?: string | null;
  email?: string | null;
  laboratorio?: string | null;
  ativo: boolean;
}

interface ProteticoFormProps {
  open: boolean;
  onClose: () => void;
  protetico?: Protetico;
}

const especialidades = [
  'Prótese Removível',
  'Prótese Fixa',
  'Prótese Total',
  'Prótese Parcial',
  'Implantodontia',
  'Cerâmica',
  'Metalurgia',
  'Ortodontia',
  'Geral'
];

export function ProteticoForm({ open, onClose, protetico }: ProteticoFormProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    nome: '',
    especialidade: '',
    telefone: '',
    email: '',
    laboratorio: '',
    ativo: true
  });

  useEffect(() => {
    if (protetico) {
      setFormData({
        nome: protetico.nome || '',
        especialidade: protetico.especialidade || '',
        telefone: protetico.telefone || '',
        email: protetico.email || '',
        laboratorio: protetico.laboratorio || '',
        ativo: protetico.ativo
      });
    } else {
      setFormData({
        nome: '',
        especialidade: '',
        telefone: '',
        email: '',
        laboratorio: '',
        ativo: true
      });
    }
  }, [protetico, open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      if (protetico) {
        // Atualizar
        const { error } = await supabase
          .from('proteticos')
          .update(formData)
          .eq('id', protetico.id);

        if (error) throw error;

        toast({
          title: 'Sucesso!',
          description: 'Protético atualizado com sucesso',
        });
      } else {
        // Criar
        const { error } = await supabase
          .from('proteticos')
          .insert([formData]);

        if (error) throw error;

        toast({
          title: 'Sucesso!',
          description: 'Protético cadastrado com sucesso',
        });
      }

      queryClient.invalidateQueries({ queryKey: ['proteticos'] });
      onClose();
    } catch (error: any) {
      toast({
        title: 'Erro',
        description: error.message || 'Erro ao salvar protético',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return (
    <Dialog open={open} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {protetico ? 'Editar Protético' : 'Novo Protético'}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="nome">Nome *</Label>
              <Input
                id="nome"
                value={formData.nome}
                onChange={(e) => handleChange('nome', e.target.value)}
                required
                placeholder="Nome completo"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="laboratorio">Laboratório</Label>
              <Input
                id="laboratorio"
                value={formData.laboratorio}
                onChange={(e) => handleChange('laboratorio', e.target.value)}
                placeholder="Nome do laboratório"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="especialidade">Especialidade</Label>
              <Select
                value={formData.especialidade}
                onValueChange={(value) => handleChange('especialidade', value)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione a especialidade" />
                </SelectTrigger>
                <SelectContent>
                  {especialidades.map((esp) => (
                    <SelectItem key={esp} value={esp}>{esp}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="ativo">Status *</Label>
              <Select
                value={formData.ativo ? "true" : "false"}
                onValueChange={(value) => handleChange('ativo', value === "true")}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="true">Ativo</SelectItem>
                  <SelectItem value="false">Inativo</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="telefone">Telefone</Label>
              <Input
                id="telefone"
                value={formData.telefone}
                onChange={(e) => handleChange('telefone', e.target.value)}
                placeholder="(11) 99999-9999"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => handleChange('email', e.target.value)}
                placeholder="email@exemplo.com"
              />
            </div>
          </div>

          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button type="submit" disabled={loading} className="flex-1">
              {loading ? 'Salvando...' : 'Salvar'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

