import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ManualCodigo } from "@/hooks/useManuaisCodigos";
import { Badge } from "@/components/ui/badge";
import { X } from "lucide-react";

interface ManualCodigoFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: any) => Promise<void>;
  manual?: ManualCodigo | null;
}

const tiposOptions = ["Manual", "Código de Procedimento", "Tabela", "Documento"];
const categoriasOptions = ["TUSS", "AMB", "SUS", "Próprio", "Geral", "Protocolos", "Legislação"];

export function ManualCodigoForm({ open, onOpenChange, onSubmit, manual }: ManualCodigoFormProps) {
  const [formData, setFormData] = useState({
    tipo: "Manual",
    titulo: "",
    codigo: "",
    descricao: "",
    categoria: "Geral",
    conteudo: "",
    link_externo: "",
    tags: [] as string[]
  });

  const [currentTag, setCurrentTag] = useState("");

  useEffect(() => {
    if (manual) {
      setFormData({
        tipo: manual.tipo,
        titulo: manual.titulo,
        codigo: manual.codigo || "",
        descricao: manual.descricao || "",
        categoria: manual.categoria,
        conteudo: manual.conteudo || "",
        link_externo: manual.link_externo || "",
        tags: manual.tags || []
      });
    } else {
      setFormData({
        tipo: "Manual",
        titulo: "",
        codigo: "",
        descricao: "",
        categoria: "Geral",
        conteudo: "",
        link_externo: "",
        tags: []
      });
    }
  }, [manual, open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await onSubmit(formData);
    onOpenChange(false);
  };

  const addTag = () => {
    if (currentTag.trim() && !formData.tags.includes(currentTag.trim())) {
      setFormData({ ...formData, tags: [...formData.tags, currentTag.trim()] });
      setCurrentTag("");
    }
  };

  const removeTag = (tag: string) => {
    setFormData({ ...formData, tags: formData.tags.filter(t => t !== tag) });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{manual ? "Editar" : "Novo"} Manual/Código</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="tipo">Tipo *</Label>
              <Select 
                value={formData.tipo} 
                onValueChange={(value) => setFormData({ ...formData, tipo: value as any })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione o tipo" />
                </SelectTrigger>
                <SelectContent>
                  {tiposOptions.map(tipo => (
                    <SelectItem key={tipo} value={tipo}>{tipo}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="categoria">Categoria *</Label>
              <Select 
                value={formData.categoria} 
                onValueChange={(value) => setFormData({ ...formData, categoria: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione a categoria" />
                </SelectTrigger>
                <SelectContent>
                  {categoriasOptions.map(cat => (
                    <SelectItem key={cat} value={cat}>{cat}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="titulo">Título *</Label>
            <Input
              id="titulo"
              value={formData.titulo}
              onChange={(e) => setFormData({ ...formData, titulo: e.target.value })}
              required
              placeholder="Ex: Tabela TUSS - Procedimentos Odontológicos"
            />
          </div>

          {formData.tipo === "Código de Procedimento" && (
            <div className="space-y-2">
              <Label htmlFor="codigo">Código</Label>
              <Input
                id="codigo"
                value={formData.codigo}
                onChange={(e) => setFormData({ ...formData, codigo: e.target.value })}
                placeholder="Ex: 81000030"
              />
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="descricao">Descrição</Label>
            <Textarea
              id="descricao"
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
              placeholder="Breve descrição do manual ou código..."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="conteudo">Conteúdo/Instruções</Label>
            <Textarea
              id="conteudo"
              value={formData.conteudo}
              onChange={(e) => setFormData({ ...formData, conteudo: e.target.value })}
              placeholder="Instruções detalhadas, protocolo, ou conteúdo do manual..."
              rows={5}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="link_externo">Link Externo</Label>
            <Input
              id="link_externo"
              type="url"
              value={formData.link_externo}
              onChange={(e) => setFormData({ ...formData, link_externo: e.target.value })}
              placeholder="https://..."
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="tags">Tags</Label>
            <div className="flex gap-2">
              <Input
                id="tags"
                value={currentTag}
                onChange={(e) => setCurrentTag(e.target.value)}
                onKeyPress={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    addTag();
                  }
                }}
                placeholder="Adicione uma tag..."
              />
              <Button type="button" variant="outline" onClick={addTag}>
                Adicionar
              </Button>
            </div>
            {formData.tags.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {formData.tags.map(tag => (
                  <Badge key={tag} variant="secondary" className="gap-1">
                    {tag}
                    <X 
                      className="w-3 h-3 cursor-pointer" 
                      onClick={() => removeTag(tag)}
                    />
                  </Badge>
                ))}
              </div>
            )}
          </div>

          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)} className="flex-1">
              Cancelar
            </Button>
            <Button type="submit" className="flex-1">
              {manual ? "Atualizar" : "Cadastrar"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { User, Session } from '@supabase/supabase-js';
import { supabase } from '@/integrations/supabase/client';
import { del } from 'idb-keyval';

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signIn: (email: string, password: string) => Promise<{ error: any }>;
  signUp: (email: string, password: string) => Promise<{ error: any }>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider = ({ children }: AuthProviderProps) => {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Set up auth state listener FIRST
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (event, session) => {
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      }
    );

    // THEN check for existing session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const signIn = async (email: string, password: string) => {
    const { error, data } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    // Registrar auditoria de login bem-sucedido
    if (!error && data.user) {
      try {
        await supabase.rpc('log_audit', {
          p_action: 'LOGIN',
          p_table_name: 'auth.users',
          p_record_id: data.user.id,
          p_new_data: {
            email: data.user.email,
            timestamp: new Date().toISOString()
          }
        });
      } catch (auditError) {
        // Não falhar o login se a auditoria falhar
        // TODO: Implementar logging service em produção (Sentry/LogRocket)
      }
    }

    return { error };
  };

  const signUp = async (email: string, password: string) => {
    const redirectUrl = `${window.location.origin}/`;

    const { error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        emailRedirectTo: redirectUrl
      }
    });
    return { error };
  };

  const signOut = async () => {
    try {
      // Registrar auditoria de logout ANTES de limpar estado
      const currentUser = user;
      if (currentUser) {
        try {
          await supabase.rpc('log_audit', {
            p_action: 'LOGOUT',
            p_table_name: 'auth.users',
            p_record_id: currentUser.id,
            p_old_data: {
              email: currentUser.email,
              timestamp: new Date().toISOString()
            }
          });
        } catch (auditError) {
          // Não falhar o logout se a auditoria falhar
        }
      }

      // Hard Clear local state (Security measure)
      setSession(null);
      setUser(null);

      // Clear persistence and cache
      await del('REACT_QUERY_OFFLINE_CACHE');

      // Then try to sign out from Supabase
      const { error } = await supabase.auth.signOut();
      if (error) {
        console.error("Supabase signout soft-failed:", error);
      }

      // Redirecionar para auth
      window.location.href = '/auth';
    } catch (error) {
      // Mesmo com erro crítico, limpa e redireciona
      await del('REACT_QUERY_OFFLINE_CACHE');
      window.location.href = '/auth';
    }
  };

  const value = {
    user,
    session,
    loading,
    signIn,
    signUp,
    signOut,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

export interface Agendamento {
  id: string;
  paciente_id: string;
  dentista_id?: string | null;
  protetico_id?: number | null;
  data_agendamento: string;
  duracao: number;
  procedimento: string;
  status: string;
  tipo_atendimento: string;
  convenio_id?: string;
  valor?: number;
  observacoes?: string;
  confirmado: boolean;
  created_at?: string;
  updated_at?: string;
  pacientes?: {
    nome: string;
    telefone: string;
    email: string;
  };
  dentistas?: {
    nome: string;
  };
  proteticos?: {
    nome: string;
  };
  convenios?: {
    nome: string;
  };
}

export const useAgendamentos = () => {
  const [agendamentos, setAgendamentos] = useState<Agendamento[]>([]);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();

  const fetchAgendamentos = async (startDate?: Date, endDate?: Date) => {
    try {
      setLoading(true);
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error("Usuário não autenticado");
      }

      let query = supabase
        .from("agendamentos")
        .select("*")
        .eq("user_id", user.id)
        .order("data_agendamento", { ascending: true });

      if (startDate) {
        query = query.gte("data_agendamento", startDate.toISOString());
      }

      if (endDate) {
        query = query.lte("data_agendamento", endDate.toISOString());
      }

      const { data, error } = await query;

      if (error) throw error;

      // Fetch relacionamentos
      if (data && data.length > 0) {
        const pacienteIds = [...new Set(data.map(a => a.paciente_id))];
        const dentistaIds = [...new Set(data.map(a => a.dentista_id).filter(Boolean))];
        const proteticoIds = [...new Set(data.map(a => a.protetico_id).filter(Boolean))];
        const convenioIds = [...new Set(data.map(a => a.convenio_id).filter(Boolean))];

        const [pacientesData, dentistasData, proteticosData, conveniosData] = await Promise.all([
          supabase.from("pacientes").select("id, nome, telefone, email").in("id", pacienteIds),
          dentistaIds.length > 0 ? supabase.from("dentistas").select("id, nome").in("id", dentistaIds as string[]) : Promise.resolve({ data: [] }),
          proteticoIds.length > 0 ? (supabase as any).from("proteticos").select("id, nome").in("id", proteticoIds) : Promise.resolve({ data: [] as any[] }),
          convenioIds.length > 0 
            ? supabase.from("convenios").select("id, nome").in("id", convenioIds as string[])
            : Promise.resolve({ data: [] })
        ]);

        const pacientesMap = new Map<string, any>();
        pacientesData.data?.forEach(p => pacientesMap.set(p.id, p));

        const dentistasMap = new Map<string, any>();
        dentistasData.data?.forEach(d => dentistasMap.set(d.id, d));

        const proteticosMap = new Map<number, any>();
        if (proteticosData.data && Array.isArray(proteticosData.data)) {
          proteticosData.data.forEach((p: any) => proteticosMap.set(p.id, p));
        }

        const conveniosMap = new Map<string, any>();
        conveniosData.data?.forEach(c => conveniosMap.set(c.id, c));

        const agendamentosWithRelations = data.map(a => ({
          ...a,
          pacientes: pacientesMap.get(a.paciente_id),
          dentistas: a.dentista_id ? dentistasMap.get(a.dentista_id) : undefined,
          proteticos: a.protetico_id ? proteticosMap.get(a.protetico_id) : undefined,
          convenios: a.convenio_id ? conveniosMap.get(a.convenio_id) : undefined
        }));

        setAgendamentos(agendamentosWithRelations as Agendamento[]);
      } else {
        setAgendamentos([]);
      }
    } catch (error: any) {
      toast({
        title: "Erro ao carregar agendamentos",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const createAgendamento = async (agendamento: Omit<Agendamento, "id" | "created_at" | "updated_at" | "pacientes" | "dentistas" | "convenios">) => {
    try {
      setLoading(true);
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        throw new Error("Usuário não autenticado");
      }

      const { error } = await supabase
        .from("agendamentos")
        .insert([{ ...agendamento, user_id: user.id }]);

      if (error) throw error;

      toast({
        title: "Agendamento criado",
        description: "Agendamento cadastrado com sucesso!",
      });

      await fetchAgendamentos();
    } catch (error: any) {
      toast({
        title: "Erro ao criar agendamento",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const updateAgendamento = async (id: string, agendamento: Partial<Agendamento>) => {
    try {
      setLoading(true);
      const { error } = await supabase
        .from("agendamentos")
        .update(agendamento)
        .eq("id", id);

      if (error) throw error;

      toast({
        title: "Agendamento atualizado",
        description: "Agendamento atualizado com sucesso!",
      });

      await fetchAgendamentos();
    } catch (error: any) {
      toast({
        title: "Erro ao atualizar agendamento",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const deleteAgendamento = async (id: string) => {
    try {
      setLoading(true);
      const { error } = await supabase
        .from("agendamentos")
        .delete()
        .eq("id", id);

      if (error) throw error;

      toast({
        title: "Agendamento excluído",
        description: "Agendamento excluído com sucesso!",
      });

      await fetchAgendamentos();
    } catch (error: any) {
      toast({
        title: "Erro ao excluir agendamento",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const confirmarAgendamento = async (id: string) => {
    try {
      setLoading(true);
      const { error } = await supabase
        .from("agendamentos")
        .update({ confirmado: true, status: "Confirmado" })
        .eq("id", id);

      if (error) throw error;

      toast({
        title: "Agendamento confirmado",
        description: "Agendamento confirmado com sucesso!",
      });

      await fetchAgendamentos();
    } catch (error: any) {
      toast({
        title: "Erro ao confirmar agendamento",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return {
    agendamentos,
    loading,
    fetchAgendamentos,
    createAgendamento,
    updateAgendamento,
    deleteAgendamento,
    confirmarAgendamento,
  };
};

