// =====================================================
// CALCULAR STATUS GERAL BASEADO NAS ETAPAS
// =====================================================
export function calcularStatusGeralCeramica(
  procedimento: Partial<ProcedimentoCeramica>
): StatusProcedimento {
  const etapasFinalizadas = ETAPAS_CERAMICA.filter((etapa) => {
    const statusKey = `${etapa.key}_status` as keyof ProcedimentoCeramica;
    const status = procedimento[statusKey];
    return status === 'Finalizado' || status === 'Concluido';
  }).length;

  if (etapasFinalizadas === 0) {
    return 'Pendente';
  } else if (etapasFinalizadas === ETAPAS_CERAMICA.length) {
    return 'Concluído';
  } else {
    return 'Em andamento';
  }
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

export interface ContaPagar {
  id: string;
  user_id: string;
  fornecedor_id?: string;
  descricao: string;
  categoria: string;
  valor: number;
  data_vencimento: string;
  data_pagamento?: string;
  status: 'Pendente' | 'Paga' | 'Vencida' | 'Cancelada';
  forma_pagamento?: string;
  observacoes?: string;
  created_at: string;
  updated_at: string;
  fornecedores?: {
    nome: string;
  };
}

export interface CreateContaPagarData {
  fornecedor_id?: string;
  descricao: string;
  categoria: string;
  valor: number;
  data_vencimento: string;
  data_pagamento?: string;
  status: 'Pendente' | 'Paga' | 'Vencida' | 'Cancelada';
  forma_pagamento?: string;
  observacoes?: string;
}

export function useContasPagar() {
  const [contas, setContas] = useState<ContaPagar[]>([]);
  const [loading, setLoading] = useState(false);
  const { user } = useAuth();

  const fetchContas = async () => {
    if (!user) {
      setContas([]);
      return;
    }

    try {
      setLoading(true);

      const { data, error } = await supabase
        .from('contas_pagar')
        .select(`
          *,
          fornecedores (
            nome
          )
        `)
        .order('data_vencimento', { ascending: true });

      if (error) {
        console.error('Supabase error:', error);
        throw error;
      }

      const processedData = (data || []).map(c => ({
        ...c,
        status: c.status as 'Pendente' | 'Paga' | 'Vencida' | 'Cancelada'
      }));

      setContas(processedData);
    } catch (error: any) {
      console.error('fetchContas error:', error);
      toast.error('Erro ao carregar contas: ' + error.message);
      setContas([]);
    } finally {
      setLoading(false);
    }
  };

  const createConta = async (contaData: CreateContaPagarData) => {
    if (!user) {
      toast.error('Usuário não autenticado');
      return;
    }

    try {
      const { data, error } = await supabase
        .from('contas_pagar')
        .insert([{
          ...contaData,
          user_id: user.id
        }])
        .select()
        .single();

      if (error) throw error;

      const processedConta = {
        ...data,
        status: data.status as 'Pendente' | 'Paga' | 'Vencida' | 'Cancelada'
      };

      setContas(prev => [...prev, processedConta]);
      toast.success('Conta a pagar criada com sucesso!');
      return processedConta;
    } catch (error: any) {
      console.error('createConta error:', error);
      toast.error('Erro ao criar conta: ' + error.message);
      throw error;
    }
  };

  const updateConta = async (id: string, contaData: Partial<CreateContaPagarData>) => {
    try {
      const { data, error } = await supabase
        .from('contas_pagar')
        .update(contaData)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;

      const processedConta = {
        ...data,
        status: data.status as 'Pendente' | 'Paga' | 'Vencida' | 'Cancelada'
      };

      setContas(prev => prev.map(c => c.id === id ? processedConta : c));
      toast.success('Conta atualizada com sucesso!');
      return processedConta;
    } catch (error: any) {
      console.error('updateConta error:', error);
      toast.error('Erro ao atualizar conta: ' + error.message);
      throw error;
    }
  };

  const deleteConta = async (id: string) => {
    try {
      const { error } = await supabase
        .from('contas_pagar')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setContas(prev => prev.filter(c => c.id !== id));
      toast.success('Conta excluída com sucesso!');
    } catch (error: any) {
      console.error('deleteConta error:', error);
      toast.error('Erro ao excluir conta: ' + error.message);
      throw error;
    }
  };

  const pagarConta = async (id: string, dataPagamento: string, formaPagamento: string) => {
    try {
      const { data, error } = await supabase
        .from('contas_pagar')
        .update({
          data_pagamento: dataPagamento,
          forma_pagamento: formaPagamento,
          status: 'Paga'
        })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;

      const processedConta = {
        ...data,
        status: data.status as 'Pendente' | 'Paga' | 'Vencida' | 'Cancelada'
      };

      setContas(prev => prev.map(c => c.id === id ? processedConta : c));
      toast.success('Conta marcada como paga!');
      return processedConta;
    } catch (error: any) {
      console.error('pagarConta error:', error);
      toast.error('Erro ao pagar conta: ' + error.message);
      throw error;
    }
  };

  useEffect(() => {
    if (user) {
      fetchContas();
    } else {
      setContas([]);
      setLoading(false);
    }
  }, [user?.id]);

  return {
    contas,
    loading,
    createConta,
    updateConta,
    deleteConta,
    pagarConta,
    refetch: fetchContas
  };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { startOfMonth, endOfMonth, startOfDay, endOfDay } from "date-fns";

export const useDashboardStats = () => {
  const { user } = useAuth();

  // Total de Pacientes
  const { data: totalPacientes = 0 } = useQuery({
    queryKey: ["dashboard-total-pacientes", user?.id],
    queryFn: async () => {
      if (!user?.id) return 0;

      const { count, error } = await supabase
        .from("pacientes")
        .select("*", { count: "exact", head: true })
        .eq("user_id", user.id)
        .eq("status", "Ativo");

      if (error) throw error;
      return count || 0;
    },
    enabled: !!user?.id,
  });

  // Agendamentos de hoje
  const { data: agendamentosHoje } = useQuery({
    queryKey: ["dashboard-agendamentos-hoje", user?.id],
    queryFn: async () => {
      if (!user?.id) return { total: 0, confirmados: 0, pendentes: 0 };

      const hoje = new Date();
      const inicioHoje = startOfDay(hoje).toISOString();
      const fimHoje = endOfDay(hoje).toISOString();

      const { data, error } = await supabase
        .from("agendamentos")
        .select("status")
        .eq("user_id", user.id)
        .gte("data_agendamento", inicioHoje)
        .lte("data_agendamento", fimHoje);

      if (error) throw error;

      const confirmados = data?.filter(a => a.status === "Confirmado").length || 0;
      const pendentes = data?.filter(a => a.status === "Agendado").length || 0;

      return {
        total: data?.length || 0,
        confirmados,
        pendentes,
      };
    },
    enabled: !!user?.id,
  });

  // Faturamento mensal (contas recebidas este mês)
  const { data: faturamentoMensal = 0 } = useQuery({
    queryKey: ["dashboard-faturamento-mensal", user?.id],
    queryFn: async () => {
      if (!user?.id) return 0;

      const hoje = new Date();
      const inicioMes = startOfMonth(hoje).toISOString();
      const fimMes = endOfMonth(hoje).toISOString();

      const { data, error } = await supabase
        .from("contas_receber")
        .select("valor")
        .eq("user_id", user.id)
        .eq("status", "Recebida")
        .gte("data_recebimento", inicioMes)
        .lte("data_recebimento", fimMes);

      if (error) throw error;

      const total = data?.reduce((sum, item) => sum + Number(item.valor || 0), 0) || 0;
      return total;
    },
    enabled: !!user?.id,
  });

  // Produtos com estoque baixo
  const { data: produtosFalta = 0 } = useQuery({
    queryKey: ["dashboard-produtos-falta", user?.id],
    queryFn: async () => {
      if (!user?.id) return 0;

      const { data, error } = await supabase
        .from("estoque")
        .select("*")
        .eq("user_id", user.id);

      if (error) throw error;

      // Contar produtos onde estoque atual está abaixo do mínimo
      const produtosAbaixoMinimo = data?.filter(
        item => item.estoque < item.minimo
      ).length || 0;

      return produtosAbaixoMinimo;
    },
    enabled: !!user?.id,
  });

  // Novos Status de OS
  const { data: osStats = { emAndamento: 0, atrasadas: 0 } } = useQuery({
    queryKey: ["dashboard-os-stats", user?.id],
    queryFn: async () => {
      if (!user?.id) return { emAndamento: 0, atrasadas: 0 };

      const tables = [
        'procedimentos_ppr', 'procedimentos_pt_pm', 'procedimentos_fixa',
        'procedimentos_protocolo', 'procedimentos_resina_impressa',
        'procedimentos_ceramica', 'procedimentos_placa',
        'procedimentos_provisorio', 'procedimentos_lab_externo'
      ];

      const results = await Promise.all(
        tables.map(table => 
          supabase
            .from(table as any)
            .select('status_geral, data_entrega')
            .eq('user_id', user.id)
            .in('status_geral', ['Pendente', 'Em andamento'])
        )
      );

      let emAndamento = 0;
      let atrasadas = 0;
      const hoje = new Date();
      hoje.setHours(0, 0, 0, 0);

      results.forEach(({ data }) => {
        if (data) {
          (data as any[]).forEach(proc => {
            emAndamento++;
            if (proc.data_entrega) {
              const dataEntrega = new Date(proc.data_entrega);
              if (dataEntrega < hoje) {
                atrasadas++;
              }
            }
          });
        }
      });

      return { emAndamento, atrasadas };
    },
    enabled: !!user?.id,
  });

  // Faturamento Previsto (Pendente para o mês atual)
  const { data: faturamentoPrevisto = 0 } = useQuery({
    queryKey: ["dashboard-faturamento-previsto", user?.id],
    queryFn: async () => {
      if (!user?.id) return 0;

      const hoje = new Date();
      const inicioMes = startOfMonth(hoje).toISOString();
      const fimMes = endOfMonth(hoje).toISOString();

      const { data, error } = await supabase
        .from("contas_receber")
        .select("valor")
        .eq("user_id", user.id)
        .eq("status", "Pendente")
        .gte("data_vencimento", inicioMes)
        .lte("data_vencimento", fimMes);

      if (error) throw error;

      return data?.reduce((sum, item) => sum + Number(item.valor || 0), 0) || 0;
    },
    enabled: !!user?.id,
  });

  // Próximos agendamentos do dia
  const { data: proximosAgendamentos = [] } = useQuery({
    queryKey: ["dashboard-proximos-agendamentos", user?.id],
    queryFn: async () => {
      if (!user?.id) return [];

      const hoje = new Date();
      const inicioHoje = startOfDay(hoje).toISOString();
      const fimHoje = endOfDay(hoje).toISOString();

      const { data: agendamentos, error } = await supabase
        .from("agendamentos")
        .select("*")
        .eq("user_id", user.id)
        .gte("data_agendamento", inicioHoje)
        .lte("data_agendamento", fimHoje)
        .order("data_agendamento", { ascending: true })
        .limit(5);

      if (error) throw error;
      if (!agendamentos) return [];

      // Buscar nomes dos pacientes e dentistas
      const pacienteIds = [...new Set(agendamentos.map(a => a.paciente_id))].filter(Boolean) as string[];
      const dentistaIds = [...new Set(agendamentos.map(a => a.dentista_id))].filter(Boolean) as string[];

      const { data: pacientes } = await supabase
        .from("pacientes")
        .select("id, nome")
        .in("id", pacienteIds);

      const { data: dentistas } = await supabase
        .from("dentistas")
        .select("id, nome")
        .in("id", dentistaIds);

      const pacientesMap = new Map(pacientes?.map(p => [p.id, p.nome]) || []);
      const dentistasMap = new Map(dentistas?.map(d => [d.id, d.nome]) || []);

      return agendamentos.map(agendamento => ({
        id: agendamento.id,
        time: new Date(agendamento.data_agendamento).toLocaleTimeString("pt-BR", {
          hour: "2-digit",
          minute: "2-digit",
        }),
        patient: pacientesMap.get(agendamento.paciente_id || '') || "Paciente não encontrado",
        dentista: dentistasMap.get(agendamento.dentista_id || '') || "Dentista não identificado",
        procedure: agendamento.procedimento || "Consulta Geral",
        status: agendamento.status || "Agendado",
      }));
    },
    enabled: !!user?.id,
  });

  // Itens de estoque baixo (detalhados)
  const { data: estoqueBaixo = [] } = useQuery({
    queryKey: ["dashboard-estoque-baixo", user?.id],
    queryFn: async () => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("estoque")
        .select("*")
        .eq("user_id", user.id)
        .order("estoque", { ascending: true });

      if (error) throw error;

      // Retornar apenas produtos abaixo do mínimo
      return data?.filter(item => item.estoque < item.minimo)
        .slice(0, 5)
        .map(item => ({
          name: item.item,
          current: item.estoque,
          minimum: item.minimo,
        })) || [];
    },
    enabled: !!user?.id,
  });

  return {
    stats: {
      totalPacientes,
      agendamentosHoje: agendamentosHoje || { total: 0, confirmados: 0, pendentes: 0 },
      faturamentoMensal,
      faturamentoPrevisto,
      produtosFalta,
      osEmAndamento: osStats.emAndamento,
      osAtrasadas: osStats.atrasadas,
    },
    proximosAgendamentos,
    estoqueBaixo,
    isLoading: !user?.id,
  };
};

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

export interface Dentista {
  id: string;
  user_id: string;
  nome: string;
  cro: string;
  especialidade: string;
  telefone: string;
  email: string;
  cpf: string;
  endereco?: string;
  data_nascimento?: string;
  status: 'Ativo' | 'Inativo';
  created_at: string;
  updated_at: string;
}

export interface CreateDentistaData {
  nome: string;
  cro: string;
  especialidade: string;
  telefone: string;
  email: string;
  cpf: string;
  endereco?: string;
  data_nascimento?: string;
  status: 'Ativo' | 'Inativo';
}

export function useDentistas() {
  const [dentistas, setDentistas] = useState<Dentista[]>([]);
  const [loading, setLoading] = useState(false);
  const { user } = useAuth();

  const fetchDentistas = async () => {
    if (!user) {
      console.log('fetchDentistas: no user, returning');
      setDentistas([]);
      return;
    }

    try {
      console.log('fetchDentistas: starting fetch for user:', user.id);
      setLoading(true);

      const { data, error } = await supabase
        .from('dentistas')
        .select('*')
        .order('nome');

      console.log('fetchDentistas result:', { data, error });

      if (error) {
        console.error('Supabase error:', error);
        throw error;
      }

      const processedData = (data || []).map(d => ({
        ...d,
        status: d.status as 'Ativo' | 'Inativo'
      }));

      console.log('Processed data:', processedData);
      setDentistas(processedData);
      console.log('fetchDentistas: dentistas set successfully');
    } catch (error: any) {
      console.error('fetchDentistas error:', error);
      toast.error('Erro ao carregar dentistas: ' + error.message);
      setDentistas([]);
    } finally {
      setLoading(false);
      console.log('fetchDentistas: loading set to false');
    }
  };

  const createDentista = async (dentistaData: CreateDentistaData) => {
    if (!user) return null;

    try {
      const { data, error } = await supabase
        .from('dentistas')
        .insert([{
          ...dentistaData,
          user_id: user.id
        }])
        .select()
        .single();

      if (error) throw error;

      await fetchDentistas();
      toast.success('Dentista cadastrado com sucesso!');
      return data;
    } catch (error: any) {
      toast.error('Erro ao cadastrar dentista: ' + error.message);
      return null;
    }
  };

  const updateDentista = async (id: string, dentistaData: Partial<CreateDentistaData>) => {
    try {
      const { error } = await supabase
        .from('dentistas')
        .update(dentistaData)
        .eq('id', id);

      if (error) throw error;

      await fetchDentistas();
      toast.success('Dentista atualizado com sucesso!');
      return true;
    } catch (error: any) {
      toast.error('Erro ao atualizar dentista: ' + error.message);
      return false;
    }
  };

  const deleteDentista = async (id: string) => {
    try {
      const { error } = await supabase
        .from('dentistas')
        .delete()
        .eq('id', id);

      if (error) throw error;

      await fetchDentistas();
      toast.success('Dentista removido com sucesso!');
      return true;
    } catch (error: any) {
      toast.error('Erro ao remover dentista: ' + error.message);
      return false;
    }
  };

  // Carregar dados quando o usuário estiver disponível
  useEffect(() => {
    if (user) {
      console.log('useEffect triggered, user:', user.id);
      fetchDentistas();
    } else {
      console.log('useEffect: no user, clearing data');
      setDentistas([]);
      setLoading(false);
    }
  }, [user?.id]); // Dependência específica no ID do usuário

  return {
    dentistas,
    loading,
    createDentista,
    updateDentista,
    deleteDentista,
    refetch: fetchDentistas
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

export interface Foto {
  id: string;
  user_id: string;
  paciente_id: string;
  titulo: string;
  imagem_base64: string;
  tipo: string | null;
  data_foto: string | null;
  observacoes: string | null;
  created_at: string;
  updated_at: string;
}

export interface CreateFotoData {
  paciente_id: string;
  titulo: string;
  imagem_base64: string;
  tipo?: string;
  data_foto?: string;
  observacoes?: string;
}

export function useFotos(pacienteId?: string) {
  const [fotos, setFotos] = useState<Foto[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();

  const fetchFotos = async (patientId: string) => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("fotos")
        .select("*")
        .eq("paciente_id", patientId)
        .order("created_at", { ascending: false });

      if (error) throw error;
      setFotos(data as Foto[]);
    } catch (error: any) {
      console.error("Error fetching fotos:", error);
      toast.error("Erro ao carregar fotos");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user && pacienteId) {
      fetchFotos(pacienteId);
    } else {
      setLoading(false);
      setFotos([]);
    }
  }, [user, pacienteId]);

  const createFoto = async (fotoData: CreateFotoData) => {
    try {
      if (!user) {
        toast.error("Usuário não autenticado");
        return;
      }

      const { data, error } = await supabase
        .from("fotos")
        .insert([{
          paciente_id: fotoData.paciente_id,
          titulo: fotoData.titulo,
          imagem_base64: fotoData.imagem_base64,
          tipo: fotoData.tipo || null,
          data_foto: fotoData.data_foto || null,
          observacoes: fotoData.observacoes || null,
          user_id: user.id,
        }])
        .select()
        .single();

      if (error) throw error;

      setFotos((prev) => [data as Foto, ...prev]);
      toast.success("Foto adicionada com sucesso!");
      return data;
    } catch (error: any) {
      console.error("Error creating foto:", error);
      toast.error("Erro ao adicionar foto");
      throw error;
    }
  };

  const updateFoto = async (
    id: string,
    fotoData: Partial<CreateFotoData>
  ) => {
    try {
      const updateData: any = {};
      Object.keys(fotoData).forEach((key) => {
        if (fotoData[key as keyof CreateFotoData] !== undefined) {
          updateData[key] = fotoData[key as keyof CreateFotoData];
        }
      });

      const { data, error } = await supabase
        .from("fotos")
        .update(updateData)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;

      setFotos((prev) =>
        prev.map((foto) => (foto.id === id ? (data as Foto) : foto))
      );
      toast.success("Foto atualizada com sucesso!");
      return data;
    } catch (error: any) {
      console.error("Error updating foto:", error);
      toast.error("Erro ao atualizar foto");
      throw error;
    }
  };

  const deleteFoto = async (id: string) => {
    try {
      const { error } = await supabase
        .from("fotos")
        .delete()
        .eq("id", id);

      if (error) throw error;

      setFotos((prev) => prev.filter((foto) => foto.id !== id));
      toast.success("Foto excluída com sucesso!");
    } catch (error: any) {
      console.error("Error deleting foto:", error);
      toast.error("Erro ao excluir foto");
      throw error;
    }
  };

  const refetch = (patientId: string) => {
    if (user && patientId) {
      fetchFotos(patientId);
    }
  };

  return {
    fotos,
    loading,
    createFoto,
    updateFoto,
    deleteFoto,
    refetch,
  };
}

import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

export interface DentistaPerformance {
  dentista_id: string;
  dentista_nome: string;
  total_procedimentos: number;
  faturamento_total: number;
  total_comissao: number;
  crescimento: string;
  percentual_performance: number;
}

export interface ProcedimentoDentista {
  dentista_id: string;
  dentista_nome: string;
  procedimento: string;
  quantidade: number;
  valor_total: number;
}

export const useGanhoDentista = (dataInicio?: Date, dataFim?: Date) => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [performanceDentistas, setPerformanceDentistas] = useState<DentistaPerformance[]>([]);
  const [topProcedimentos, setTopProcedimentos] = useState<ProcedimentoDentista[]>([]);

  const fetchRelatorio = async () => {
    if (!user) return;

    try {
      setLoading(true);

      // Buscar todos os dentistas
      const { data: dentistas, error: dentistasError } = await supabase
        .from('dentistas')
        .select('id, nome')
        .eq('user_id', user.id)
        .eq('status', 'Ativo');

      if (dentistasError) throw dentistasError;

      // Preparar filtros de data
      let agendamentosQuery = supabase
        .from('agendamentos')
        .select('dentista_id, valor, procedimento, status')
        .eq('user_id', user.id)
        .in('status', ['Concluído', 'Realizado']);

      if (dataInicio) {
        agendamentosQuery = agendamentosQuery.gte('data_agendamento', dataInicio.toISOString());
      }
      if (dataFim) {
        agendamentosQuery = agendamentosQuery.lte('data_agendamento', dataFim.toISOString());
      }

      const { data: agendamentos, error: agendamentosError } = await agendamentosQuery;
      if (agendamentosError) throw agendamentosError;

      // Buscar comissões
      let comissoesQuery = supabase
        .from('comissoes')
        .select('dentista_id, valor_comissao')
        .eq('user_id', user.id)
        .eq('status', 'Paga');

      if (dataInicio) {
        comissoesQuery = comissoesQuery.gte('data_inicio', dataInicio.toISOString().split('T')[0]);
      }
      if (dataFim) {
        comissoesQuery = comissoesQuery.lte('data_fim', dataFim.toISOString().split('T')[0]);
      }

      const { data: comissoes, error: comissoesError } = await comissoesQuery;
      if (comissoesError) throw comissoesError;

      // Calcular performance por dentista
      const performance: DentistaPerformance[] = (dentistas || []).map((dentista) => {
        const agendamentosDentista = (agendamentos || []).filter(a => a.dentista_id === dentista.id);
        const comissoesDentista = (comissoes || []).filter(c => c.dentista_id === dentista.id);

        const totalProcedimentos = agendamentosDentista.length;
        const faturamentoTotal = agendamentosDentista.reduce((sum, a) => sum + Number(a.valor || 0), 0);
        const totalComissao = comissoesDentista.reduce((sum, c) => sum + Number(c.valor_comissao || 0), 0);

        // Calcular percentual de performance (baseado em meta de 100k)
        const metaMensal = 100000;
        const percentualPerformance = (faturamentoTotal / metaMensal) * 100;

        return {
          dentista_id: dentista.id,
          dentista_nome: dentista.nome,
          total_procedimentos: totalProcedimentos,
          faturamento_total: faturamentoTotal,
          total_comissao: totalComissao,
          crescimento: '+0%', // Pode ser calculado comparando com período anterior
          percentual_performance: Math.min(percentualPerformance, 100)
        };
      });

      // Calcular top procedimentos por dentista
      const procedimentosMap = new Map<string, ProcedimentoDentista>();

      (agendamentos || []).forEach((agendamento) => {
        const key = `${agendamento.dentista_id}-${agendamento.procedimento}`;
        const dentista = (dentistas || []).find(d => d.id === agendamento.dentista_id);

        if (dentista) {
          const existing = procedimentosMap.get(key);
          if (existing) {
            existing.quantidade += 1;
            existing.valor_total += Number(agendamento.valor || 0);
          } else {
            procedimentosMap.set(key, {
              dentista_id: agendamento.dentista_id,
              dentista_nome: dentista.nome,
              procedimento: agendamento.procedimento,
              quantidade: 1,
              valor_total: Number(agendamento.valor || 0)
            });
          }
        }
      });

      const topProcs = Array.from(procedimentosMap.values())
        .sort((a, b) => b.valor_total - a.valor_total)
        .slice(0, 10);

      setPerformanceDentistas(performance);
      setTopProcedimentos(topProcs);
    } catch (error: any) {
      console.error('Erro ao buscar relatório:', error);
      toast.error('Erro ao carregar relatório de ganho por dentista');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRelatorio();
  }, [user, dataInicio, dataFim]);

  return {
    performanceDentistas,
    topProcedimentos,
    loading,
    refetch: fetchRelatorio
  };
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";

export interface SearchResult {
  id: string;
  type: "paciente" | "agendamento";
  title: string;
  subtitle?: string;
  data?: any;
}

export const useGlobalSearch = (query: string) => {
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const { user } = useAuth();

  useEffect(() => {
    const searchData = async () => {
      if (!query || query.length < 2 || !user?.id) {
        setResults([]);
        return;
      }

      setIsLoading(true);
      try {
        const searchTerm = `%${query}%`;

        // Buscar pacientes
        const { data: pacientes } = await supabase
          .from("pacientes")
          .select("*")
          .eq("user_id", user.id)
          .or(`nome.ilike.${searchTerm},cpf.ilike.${searchTerm},telefone.ilike.${searchTerm}`)
          .limit(5);

        // Buscar agendamentos com informações do paciente
        const { data: agendamentos } = await supabase
          .from("agendamentos")
          .select("*")
          .eq("user_id", user.id)
          .or(`procedimento.ilike.${searchTerm},observacoes.ilike.${searchTerm}`)
          .limit(5);

        const searchResults: SearchResult[] = [];

        // Adicionar pacientes aos resultados
        if (pacientes) {
          for (const paciente of pacientes) {
            searchResults.push({
              id: paciente.id,
              type: "paciente",
              title: paciente.nome,
              subtitle: paciente.telefone,
              data: paciente,
            });
          }
        }

        // Adicionar agendamentos aos resultados
        if (agendamentos) {
          for (const agendamento of agendamentos) {
            // Buscar nome do paciente
            const { data: paciente } = await supabase
              .from("pacientes")
              .select("nome")
              .eq("id", agendamento.paciente_id)
              .single();

            const dataFormatada = new Date(agendamento.data_agendamento).toLocaleDateString("pt-BR");

            searchResults.push({
              id: agendamento.id,
              type: "agendamento",
              title: agendamento.procedimento,
              subtitle: `${paciente?.nome || "Paciente"} - ${dataFormatada}`,
              data: agendamento,
            });
          }
        }

        setResults(searchResults);
      } catch (error) {
        console.error("Erro ao buscar:", error);
        setResults([]);
      } finally {
        setIsLoading(false);
      }
    };

    // Debounce
    const timeoutId = setTimeout(searchData, 300);
    return () => clearTimeout(timeoutId);
  }, [query, user?.id]);

  return { results, isLoading };
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

export interface HistoricoItem {
  id: string;
  user_id: string;
  paciente_id?: string;
  procedimento_id?: string;
  tipo_procedimento?: string;
  ordem_servico?: number;
  usuario_nome: string;
  acao: string;
  detalhes?: string;
  tipo: 'STATUS' | 'TECNICA' | 'FINANCEIRO' | 'SISTEMA';
  data: string;
}

export function useHistorico(procedimentoId?: string, tipoProcedimento?: string) {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const { data: itens = [], isLoading } = useQuery({
    queryKey: ['historico', procedimentoId, tipoProcedimento],
    queryFn: async () => {
      if (!procedimentoId || !tipoProcedimento) return [];

      const { data, error } = await (supabase as any)
        .from('historico_atividades')
        .select('*')
        .eq('procedimento_id', procedimentoId)
        .eq('tipo_procedimento', tipoProcedimento)
        .order('data', { ascending: false });

      if (error) {
        console.error('Erro ao buscar histórico:', error);
        return [];
      }

      return data as HistoricoItem[];
    },
    enabled: !!procedimentoId && !!tipoProcedimento,
  });

  const adicionarEvento = useMutation({
    mutationFn: async (evento: Omit<HistoricoItem, 'id' | 'user_id' | 'data'>) => {
      if (!user) throw new Error('Usuário não autenticado');

      const { error } = await (supabase as any)
        .from('historico_atividades')
        .insert({
          ...evento,
          user_id: user.id,
          data: new Date().toISOString(),
        });

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['historico', procedimentoId, tipoProcedimento] });
    },
    onError: (error) => {
      console.error('Erro ao registrar histórico:', error);
    }
  });

  return {
    itens,
    isLoading,
    adicionarEvento: adicionarEvento.mutateAsync
  };
}

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

export interface Honorario {
  id: string;
  procedimento: string;
  codigo: string;
  categoria: string;
  valor_particular: number;
  valor_convenio: number;
