// =====================================================
// CALCULAR STATUS GERAL BASEADO NAS ETAPAS
// =====================================================
export function calcularStatusGeralLabExterno(
  procedimento: Partial<ProcedimentoLabExterno>
): StatusProcedimento {
  const etapasFinalizadas = ETAPAS_LAB_EXTERNO.filter((etapa) => {
    const statusKey = `${etapa.key}_status` as keyof ProcedimentoLabExterno;
    const status = procedimento[statusKey];
    return status === 'Finalizado' || status === 'Concluido';
  }).length;

  if (etapasFinalizadas === 0) {
    return 'Pendente';
  } else if (etapasFinalizadas === ETAPAS_LAB_EXTERNO.length) {
    return 'Concluído';
  } else {
    return 'Em andamento';
  }
}

