  }, [user]);

  return {
    manuais,
    loading,
    createManual,
    updateManual,
    deleteManual,
    refetch: fetchManuais
  };
};

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useTodosProcedimentos } from './useTodosProcedimentos';
import { isBefore, startOfDay, parseISO } from 'date-fns';

export interface Notificacao {
  id: string;
  tipo: 'FALTA' | 'ATRASO_OS' | 'SUCESSO';
  titulo: string;
  mensagem: string;
  data: string;
  lida: boolean;
  link?: string;
}

export function useNotificacoes() {
  const { data: todosProcedimentos } = useTodosProcedimentos();

  return useQuery({
    queryKey: ['notificacoes', todosProcedimentos?.length],
    queryFn: async () => {
      const notificacoes: Notificacao[] = [];
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return [];

      // 1. Buscar agendamentos recentes do tipo "Faltou" (Últimos 15 dias)
      const quinzeDiasAtras = new Date();
      quinzeDiasAtras.setDate(quinzeDiasAtras.getDate() - 15);

      const { data: faltas } = await supabase
        .from('agendamentos')
        .select(`
          id, 
          data_agendamento, 
          status,
          pacientes (nome)
        `)
        .eq('user_id', user.id)
        .eq('status', 'Faltou')
        .gte('data_agendamento', quinzeDiasAtras.toISOString());

      if (faltas) {
        faltas.forEach(falta => {
          notificacoes.push({
            id: `falta-${falta.id}`,
            tipo: 'FALTA',
            titulo: 'Alerta de Falta',
            mensagem: `Paciente ${(falta.pacientes as any)?.nome || 'Desconhecido'} faltou à consulta.`,
            data: falta.data_agendamento,
            lida: false,
            link: '/appointments'
          });
        });
      }

      // 3. Verificar Estoque (abaixo do mínimo)
      const { data: estoque } = await supabase
        .from('estoque')
        .select('*')
        .eq('user_id', user.id);

      if (estoque) {
        estoque.forEach(item => {
          if (item.estoque < item.minimo) {
            notificacoes.push({
              id: `estoque-${item.id}`,
              tipo: 'FALTA',
              titulo: 'Estoque Baixo!',
              mensagem: `${item.item} está com apenas ${item.estoque} unidades (mínimo: ${item.minimo}).`,
              data: new Date().toISOString(),
              lida: false,
              link: '/estoque'
            });
          }
        });
      }

      // Ordenar para mostrar mais urgentes/recentes no topo
      return notificacoes.sort((a, b) => new Date(b.data).getTime() - new Date(a.data).getTime());
    },
    enabled: todosProcedimentos !== undefined,
    staleTime: 5 * 60 * 1000,
  });
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

export interface DadosDente {
  numero: number;
  procedimentos: string[];
  observacoes?: string;
}

export interface Odontograma {
  id: string;
  user_id: string;
  paciente_id: string;
  dados_dentes: Record<string, DadosDente>;
  observacoes: string | null;
  created_at: string;
  updated_at: string;
}

export interface CreateOdontogramaData {
  paciente_id: string;
  dados_dentes?: Record<string, DadosDente>;
  observacoes?: string;
}

export function useOdontograma(pacienteId?: string) {
  const [odontograma, setOdontograma] = useState<Odontograma | null>(null);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();

  const fetchOdontograma = async (patientId: string) => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("odontograma")
        .select("*")
        .eq("paciente_id", patientId)
        .maybeSingle();

      if (error) throw error;
      setOdontograma(data as unknown as Odontograma | null);
    } catch (error: any) {
      console.error("Error fetching odontograma:", error);
      toast.error("Erro ao carregar odontograma");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user && pacienteId) {
      fetchOdontograma(pacienteId);
    } else {
      setLoading(false);
      setOdontograma(null);
    }
  }, [user, pacienteId]);

  const createOdontograma = async (odontogramaData: CreateOdontogramaData) => {
    try {
      if (!user) {
        toast.error("Usuário não autenticado");
        return;
      }

      const { data, error } = await supabase
        .from("odontograma")
        .insert([{
          paciente_id: odontogramaData.paciente_id,
          dados_dentes: (odontogramaData.dados_dentes || {}) as any,
          observacoes: odontogramaData.observacoes || null,
          user_id: user.id,
        }])
        .select()
        .single();

      if (error) throw error;

      setOdontograma(data as unknown as Odontograma);
      toast.success("Odontograma criado com sucesso!");
      return data;
    } catch (error: any) {
      console.error("Error creating odontograma:", error);
      toast.error("Erro ao criar odontograma");
      throw error;
    }
  };

  const updateOdontograma = async (
    id: string,
    odontogramaData: Partial<CreateOdontogramaData>
  ) => {
    try {
      const updateData: any = {};
      if (odontogramaData.dados_dentes !== undefined) {
        updateData.dados_dentes = odontogramaData.dados_dentes;
      }
      if (odontogramaData.observacoes !== undefined) {
        updateData.observacoes = odontogramaData.observacoes;
      }

      const { data, error } = await supabase
        .from("odontograma")
        .update(updateData)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;

      setOdontograma(data as unknown as Odontograma);
      toast.success("Odontograma atualizado com sucesso!");
      return data;
    } catch (error: any) {
      console.error("Error updating odontograma:", error);
      toast.error("Erro ao atualizar odontograma");
      throw error;
    }
  };

  const deleteOdontograma = async (id: string) => {
    try {
      const { error } = await supabase
        .from("odontograma")
        .delete()
        .eq("id", id);

      if (error) throw error;

      setOdontograma(null);
      toast.success("Odontograma excluído com sucesso!");
    } catch (error: any) {
      console.error("Error deleting odontograma:", error);
