import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

export interface Paciente {
  id: string;
  user_id: string;
  nome: string;
  email: string;
  telefone: string;
  data_nascimento?: string | null;
  status: 'Ativo' | 'Inativo';
  endereco?: string | null;
  rua?: string | null;
  numero?: string | null;
  bairro?: string | null;
  cidade?: string | null;
  observacao_endereco?: string | null;
  cpf?: string | null;
  ultima_consulta?: string | null;
  created_at?: string;
  updated_at?: string;
}

export type CreatePacienteData = Omit<
  Paciente,
  'id' | 'user_id' | 'created_at' | 'updated_at'
>;

export function usePacientes() {
  const [pacientes, setPacientes] = useState<Paciente[]>([]);
  const [loading, setLoading] = useState(false);
  const { user } = useAuth();

  const fetchPacientes = async () => {
    if (!user) {
      setPacientes([]);
      return;
    }

    try {
      setLoading(true);

      const { data, error } = await supabase
        .from('pacientes')
        .select('*')
        .eq('user_id', user.id)
        .eq('status', 'Ativo')
        .order('nome');

      if (error) {
        console.error('Supabase error:', error);
        throw error;
      }

      const processedData = (data || []).map(p => ({
        ...p,
        status: p.status as 'Ativo' | 'Inativo'
      }));

      setPacientes(processedData);
    } catch (error: any) {
      console.error('fetchPacientes error:', error);
      toast.error('Erro ao carregar pacientes: ' + error.message);
      setPacientes([]);
    } finally {
      setLoading(false);
    }
  };

  const createPaciente = async (pacienteData: CreatePacienteData) => {
    if (!user) {
      toast.error('Usuário não autenticado');
      return;
    }

    try {
      const { data, error } = await supabase
        .from('pacientes')
        .insert([{
          ...pacienteData,
          user_id: user.id
        }])
        .select()
        .single();

      if (error) throw error;

      const processedPaciente = {
        ...data,
        status: data.status as 'Ativo' | 'Inativo'
      };
      setPacientes(prev => [...prev, processedPaciente]);
      toast.success('Paciente criado com sucesso!');
      return processedPaciente;
    } catch (error: any) {
      console.error('createPaciente error:', error);
      toast.error('Erro ao criar paciente: ' + error.message);
      throw error;
    }
  };

  const updatePaciente = async (id: string, pacienteData: Partial<CreatePacienteData>) => {
    try {
      const { data, error } = await supabase
        .from('pacientes')
        .update(pacienteData)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;

      const processedPaciente = {
        ...data,
        status: data.status as 'Ativo' | 'Inativo'
      };
      setPacientes(prev => prev.map(p => p.id === id ? processedPaciente : p));
      toast.success('Paciente atualizado com sucesso!');
      return processedPaciente;
    } catch (error: any) {
      console.error('updatePaciente error:', error);
      toast.error('Erro ao atualizar paciente: ' + error.message);
      throw error;
    }
  };

  const deletePaciente = async (id: string) => {
    try {
      const { error } = await supabase
        .from('pacientes')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setPacientes(prev => prev.filter(p => p.id !== id));
      toast.success('Paciente excluído com sucesso!');
    } catch (error: any) {
      console.error('deletePaciente error:', error);
      toast.error('Erro ao excluir paciente: ' + error.message);
      throw error;
    }
  };

  useEffect(() => {
    if (user) {
      fetchPacientes();
    } else {
      setPacientes([]);
      setLoading(false);
    }
  }, [user?.id]);

  return {
    pacientes,
    loading,
    createPaciente,
    updatePaciente,
    deletePaciente,
    refetch: fetchPacientes
  };
}

import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

export interface ContaPagar {
  id: string;
  fornecedor_id: string | null;
  descricao: string;
  categoria: string;
  valor: number;
  data_vencimento: string;
  status: string;
  observacoes: string | null;
  fornecedor_nome?: string;
}

export interface PagamentoData {
  conta_id: string;
  forma_pagamento: string;
  data_pagamento: string;
  valor_pago: number;
  observacoes?: string;
}

export const usePagamentos = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [contasPendentes, setContasPendentes] = useState<ContaPagar[]>([]);

  const fetchContasPendentes = async () => {
    if (!user) return;

    try {
      setLoading(true);

      // Buscar fornecedores primeiro
      const { data: fornecedores, error: fornecedoresError } = await supabase
        .from('fornecedores')
        .select('id, nome')
        .eq('user_id', user.id);

      if (fornecedoresError) throw fornecedoresError;

      // Buscar contas a pagar pendentes e vencidas
      const { data: contas, error: contasError } = await supabase
        .from('contas_pagar')
        .select('*')
        .eq('user_id', user.id)
        .in('status', ['Pendente', 'Vencida'])
        .order('data_vencimento', { ascending: true });

      if (contasError) throw contasError;

      // Mapear contas com nomes dos fornecedores
      const contasComFornecedores = (contas || []).map(conta => {
        const fornecedor = (fornecedores || []).find(f => f.id === conta.fornecedor_id);
        return {
          ...conta,
          fornecedor_nome: fornecedor?.nome || 'Fornecedor não especificado'
        };
      });

      setContasPendentes(contasComFornecedores);
    } catch (error: any) {
      console.error('Erro ao buscar contas pendentes:', error);
      toast.error('Erro ao carregar contas pendentes');
    } finally {
      setLoading(false);
    }
  };

  const efetuarPagamento = async (dados: PagamentoData) => {
    if (!user) {
      toast.error('Usuário não autenticado');
      return false;
    }

    try {
      const { error } = await supabase
        .from('contas_pagar')
        .update({
          status: 'Paga',
          data_pagamento: dados.data_pagamento,
          forma_pagamento: dados.forma_pagamento,
          observacoes: dados.observacoes || null,
          updated_at: new Date().toISOString()
        })
        .eq('id', dados.conta_id)
        .eq('user_id', user.id);

      if (error) throw error;

      toast.success('Pagamento efetuado com sucesso!');
      await fetchContasPendentes(); // Recarregar lista
      return true;
    } catch (error: any) {
      console.error('Erro ao efetuar pagamento:', error);
      toast.error('Erro ao efetuar pagamento');
      return false;
    }
  };

  useEffect(() => {
    fetchContasPendentes();
  }, [user]);

  return {
    contasPendentes,
    loading,
    efetuarPagamento,
    refetch: fetchContasPendentes
  };
};

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { startOfMonth, endOfMonth } from 'date-fns';

export interface PerformanceItem {
  id: string;
  nome: string;
  totalConcluido: number;
  tipo: 'DENTISTA' | 'PROTETICO';
}

export function usePerformanceStats() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ['performance-stats', user?.id],
    queryFn: async () => {
      if (!user?.id) return { dentistas: [], proteticos: [] };

      const tables = [
        'procedimentos_ppr', 'procedimentos_pt_pm', 'procedimentos_fixa',
        'procedimentos_protocolo', 'procedimentos_resina_impressa',
        'procedimentos_ceramica', 'procedimentos_placa',
        'procedimentos_provisorio', 'procedimentos_lab_externo'
      ];

      const hoje = new Date();
      const inicioMes = startOfMonth(hoje).toISOString();
      const fimMes = endOfMonth(hoje).toISOString();

      // Buscar todos os procedimentos concluídos no mês
      const results = await Promise.all(
        tables.map(table => 
          supabase
            .from(table as any)
            .select('dentista_id, protetico_id, status_geral, updated_at')
            .eq('user_id', user.id)
            .eq('status_geral', 'Concluído')
            .gte('updated_at', inicioMes)
            .lte('updated_at', fimMes)
        )
      );

      const dentistaCount: Record<string, number> = {};
      const proteticoCount: Record<string, number> = {};

      results.forEach(({ data }) => {
        if (data) {
          (data as any[]).forEach(proc => {
            if (proc.dentista_id) {
              dentistaCount[proc.dentista_id] = (dentistaCount[proc.dentista_id] || 0) + 1;
            }
            if (proc.protetico_id) {
              proteticoCount[proc.protetico_id] = (proteticoCount[proc.protetico_id] || 0) + 1;
            }
          });
        }
      });

      // Buscar nomes dos profissionais
      const dentistaIds = Object.keys(dentistaCount);
      const proteticoIds = Object.keys(proteticoCount);

      if (dentistaIds.length === 0 && proteticoIds.length === 0) {
        return { dentistas: [], proteticos: [] };
      }

      const [{ data: dentistasData }, { data: proteticosData }] = await Promise.all([
        dentistaIds.length > 0 
          ? (supabase as any).from('dentistas').select('id, nome').in('id', dentistaIds)
          : Promise.resolve({ data: [] }),
        proteticoIds.length > 0
          ? (supabase as any).from('proteticos').select('id, nome').in('id', proteticoIds)
          : Promise.resolve({ data: [] })
      ]);

      const performanceDentistas = (dentistasData || []).map((d: any) => ({
        id: d.id,
        nome: d.nome,
        totalConcluido: dentistaCount[d.id] || 0,
        tipo: 'DENTISTA' as const
      })).sort((a: any, b: any) => b.totalConcluido - a.totalConcluido);

      const performanceProteticos = (proteticosData || []).map((p: any) => ({
        id: p.id,
        nome: p.nome,
        totalConcluido: proteticoCount[p.id] || 0,
        tipo: 'PROTETICO' as const
      })).sort((a: any, b: any) => b.totalConcluido - a.totalConcluido);

      return {
        dentistas: performanceDentistas,
        proteticos: performanceProteticos
      };
    },
    enabled: !!user?.id,
  });
}

