// =====================================================
// CALCULAR STATUS GERAL BASEADO NAS ETAPAS
// =====================================================
export function calcularStatusGeralPlaca(
  procedimento: Partial<ProcedimentoPlaca>
): StatusProcedimento {
  const etapasFinalizadas = ETAPAS_PLACA.filter((etapa) => {
    const statusKey = `${etapa.key}_status` as keyof ProcedimentoPlaca;
    const status = procedimento[statusKey];
    return status === 'Finalizado' || status === 'Concluido';
  }).length;

  if (etapasFinalizadas === 0) {
    return 'Pendente';
  } else if (etapasFinalizadas === ETAPAS_PLACA.length) {
    return 'Concluído';
  } else {
    return 'Em andamento';
  }
}

