// Hook para atualizar uma etapa específica
export function useUpdateEtapa() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({
      procedimentoId,
      etapaKey,
      status,
      data,
      executorId,
      executorNome,
      tipoExecutor,
    }: {
      procedimentoId: string;
      etapaKey: string;
      status: StatusEtapa;
      data?: string;
      executorId?: string | number; // UUID para dentistas, number para protéticos
      executorNome?: string;
      tipoExecutor?: TipoExecutor;
    }) => {
      if (!user) throw new Error('Usuário não autenticado');

      if (data && data.ordem_servico) {
        await ensureOrdemServicoExists(data.ordem_servico, user.id, data.paciente_id, data.dentista_id);
      }

      // Preparar os campos para atualizar
      const updateData: any = {
        [`${etapaKey}_status`]: status,
      };

      if (data) {
        updateData[`${etapaKey}_data`] = data;
      }

      // Sempre salvar o nome do executor e a data de execução se fornecidos
      if (executorNome) {
        // Salvar executorId para protéticos (number) ou dentistas (UUID string)
        // Secretárias não têm executor_id
        if (executorId !== undefined && tipoExecutor !== 'SECRETARIA') {
          updateData[`${etapaKey}_executor_id`] = executorId;
        }
        updateData[`${etapaKey}_executado_em`] = getBrasiliaDateTime();
        updateData[`${etapaKey}_executado_por`] = executorNome;
      }

      // Atualizar o procedimento
      const { data: result, error } = await supabase
        .from('procedimentos_ppr')
        .update(updateData)
        .eq('id', procedimentoId)
        .select()
        .single();

      if (error) throw error;

      // Registrar no histórico
      const etapaConfig = ETAPAS_PPR.find((e) => e.key === etapaKey);
      if (etapaConfig) {
        await supabase.from('historico_procedimentos').insert({
          procedimento_tipo: 'PPR',
          procedimento_id: procedimentoId,
          ordem_servico: result.ordem_servico,
          nome_paciente: result.nome_paciente,
          etapa: etapaKey,
          etapa_label: etapaConfig.label,
          acao: status === 'Finalizado' ? 'CONCLUIU' : 'ALTEROU_STATUS',
          status_novo: status,
          executor_tipo: tipoExecutor,
          executor_id: executorId,
          executor_nome: executorNome,
          responsavel_esperado: etapaConfig.responsavel,
        });
      }

      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['procedimentos'] });
      queryClient.invalidateQueries({ queryKey: ['procedimento'] });
      queryClient.invalidateQueries({ queryKey: ['historico'] });
      toast({
        title: 'Sucesso!',
        description: 'Etapa atualizada com sucesso',
      });
    },
    onError: (error: any) => {
      toast({
        title: 'Erro ao atualizar etapa',
        description: error.message,
        variant: 'destructive',
      });
    },
  });
}

