// =====================================================
// CALCULAR STATUS GERAL BASEADO NAS ETAPAS
// =====================================================
export function calcularStatusGeralFixa(
  procedimento: Partial<ProcedimentoFixa>
): StatusProcedimento {
  const etapasFinalizadas = ETAPAS_FIXA.filter((etapa) => {
    const statusKey = `${etapa.key}_status` as keyof ProcedimentoFixa;
    const status = procedimento[statusKey];
    return status === 'Finalizado' || status === 'Concluido';
  }).length;

  if (etapasFinalizadas === 0) {
    return 'Pendente';
  } else if (etapasFinalizadas === ETAPAS_FIXA.length) {
    return 'Concluído';
  } else {
    return 'Em andamento';
  }
}

