// Hook para pegar histórico de um procedimento PROTOCOLO
export function useHistoricoProcedimentoProtocolo(ordemServico: number, tipoProtocolo: TipoProtocolo) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ['historico-protocolo', tipoProtocolo, ordemServico, user?.id],
    queryFn: async () => {
      if (!user) throw new Error('Usuário não autenticado');

      const procedimentoTipo = tipoProtocolo === 'PROVISORIO'
        ? 'PROTOCOLO PROVISORIO'
        : 'PROTOCOLO DEFINITIVO';

      const { data, error } = await supabase
        .from('historico_procedimentos')
        .select('*')
        .eq('ordem_servico', ordemServico)
        .eq('procedimento_tipo', procedimentoTipo)
        .order('executado_em', { ascending: false });

      if (error) throw error;
      return data;
    },
    enabled: !!user && !!ordemServico,
  });
}

// Hook para calcular status geral baseado nas etapas
export function calcularStatusGeralProtocolo(procedimento: Partial<ProcedimentoProtocolo>): 'Pendente' | 'Em andamento' | 'Concluído' {
  // Para PROVISORIO: 8 etapas (sem prova_barra)
  // Para DEFINITIVO: 9 etapas (com prova_barra)
  const etapasParaContar = procedimento.tipo_protocolo === 'PROVISORIO'
    ? ETAPAS_PROTOCOLO.filter(e => e.key !== 'prova_barra')
    : ETAPAS_PROTOCOLO;

  const etapasFinalizadas = etapasParaContar.filter((etapa) => {
    const statusKey = `${etapa.key}_status` as keyof ProcedimentoProtocolo;
    const status = procedimento[statusKey];
    return status === 'Finalizado' || status === 'Concluido';
  }).length;

  if (etapasFinalizadas === 0) {
    return 'Pendente';
  } else if (etapasFinalizadas === etapasParaContar.length) {
    return 'Concluído';
  } else {
    return 'Em andamento';
  }
}

