    },
    onError: (error: any) => {
      toast({
        title: 'Erro ao deletar procedimento',
        description: error.message,
        variant: 'destructive',
      });
    },
  });
}

// =====================================================
// ATUALIZAR UMA ETAPA ESPECÍFICA
// =====================================================
export function useUpdateEtapaResinaImpressa() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({
      procedimentoId,
      etapaKey,
      status,
      data,
      agenda,
      executorId,
      executorNome,
      tipoExecutor,
    }: {
      procedimentoId: string;
      etapaKey: string;
      status: StatusEtapa;
      data?: string;
      agenda?: string;
      executorId?: string | number;
      executorNome?: string;
      tipoExecutor?: TipoExecutor;
    }) => {
      if (!user) throw new Error('Usuário não autenticado');

      // Preparar dados de atualização
      const updateData: any = {
        [`${etapaKey}_status`]: status,
      };

      if (data) {
        updateData[`${etapaKey}_data`] = data;
      }

      if (agenda) {
        updateData[`${etapaKey}_agenda`] = agenda;
      }

      if (executorNome) {
        if (executorId !== undefined) {
          updateData[`${etapaKey}_executor_id`] = executorId;
        }
        updateData[`${etapaKey}_executado_em`] = new Date().toISOString();
        updateData[`${etapaKey}_executado_por`] = executorNome;
      }

      // Atualizar procedimento
      const { data: result, error } = await supabase
        .from('procedimentos_resina_impressa')
        .update(updateData)
        .eq('id', procedimentoId)
        .select()
        .single();

      if (error) throw error;

      // Registrar no histórico
      const etapaConfig = ETAPAS_RESINA_IMPRESSA.find((e) => e.key === etapaKey);
      if (etapaConfig) {
        await supabase.from('historico_procedimentos').insert({
          user_id: user.id,
          procedimento_tipo: 'RESINA IMPRESSA',
          procedimento_id: procedimentoId,
          ordem_servico: result.ordem_servico,
          nome_paciente: result.nome_paciente,
          etapa: etapaKey,
          etapa_label: etapaConfig.label,
          acao: status === 'Finalizado' || status === 'Concluido' ? 'CONCLUIU' : 'ALTEROU_STATUS',
          status_novo: status,
          executor_tipo: tipoExecutor,
          executor_id: executorId as number,
          executor_nome: executorNome,
          responsavel_esperado: etapaConfig.responsavel,
          executado_em: new Date().toISOString(),
        });
      }

      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['procedimentos-resina-impressa'] });
      queryClient.invalidateQueries({ queryKey: ['procedimento-resina-impressa'] });
      queryClient.invalidateQueries({ queryKey: ['todos-procedimentos-unificados'] });
      queryClient.invalidateQueries({ queryKey: ['historico'] });
      toast({
        title: 'Sucesso!',
        description: 'Etapa atualizada com sucesso',
      });
    },
    onError: (error: any) => {
      toast({
        title: 'Erro ao atualizar etapa',
        description: error.message,
        variant: 'destructive',
      });
    },
  });
}

