  return useQuery({
    queryKey: ['historico-resina-impressa', ordemServico, user?.id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('historico_procedimentos')
        .select('*')
        .eq('ordem_servico', ordemServico)
        .eq('procedimento_tipo', 'RESINA IMPRESSA')
        .order('executado_em', { ascending: false });

      if (error) throw error;
      return data;
    },
    enabled: !!user && !!ordemServico,
  });
}

// =====================================================
// CALCULAR STATUS GERAL BASEADO NAS ETAPAS
// =====================================================
export function calcularStatusGeralResinaImpressa(
  procedimento: Partial<ProcedimentoResinaImpressa>
): StatusProcedimento {
  const etapasFinalizadas = ETAPAS_RESINA_IMPRESSA.filter((etapa) => {
    const statusKey = `${etapa.key}_status` as keyof ProcedimentoResinaImpressa;
    const status = procedimento[statusKey];
    return status === 'Finalizado' || status === 'Concluido';
  }).length;

  if (etapasFinalizadas === 0) {
    return 'Pendente';
  } else if (etapasFinalizadas === ETAPAS_RESINA_IMPRESSA.length) {
    return 'Concluído';
  } else {
    return 'Em andamento';
  }
}

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

export interface ProcedimentoUnificado {
  id: string;
  ordem_servico: number;
  nome_paciente: string;
  data_entrada?: string;
  data_inicial?: string;
  data_saida?: string;
  data_entrega?: string;
  status?: string;
  status_geral: string;
  valor_total?: number;
  tipo: 'PPR' | 'PT/PM' | 'FIXA ORTOVITAL' | 'PROTOCOLO PROVISORIO' | 'PROTOCOLO DEFINITIVO' | 'RESINA IMPRESSA' | 'CERAMICA ORTOVITAL' | 'PLACA DE BRUXISMO/CLAREAMENTO' | 'PROVISORIO/ADESIVA' | 'LAB EXTERNO';
  tipo_original: string;
  [key: string]: any; // Para permitir campos de etapas dinâmicos
}

/**
 * Hook otimizado que busca TODOS os procedimentos de uma vez só
 * evitando o problema N+1 de múltiplas queries
 */
export function useTodosProcedimentos() {
  return useQuery({
    queryKey: ['todos-procedimentos-unificados'],
    queryFn: async () => {
      try {
        // Buscar todos os tipos de procedimentos em paralelo (com TODOS os campos)
        const [
          { data: pprData, error: pprError },
          { data: ptpmData, error: ptpmError },
          { data: fixaData, error: fixaError },
          { data: protocoloData, error: protocoloError },
          { data: resinaData, error: resinaError },
          { data: ceramicaData, error: ceramicaError },
          { data: placaData, error: placaError },
          { data: provisorioData, error: provisorioError },
          { data: labExternoData, error: labExternoError },
        ] = await Promise.all([
          supabase
            .from('procedimentos_ppr')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_pt_pm')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_fixa')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_protocolo')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_resina_impressa')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_ceramica')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_placa')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_provisorio')
            .select('*')
            .order('ordem_servico', { ascending: false }),

          supabase
            .from('procedimentos_lab_externo')
            .select('*')
            .order('ordem_servico', { ascending: false }),
        ]);

        // Verificar erros
        if (pprError) throw pprError;
        if (ptpmError) throw ptpmError;
        if (fixaError) throw fixaError;
        if (protocoloError) throw protocoloError;
        if (resinaError) throw resinaError;
        if (ceramicaError) throw ceramicaError;
        if (placaError) throw placaError;
        if (provisorioError) throw provisorioError;
        if (labExternoError) throw labExternoError;

        // Separar protocolos por tipo (aceitar variações)
        const protocoloProvisorio = (protocoloData || []).filter(p => {
          const tipo = p.tipo_protocolo?.toUpperCase();
          return tipo === 'PROVISORIO' || tipo === 'PROVISÓRIO';
        });
        const protocoloDefinitivo = (protocoloData || []).filter(p => {
          const tipo = p.tipo_protocolo?.toUpperCase();
          return tipo === 'DEFINITIVO';
        });

        // Unificar resultados com tipo identificado
        const procedimentos: ProcedimentoUnificado[] = [
          ...(pprData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente', // Garantir status_geral
            tipo: 'PPR' as const,
            tipo_original: 'procedimentos_ppr'
          })),
          ...(ptpmData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'PT/PM' as const,
            tipo_original: 'procedimentos_pt_pm'
          })),
          ...(fixaData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'FIXA ORTOVITAL' as const,
            tipo_original: 'procedimentos_fixa'
          })),
          ...protocoloProvisorio.map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'PROTOCOLO PROVISORIO' as const,
            tipo_original: 'procedimentos_protocolo'
          })),
          ...protocoloDefinitivo.map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'PROTOCOLO DEFINITIVO' as const,
            tipo_original: 'procedimentos_protocolo'
          })),
          ...(resinaData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'RESINA IMPRESSA' as const,
            tipo_original: 'procedimentos_resina_impressa'
          })),
          ...(ceramicaData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'CERAMICA ORTOVITAL' as const,
            tipo_original: 'procedimentos_ceramica'
          })),
          ...(placaData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'PLACA DE BRUXISMO/CLAREAMENTO' as const,
            tipo_original: 'procedimentos_placa'
          })),
          ...(provisorioData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'PROVISORIO/ADESIVA' as const,
            tipo_original: 'procedimentos_provisorio'
          })),
          ...(labExternoData || []).map(p => ({
            ...p,
            status_geral: p.status_geral || 'Pendente',
            tipo: 'LAB EXTERNO' as const,
            tipo_original: 'procedimentos_lab_externo'
          })),
        ];

        // Ordenar por data_inicial/data_entrada (mais recentes primeiro)
        procedimentos.sort((a, b) => {
          const dataA = a.data_inicial || a.data_entrada || '1970-01-01';
          const dataB = b.data_inicial || b.data_entrada || '1970-01-01';
          return new Date(dataB).getTime() - new Date(dataA).getTime();
        });

        return procedimentos;
      } catch (error) {
        // TODO: Implementar logging service em produção (Sentry/LogRocket)
        throw error;
      }
    },
    staleTime: 5 * 60 * 1000, // 5 minutos
    gcTime: 10 * 60 * 1000, // 10 minutos
  });
}

/**
 * Hook para buscar procedimentos separados por tipo
 * Usa o cache do hook principal para evitar queries duplicadas
 */
export function useProcedimentosPorTipo() {
  const { data: todos, isLoading, error } = useTodosProcedimentos();

  return {
    procedimentosPPR: todos?.filter(p => p.tipo === 'PPR') || [],
    procedimentosPTPM: todos?.filter(p => p.tipo === 'PT/PM') || [],
    procedimentosFixa: todos?.filter(p => p.tipo === 'FIXA') || [],
    procedimentosProtocolo: todos?.filter(p => p.tipo === 'PROT. PROV' || p.tipo === 'PROT. DEF') || [],
    todosProcedimentos: todos || [],
    isLoading,
    error,
  };
}

/**
 * Hook para estatísticas rápidas de procedimentos
 */
export function useEstatisticasProcedimentos() {
  const { data: todos, isLoading } = useTodosProcedimentos();

  const stats = {
    total: todos?.length || 0,
    porTipo: {
      ppr: todos?.filter(p => p.tipo === 'PPR').length || 0,
      ptpm: todos?.filter(p => p.tipo === 'PT/PM').length || 0,
      fixa: todos?.filter(p => p.tipo === 'FIXA').length || 0,
      protocoloProv: todos?.filter(p => p.tipo === 'PROT. PROV').length || 0,
      protocoloDef: todos?.filter(p => p.tipo === 'PROT. DEF').length || 0,
      resinaImpressa: todos?.filter(p => p.tipo === 'RESINA IMPRESSA').length || 0,
      ceramica: todos?.filter(p => p.tipo === 'CERAMICA').length || 0,
      placa: todos?.filter(p => p.tipo === 'PLACA').length || 0,
      provisorio: todos?.filter(p => p.tipo === 'PROVISORIO').length || 0,
      labExterno: todos?.filter(p => p.tipo === 'LAB EXTERNO').length || 0,
    },
    porStatus: {
      emAndamento: todos?.filter(p => p.status === 'Em andamento').length || 0,
      concluido: todos?.filter(p => p.status === 'Concluído').length || 0,
      pendente: todos?.filter(p => p.status === 'Pendente').length || 0,
    },
    valorTotal: todos?.reduce((sum, p) => sum + (p.valor_total || 0), 0) || 0,
  };

  return { stats, isLoading };
}

