  frete?: number
  taxa_adicional?: number
  total: number
  forma_pagamento?: string
  status_pagamento?: 'pendente' | 'pago' | 'estornado' | 'cancelado'
  data_pagamento?: string
  parcelas?: number
  link_pagamento?: string
  tipo_entrega?: string
  endereco_entrega?: Record<string, any>
  codigo_rastreio?: string
  transportadora?: string
  previsao_entrega?: string
  observacoes?: string
  observacoes_internas?: string
  atendente_id?: string
  origem?: string
  itens?: ItemPedido[]
}

export type PedidoCompleto = Pedido & {
  cliente?: {
    nome: string
    telefone: string
    whatsapp_id: string
  }
  itens_pedido?: ItemPedido[]
  atendente?: {
    nome: string
  }
}

export type FiltrosPedido = {
  cliente_id?: string
  status?: string[]
  status_pagamento?: string[]
  data_inicio?: string
  data_fim?: string
  forma_pagamento?: string
  atendente_id?: string
  busca?: string
}

class PedidosService {

  /**
   * Criar novo pedido
   */
  async criar(pedido: Pedido): Promise<SupabaseResponse<PedidoCompleto>> {
    const itens = pedido.itens || []
    delete pedido.itens

    // Inserir pedido
    const { data: pedidoData, error: pedidoError } = await supabase
      .from('pedidos')
      .insert({
        ...pedido,
        created_at: new Date().toISOString()
      })
      .select()
      .single()

    if (pedidoError) {
      return createResponse(null, pedidoError)
    }

    // Inserir itens
    if (itens.length > 0) {
      const itensComPedidoId = itens.map(item => ({
        ...item,
        pedido_id: pedidoData.id
      }))

      const { error: itensError } = await supabase
        .from('itens_pedido')
        .insert(itensComPedidoId)

      if (itensError) {
        // Rollback: deletar pedido se falhar ao inserir itens
        await supabase.from('pedidos').delete().eq('id', pedidoData.id)
        return createResponse(null, itensError)
      }
    }

    // Buscar pedido completo
    return this.buscarPorId(pedidoData.id)
  }

  /**
   * Buscar pedido por ID
   */
  async buscarPorId(id: string): Promise<SupabaseResponse<PedidoCompleto>> {
    const { data, error } = await supabase
      .from('pedidos')
      .select(`
        *,
        cliente:clientes(nome, telefone, whatsapp_id),
        atendente:users(nome),
        itens_pedido(
          *,
          produto:produtos(nome, sku, imagem_principal)
        )
      `)
      .eq('id', id)
      .single()

    return createResponse(data, error)
  }

  /**
   * Buscar pedido por número
   */
  async buscarPorNumero(numero_pedido: string): Promise<SupabaseResponse<PedidoCompleto>> {
    const { data, error } = await supabase
      .from('pedidos')
      .select(`
        *,
        cliente:clientes(nome, telefone, whatsapp_id),
        atendente:users(nome),
        itens_pedido(
          *,
          produto:produtos(nome, sku, imagem_principal)
        )
      `)
      .eq('numero_pedido', numero_pedido)
      .single()

    return createResponse(data, error)
  }

  /**
   * Listar pedidos com filtros
   */
  async listar(
    filtros: FiltrosPedido = {},
    page: number = 1,
    pageSize: number = 20
  ): Promise<SupabaseResponse<PedidoCompleto[]>> {
    let query = supabase
      .from('pedidos')
      .select(`
        *,
        cliente:clientes(nome, telefone),
        atendente:users(nome)
      `, { count: 'exact' })
      .order('created_at', { ascending: false })

    // Aplicar filtros
    if (filtros.cliente_id) {
      query = query.eq('cliente_id', filtros.cliente_id)
    }

    if (filtros.status && filtros.status.length > 0) {
      query = query.in('status', filtros.status)
    }

    if (filtros.status_pagamento && filtros.status_pagamento.length > 0) {
      query = query.in('status_pagamento', filtros.status_pagamento)
    }

    if (filtros.forma_pagamento) {
      query = query.eq('forma_pagamento', filtros.forma_pagamento)
    }

    if (filtros.atendente_id) {
      query = query.eq('atendente_id', filtros.atendente_id)
    }

    if (filtros.data_inicio) {
      query = query.gte('created_at', filtros.data_inicio)
    }

    if (filtros.data_fim) {
      query = query.lte('created_at', filtros.data_fim)
    }

    if (filtros.busca) {
      query = query.or(`numero_pedido.ilike.%${filtros.busca}%`)
    }

    return paginatedQuery(query, page, pageSize)
  }

  /**
   * Listar pedidos de um cliente
   */
  async listarPorCliente(cliente_id: string): Promise<SupabaseResponse<PedidoCompleto[]>> {
    const { data, error } = await supabase
      .from('pedidos')
      .select(`
        *,
        itens_pedido(
          *,
          produto:produtos(nome, imagem_principal)
        )
      `)
      .eq('cliente_id', cliente_id)
      .order('created_at', { ascending: false })

    return createResponse(data, error)
  }

  /**
   * Atualizar status do pedido
   */
  async atualizarStatus(
    id: string,
    status: Pedido['status']
  ): Promise<SupabaseResponse<Pedido>> {
    const { data, error } = await supabase
      .from('pedidos')
      .update({
        status,
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Atualizar status de pagamento
   */
  async atualizarPagamento(
    id: string,
    status_pagamento: Pedido['status_pagamento'],
    data_pagamento?: string
  ): Promise<SupabaseResponse<Pedido>> {
    const { data, error } = await supabase
      .from('pedidos')
      .update({
        status_pagamento,
        data_pagamento: data_pagamento || new Date().toISOString(),
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Adicionar código de rastreio
   */
  async adicionarRastreio(
    id: string,
    codigo_rastreio: string,
    transportadora?: string
  ): Promise<SupabaseResponse<Pedido>> {
    const { data, error } = await supabase
      .from('pedidos')
      .update({
        codigo_rastreio,
        transportadora,
        status: 'enviado',
        data_envio: new Date().toISOString(),
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Cancelar pedido
   */
  async cancelar(
    id: string,
    motivo: string,
    user_id?: string
  ): Promise<SupabaseResponse<Pedido>> {
    const { data, error } = await supabase
      .from('pedidos')
      .update({
        status: 'cancelado',
        motivo_cancelamento: motivo,
        cancelado_por: user_id,
        cancelado_em: new Date().toISOString(),
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Marcar como entregue
   */
  async marcarEntregue(id: string): Promise<SupabaseResponse<Pedido>> {
    const { data, error } = await supabase
      .from('pedidos')
      .update({
        status: 'entregue',
        data_entrega: new Date().toISOString(),
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Estatísticas de vendas
   */
  async estatisticasVendas(
    data_inicio?: string,
    data_fim?: string
  ): Promise<SupabaseResponse<any>> {
    let query = supabase
      .from('pedidos')
      .select('total, status_pagamento, created_at')
      .eq('status_pagamento', 'pago')

    if (data_inicio) {
      query = query.gte('created_at', data_inicio)
    }

    if (data_fim) {
      query = query.lte('created_at', data_fim)
    }

    const { data, error } = await query

    if (error) {
      return createResponse(null, error)
    }

    const total = data.reduce((acc, p) => acc + (p.total || 0), 0)
    const quantidade = data.length
    const ticket_medio = quantidade > 0 ? total / quantidade : 0

    return createResponse({
      total_vendas: total,
      quantidade_pedidos: quantidade,
      ticket_medio
    }, null)
  }

  /**
   * Produtos mais vendidos
   */
  async produtosMaisVendidos(limit: number = 10): Promise<SupabaseResponse<any[]>> {
    const { data, error } = await supabase
      .from('itens_pedido')
      .select(`
        produto_id,
        produto_nome,
        quantidade,
        produto:produtos(imagem_principal)
      `)

    if (error) {
      return createResponse(null, error)
    }

    // Agrupar e somar quantidades
    const agrupado = data.reduce((acc: any, item: any) => {
      const key = item.produto_id
      if (!acc[key]) {
        acc[key] = {
          produto_id: item.produto_id,
          produto_nome: item.produto_nome,
          imagem: item.produto?.imagem_principal,
          total_vendido: 0
        }
      }
      acc[key].total_vendido += item.quantidade
      return acc
    }, {})

    const ranking = Object.values(agrupado)
      .sort((a: any, b: any) => b.total_vendido - a.total_vendido)
      .slice(0, limit)

    return createResponse(ranking, null)
  }
}

export const pedidosService = new PedidosService()
export default pedidosService

/**
 * Serviço de Produtos - Gerenciamento de catálogo
 */

import { supabase, createResponse, paginatedQuery, type SupabaseResponse } from '../client'

export type Produto = {
  id?: string
  sku?: string
  codigo_barras?: string
  nome: string
  descricao?: string
  categoria?: string
  subcategoria?: string
  preco: number
  preco_promocional?: number
  custo?: number
  margem_lucro?: number
  estoque_atual?: number
  estoque_minimo?: number
  estoque_maximo?: number
  controla_estoque?: boolean
  peso?: number
  dimensoes?: Record<string, any>
  imagem_principal?: string
  imagens?: string[]
  tem_variacoes?: boolean
  variacoes?: any[]
  tags?: string[]
  palavras_chave?: string
  ativo?: boolean
  destaque?: boolean
  fornecedor?: string
  link_fornecedor?: string
}

export type FiltrosProduto = {
  categoria?: string
  busca?: string
  preco_min?: number
  preco_max?: number
  ativo?: boolean
  estoque_baixo?: boolean
  destaque?: boolean
  tags?: string[]
}

class ProdutosService {

  /**
   * Criar novo produto
   */
  async criar(produto: Produto): Promise<SupabaseResponse<Produto>> {
    const { data, error } = await supabase
      .from('produtos')
      .insert({
        ...produto,
        created_at: new Date().toISOString()
      })
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Buscar produto por ID
   */
  async buscarPorId(id: string): Promise<SupabaseResponse<Produto>> {
    const { data, error } = await supabase
      .from('produtos')
      .select('*')
      .eq('id', id)
      .single()

    return createResponse(data, error)
  }

  /**
   * Buscar produto por SKU
   */
  async buscarPorSku(sku: string): Promise<SupabaseResponse<Produto>> {
    const { data, error } = await supabase
      .from('produtos')
      .select('*')
      .eq('sku', sku)
      .single()

    return createResponse(data, error)
  }

  /**
   * Listar produtos com filtros
   */
  async listar(
    filtros: FiltrosProduto = {},
    page: number = 1,
    pageSize: number = 20
  ): Promise<SupabaseResponse<Produto[]>> {
    let query = supabase
      .from('produtos')
      .select('*', { count: 'exact' })
      .order('created_at', { ascending: false })

    // Aplicar filtros
    if (filtros.categoria) {
      query = query.eq('categoria', filtros.categoria)
    }

    if (filtros.ativo !== undefined) {
      query = query.eq('ativo', filtros.ativo)
    }

    if (filtros.destaque) {
      query = query.eq('destaque', true)
    }

    if (filtros.estoque_baixo) {
      query = query.lte('estoque_atual', supabase.rpc('estoque_minimo'))
    }

    if (filtros.preco_min !== undefined) {
      query = query.gte('preco', filtros.preco_min)
    }

    if (filtros.preco_max !== undefined) {
      query = query.lte('preco', filtros.preco_max)
    }

    if (filtros.tags && filtros.tags.length > 0) {
      query = query.contains('tags', filtros.tags)
    }

    if (filtros.busca) {
      query = query.or(`nome.ilike.%${filtros.busca}%,descricao.ilike.%${filtros.busca}%,sku.ilike.%${filtros.busca}%`)
    }

    return paginatedQuery(query, page, pageSize)
  }

  /**
   * Atualizar produto
   */
  async atualizar(id: string, dados: Partial<Produto>): Promise<SupabaseResponse<Produto>> {
    const { data, error } = await supabase
      .from('produtos')
      .update({
        ...dados,
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Atualizar estoque
   */
  async atualizarEstoque(id: string, quantidade: number): Promise<SupabaseResponse<Produto>> {
    const { data, error } = await supabase
      .from('produtos')
      .update({
        estoque_atual: quantidade,
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single()

    return createResponse(data, error)
  }

  /**
   * Adicionar estoque
   */
  async adicionarEstoque(id: string, quantidade: number): Promise<SupabaseResponse<Produto>> {
    const produto = await this.buscarPorId(id)
    if (!produto.data) return createResponse(null, produto.error)

    const novoEstoque = (produto.data.estoque_atual || 0) + quantidade
    return this.atualizarEstoque(id, novoEstoque)
  }

  /**
   * Remover estoque
   */
  async removerEstoque(id: string, quantidade: number): Promise<SupabaseResponse<Produto>> {
    const produto = await this.buscarPorId(id)
    if (!produto.data) return createResponse(null, produto.error)

    const novoEstoque = Math.max(0, (produto.data.estoque_atual || 0) - quantidade)
    return this.atualizarEstoque(id, novoEstoque)
  }

  /**
   * Buscar produtos com estoque baixo
   */
  async produtosEstoqueBaixo(): Promise<SupabaseResponse<Produto[]>> {
    const { data, error } = await supabase
      .from('produtos')
      .select('*')
      .lte('estoque_atual', supabase.raw('estoque_minimo'))
      .eq('controla_estoque', true)
      .order('estoque_atual', { ascending: true })

    return createResponse(data, error)
  }

  /**
   * Buscar produtos em destaque
   */
  async produtosDestaque(limit: number = 10): Promise<SupabaseResponse<Produto[]>> {
    const { data, error } = await supabase
      .from('produtos')
      .select('*')
      .eq('destaque', true)
      .eq('ativo', true)
      .order('total_vendido', { ascending: false })
      .limit(limit)

    return createResponse(data, error)
  }

  /**
   * Buscar categorias disponíveis
   */
  async listarCategorias(): Promise<SupabaseResponse<string[]>> {
    const { data, error } = await supabase
      .from('produtos')
      .select('categoria')
      .not('categoria', 'is', null)

    if (error) {
      return createResponse(null, error)
    }

    const categorias = [...new Set(data.map((p: any) => p.categoria).filter(Boolean))]
    return createResponse(categorias, null)
  }

  /**
   * Ativar/Desativar produto
   */
  async toggleAtivo(id: string): Promise<SupabaseResponse<Produto>> {
    const produto = await this.buscarPorId(id)
    if (!produto.data) return createResponse(null, produto.error)

    return this.atualizar(id, { ativo: !produto.data.ativo })
  }

  /**
   * Deletar produto
   */
  async deletar(id: string): Promise<SupabaseResponse<void>> {
    const { error } = await supabase
      .from('produtos')
      .delete()
      .eq('id', id)

    return createResponse(null, error)
  }

  /**
   * Importar produtos em massa (CSV/JSON)
   */
  async importarEmMassa(produtos: Produto[]): Promise<SupabaseResponse<Produto[]>> {
    const { data, error } = await supabase
      .from('produtos')
      .insert(produtos)
      .select()

    return createResponse(data, error)
  }
}

export const produtosService = new ProdutosService()
export default produtosService

/**
 * Sistema de Sincronização Inteligente
 * Gerencia dados entre Chrome Storage (local) e Supabase (remoto)
 */

import { supabase } from '../supabase/client'
import { clientesService, pedidosService, produtosService } from '../supabase/services'

type SyncQueueItem = {
  id: string
  table: string
  action: 'create' | 'update' | 'delete'
  data: any
  timestamp: number
  retries: number
}

type SyncStatus = 'idle' | 'syncing' | 'error'

export class SyncManager {
  private queue: SyncQueueItem[] = []
  private status: SyncStatus = 'idle'
  private maxRetries = 3
  private syncInterval: number = 30000 // 30 segundos
  private intervalId?: number
  private listeners: Map<string, Function[]> = new Map()

  constructor() {
    this.loadQueueFromStorage()
    this.startAutoSync()
    this.setupOnlineListener()
  }

  /**
   * Iniciar sincronização automática
   */
  private startAutoSync() {
    this.intervalId = window.setInterval(() => {
      this.sync()
    }, this.syncInterval)
  }

  /**
   * Parar sincronização automática
   */
  stopAutoSync() {
    if (this.intervalId) {
      clearInterval(this.intervalId)
    }
  }

  /**
   * Detectar quando voltar online
   */
  private setupOnlineListener() {
    window.addEventListener('online', () => {
      console.log('🌐 Conexão restaurada - iniciando sincronização')
      this.sync()
    })
  }

  /**
   * Adicionar item à fila de sincronização
   */
  private addToQueue(item: Omit<SyncQueueItem, 'id' | 'timestamp' | 'retries'>) {
    const queueItem: SyncQueueItem = {
      ...item,
      id: crypto.randomUUID(),
      timestamp: Date.now(),
      retries: 0
    }

    this.queue.push(queueItem)
    this.saveQueueToStorage()
    this.emit('queue-updated', this.queue.length)

    // Tentar sincronizar imediatamente
    this.sync()
  }

  /**
   * Salvar localmente e adicionar à fila de sincronização
   */
  async saveLocal<T>(table: string, key: string, data: T): Promise<T> {
    // Salvar no Chrome Storage primeiro (performance)
    await chrome.storage.local.set({ [key]: data })

    // Adicionar à fila para sincronizar com Supabase
    this.addToQueue({
      table,
      action: 'update',
      data: { key, value: data }
    })

    return data
  }

  /**
   * Criar/Atualizar registro no Supabase e cachear localmente
   */
  async upsert(table: string, data: any): Promise<any> {
    // Salvar local primeiro para UX rápida
    const cacheKey = `cache_${table}_${data.id || 'new'}`
    await chrome.storage.local.set({ [cacheKey]: data })

    // Adicionar à fila
    this.addToQueue({
      table,
      action: data.id ? 'update' : 'create',
      data
    })

    return data
  }

  /**
   * Deletar registro
   */
  async delete(table: string, id: string): Promise<void> {
    // Remover do cache local
    const cacheKey = `cache_${table}_${id}`
    await chrome.storage.local.remove(cacheKey)

    // Adicionar à fila
    this.addToQueue({
      table,
      action: 'delete',
      data: { id }
    })
  }

  /**
   * Buscar dados (cache first)
   */
  async fetch<T>(table: string, id: string, force: boolean = false): Promise<T | null> {
    const cacheKey = `cache_${table}_${id}`

    if (!force) {
      // Tentar buscar do cache primeiro
      const cached = await chrome.storage.local.get(cacheKey)
      if (cached[cacheKey]) {
        return cached[cacheKey] as T
      }
    }

    // Se não tiver no cache ou force=true, buscar do Supabase
    try {
      const { data } = await supabase
        .from(table)
        .select('*')
        .eq('id', id)
        .single()

      if (data) {
        // Cachear para próximas consultas
        await chrome.storage.local.set({ [cacheKey]: data })
        return data as T
      }
    } catch (error) {
      console.error(`Erro ao buscar ${table}:${id}`, error)
    }

    return null
  }

  /**
   * Sincronizar fila com Supabase
   */
  async sync(): Promise<void> {
    if (this.status === 'syncing' || this.queue.length === 0) {
      return
    }

    if (!navigator.onLine) {
      console.log('📡 Offline - sincronização adiada')
      return
    }

    this.status = 'syncing'
    this.emit('sync-start')

    console.log(`🔄 Sincronizando ${this.queue.length} itens...`)

    const itemsToSync = [...this.queue]
    const successfulIds: string[] = []

    for (const item of itemsToSync) {
      try {
        await this.syncItem(item)
        successfulIds.push(item.id)
        this.emit('item-synced', item)
      } catch (error) {
        console.error(`Erro ao sincronizar item ${item.id}:`, error)

        // Incrementar retries
        item.retries++

        if (item.retries >= this.maxRetries) {
          console.error(`Item ${item.id} excedeu máximo de tentativas`)
          this.emit('item-failed', item)
          successfulIds.push(item.id) // Remover da fila
        }
      }
    }

    // Remover itens sincronizados da fila
    this.queue = this.queue.filter(item => !successfulIds.includes(item.id))
    await this.saveQueueToStorage()

    this.status = 'idle'
    this.emit('sync-complete', successfulIds.length)

    console.log(`✅ Sincronização concluída: ${successfulIds.length}/${itemsToSync.length}`)
  }

  /**
   * Sincronizar um item específico
   */
  private async syncItem(item: SyncQueueItem): Promise<void> {
    const { table, action, data } = item

    switch (table) {
      case 'clientes':
        return this.syncCliente(action, data)

      case 'pedidos':
        return this.syncPedido(action, data)

      case 'produtos':
        return this.syncProduto(action, data)

      default:
        // Sincronização genérica
        return this.syncGeneric(table, action, data)
    }
  }

  /**
   * Sincronizar cliente
   */
  private async syncCliente(action: string, data: any): Promise<void> {
    switch (action) {
      case 'create':
        await clientesService.criar(data)
        break

      case 'update':
        if (data.id) {
          await clientesService.atualizar(data.id, data)
        }
        break

      case 'delete':
        if (data.id) {
          await clientesService.deletar(data.id)
        }
        break
    }
  }

  /**
   * Sincronizar pedido
   */
  private async syncPedido(action: string, data: any): Promise<void> {
    switch (action) {
      case 'create':
        await pedidosService.criar(data)
        break

      case 'update':
        if (data.id && data.status) {
          await pedidosService.atualizarStatus(data.id, data.status)
        }
        break

      case 'delete':
        if (data.id) {
          await pedidosService.cancelar(data.id, 'Cancelado pelo usuário')
        }
        break
    }
  }

  /**
   * Sincronizar produto
   */
  private async syncProduto(action: string, data: any): Promise<void> {
    switch (action) {
      case 'create':
        await produtosService.criar(data)
        break

      case 'update':
        if (data.id) {
          await produtosService.atualizar(data.id, data)
        }
        break

      case 'delete':
        if (data.id) {
          await produtosService.deletar(data.id)
        }
        break
    }
  }

  /**
   * Sincronização genérica
   */
  private async syncGeneric(table: string, action: string, data: any): Promise<void> {
    switch (action) {
      case 'create':
      case 'update':
        await supabase.from(table).upsert(data)
        break

      case 'delete':
        await supabase.from(table).delete().eq('id', data.id)
        break
    }
  }

  /**
   * Salvar fila no storage
   */
  private async saveQueueToStorage() {
    await chrome.storage.local.set({
      sync_queue: this.queue,
      sync_queue_updated: Date.now()
    })
  }

  /**
   * Carregar fila do storage
   */
  private async loadQueueFromStorage() {
    const result = await chrome.storage.local.get('sync_queue')
    if (result.sync_queue) {
      this.queue = result.sync_queue
      console.log(`📥 Fila de sincronização carregada: ${this.queue.length} itens`)
    }
  }

  /**
   * Limpar cache local
   */
  async clearCache() {
    const keys = await chrome.storage.local.get(null)
    const cacheKeys = Object.keys(keys).filter(k => k.startsWith('cache_'))

    await chrome.storage.local.remove(cacheKeys)
    console.log(`🗑️ Cache limpo: ${cacheKeys.length} itens removidos`)
  }

  /**
   * Forçar sincronização completa (pull do Supabase)
   */
  async fullSync() {
    console.log('🔄 Iniciando sincronização completa...')

    try {
      // Buscar todos os dados do Supabase
      const [clientes, pedidos, produtos] = await Promise.all([
        clientesService.listar({}, 1, 1000),
        pedidosService.listar({}, 1, 1000),
        produtosService.listar({}, 1, 1000)
      ])

      // Salvar no cache local
      await chrome.storage.local.set({
        cache_clientes: clientes.data || [],
        cache_pedidos: pedidos.data || [],
        cache_produtos: produtos.data || [],
        last_full_sync: Date.now()
      })

      console.log('✅ Sincronização completa concluída')
      this.emit('full-sync-complete')
    } catch (error) {
      console.error('❌ Erro na sincronização completa:', error)
      this.emit('full-sync-error', error)
    }
  }

  /**
   * Event emitter
   */
  on(event: string, callback: Function) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, [])
    }
    this.listeners.get(event)!.push(callback)
  }

  off(event: string, callback: Function) {
    const callbacks = this.listeners.get(event)
    if (callbacks) {
      const index = callbacks.indexOf(callback)
      if (index > -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  private emit(event: string, ...args: any[]) {
    const callbacks = this.listeners.get(event)
    if (callbacks) {
      callbacks.forEach(callback => callback(...args))
    }
  }

  /**
   * Status da sincronização
   */
  getStatus() {
    return {
      status: this.status,
      queueLength: this.queue.length,
      isOnline: navigator.onLine
    }
  }
}

