    if (editingAgendamento) {
      await updateAgendamento((editingAgendamento as any).id, data);
    } else {
      await createAgendamento(data);
    }
  };

  const handleEdit = (agendamento: any) => {
    setEditingAgendamento(agendamento);
    setDialogOpen(true);
  };

  const handleDelete = async () => {
