                </div>
              </CardHeader>
              <CardContent>
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Status</label>
                    <Select value={statusFilter} onValueChange={setStatusFilter}>
                      <SelectTrigger><SelectValue placeholder="Selecione o status" /></SelectTrigger>
                      <SelectContent>
                        {statusOptions.map(status => (
                          <SelectItem key={status} value={status}>{status}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Dentista</label>
                    <Select value={dentistaFilter} onValueChange={setDentistaFilter}>
                      <SelectTrigger><SelectValue placeholder="Selecione o dentista" /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Todos">Todos</SelectItem>
                        {dentistas.map(dentista => (
                          <SelectItem key={dentista.id} value={dentista.id}>{dentista.nome}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Protético</label>
                    <Select value={proteticoFilter} onValueChange={setProteticoFilter}>
                      <SelectTrigger><SelectValue placeholder="Selecione o protético" /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Todos">Todos</SelectItem>
                        {proteticos.map((protetico: any) => (
                          <SelectItem key={protetico.id} value={protetico.id.toString()}>{protetico.nome}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Paciente</label>
                    <Select value={pacienteFilter} onValueChange={setPacienteFilter}>
                      <SelectTrigger><SelectValue placeholder="Selecione o paciente" /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Todos">Todos</SelectItem>
                        {pacientes.map(paciente => (
                          <SelectItem key={paciente.id} value={paciente.id}>{paciente.nome}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Procedimento</label>
