                        <div key={appointment.id} className="p-4 border border-border rounded-lg bg-card hover:bg-muted/30 transition-colors space-y-3">
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex items-center gap-3">
                              <Avatar className="h-10 w-10">
                                <AvatarFallback className="gradient-secondary text-white text-sm font-semibold">
                                  {getInitials(appointment.pacientes?.nome)}
                                </AvatarFallback>
                              </Avatar>
                              <div>
                                <p className="font-semibold text-base">{appointment.pacientes?.nome || "Paciente"}</p>
                                <p className="text-sm text-muted-foreground flex items-center gap-1">
                                  <Clock className="w-3.5 h-3.5" /> {format(dataAgendamento, "HH:mm")} ({appointment.duracao} min)
                                </p>
                              </div>
                            </div>
                            <Badge className={cn("text-xs", getStatusColor(appointment.status))}>
                              {appointment.status}
                            </Badge>
                          </div>

                          <div className="space-y-1 bg-muted/30 p-2 rounded-md">
                            <p className="font-medium text-primary">{appointment.procedimento}</p>
                            <p className="text-sm text-muted-foreground">
                              {appointment.dentistas?.nome 
                                ? `Dr(a). ${appointment.dentistas.nome}`
                                : appointment.proteticos?.nome 
                                  ? `Protético(a) ${appointment.proteticos.nome}`
                                  : "Profissional"
                              }
                            </p>
                          </div>

                          <div className="flex justify-end gap-2 pt-2 border-t text-sm">
                            {!appointment.confirmado && appointment.status === "Agendado" && (
                              <Button variant="outline" size="sm" onClick={() => confirmarAgendamento(appointment.id)}>
                                Confirmar
                              </Button>
                            )}
                            <Button variant="ghost" size="sm" onClick={() => handleEdit(appointment)}>
                              <Edit className="h-4 w-4 mr-1" /> Editar
                            </Button>
                            <Button variant="ghost" size="sm" onClick={() => setDeleteId(appointment.id)} className="text-destructive hover:text-destructive">
                              <Trash2 className="h-4 w-4 mr-1" /> Excluir
                            </Button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          </motion.div>
        </TabsContent>
      </Tabs>

        <AgendamentoForm open={dialogOpen} onOpenChange={setDialogOpen} onSubmit={handleSubmit} agendamento={editingAgendamento} />

        <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Confirmar exclusão</AlertDialogTitle>
              <AlertDialogDescription>Tem certeza que deseja excluir este agendamento? Esta ação não pode ser desfeita.</AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancelar</AlertDialogCancel>
              <AlertDialogAction onClick={handleDelete}>Excluir</AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </motion.div>
    </DashboardLayout>
  );
}

