                         (patient.telefone || '').includes(searchTerm);

    const matchesStatus = selectedStatus === "all" || 
                         (patient.status === "Ativo" && selectedStatus === "active") ||
                         (patient.status === "Inativo" && selectedStatus === "inactive");

