                    onChange={(e) => handleChange("telefone", e.target.value)}
                    placeholder="(00) 0000-0000"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="celular">Celular</Label>
                  <Input
                    id="celular"
