import { useState, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Filter, Plus, ClipboardList, Calendar, User, Home, ArrowLeft } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { useProcedimentosPTPM } from '@/hooks/useProcedimentosPTPM';
import { StatusProcedimento, ETAPAS_PT_PM, TipoExecutor } from '@/types/procedimentos';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

// Função para obter a última modificação de um procedimento PT/PM
function getUltimaModificacao(proc: any): {
  etapaLabel: string;
  responsavel: TipoExecutor;
  executadoPor: string;
  executadoEm: string | null;
} | null {
  let ultimaData: Date | null = null;
  let ultimaEtapa: { label: string; responsavel: TipoExecutor } | null = null;
  let executadoPor = '';
  let executadoEm: string | null = null;

  for (const etapa of ETAPAS_PT_PM) {
    const executadoEmKey = `${etapa.key}_executado_em` as keyof typeof proc;
    const executadoPorKey = `${etapa.key}_executado_por` as keyof typeof proc;
    const dataExecucao = proc[executadoEmKey];

    if (dataExecucao) {
      const data = new Date(dataExecucao);
      if (!ultimaData || data > ultimaData) {
        ultimaData = data;
        ultimaEtapa = { label: etapa.label, responsavel: etapa.responsavel };
        executadoPor = proc[executadoPorKey] || '';
        executadoEm = dataExecucao;
      }
    }
  }

  if (ultimaEtapa) {
    return {
      etapaLabel: ultimaEtapa.label,
      responsavel: ultimaEtapa.responsavel,
      executadoPor,
      executadoEm,
    };
  }

  return null;
}

// Função para obter a cor baseada no responsável
function getCorResponsavelCard(responsavel: TipoExecutor): string {
  switch (responsavel) {
    case 'DENTISTA':
      return 'bg-blue-50 border-blue-300 text-blue-800';
    case 'PROTETICO':
      return 'bg-orange-50 border-orange-300 text-orange-800';
    case 'SECRETARIA':
      return 'bg-green-50 border-green-300 text-green-800';
    default:
      return 'bg-gray-50 border-gray-300 text-gray-800';
  }
}

export default function PTPMListPage() {
  const navigate = useNavigate();
  const { data: procedimentos, isLoading } = useProcedimentosPTPM();
  const [filtroStatus, setFiltroStatus] = useState<string>('todos');

  // Filtrar e ordenar por última modificação
  const procedimentosFiltrados = useMemo(() => {
    let filtered = filtroStatus === 'todos'
      ? procedimentos
      : procedimentos?.filter((p) => p.status_geral === filtroStatus);

    if (!filtered) return filtered;

    // Ordenar por última modificação (mais recente primeiro)
    return [...filtered].sort((a, b) => {
      const ultimaA = getUltimaModificacao(a);
      const ultimaB = getUltimaModificacao(b);

      if (!ultimaA?.executadoEm && !ultimaB?.executadoEm) {
        return b.ordem_servico - a.ordem_servico; // Fallback: ordem de serviço
      }
      if (!ultimaA?.executadoEm) return 1;
      if (!ultimaB?.executadoEm) return -1;

      return new Date(ultimaB.executadoEm).getTime() - new Date(ultimaA.executadoEm).getTime();
    });
  }, [procedimentos, filtroStatus]);

  const getStatusColor = (status: StatusProcedimento) => {
    switch (status) {
      case 'Concluído':
        return 'bg-green-100 text-green-800 border-green-300';
      case 'Em andamento':
        return 'bg-blue-100 text-blue-800 border-blue-300';
      case 'Pendente':
        return 'bg-yellow-100 text-yellow-800 border-yellow-300';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="mb-6">
          <Skeleton className="h-10 w-64 mb-2" />
          <Skeleton className="h-6 w-96" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <Card key={i}>
              <CardHeader>
                <Skeleton className="h-6 w-32 mb-2" />
                <Skeleton className="h-8 w-48" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-4 w-full mb-2" />
                <Skeleton className="h-4 w-full mb-2" />
                <Skeleton className="h-4 w-2/3" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-6">
          <Button
            variant="outline"
            onClick={() => navigate('/')}
            className="gap-2 border-2 hover:border-primary hover:bg-primary/5 transition-all duration-200 shadow-sm hover:shadow-md font-semibold"
          >
            <Home className="w-4 h-4" />
            <span className="hidden sm:inline">Voltar ao Menu</span>
            <span className="sm:hidden">Menu</span>
          </Button>
        </div>
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-6 bg-gradient-to-r from-primary/5 via-primary/3 to-transparent rounded-xl border-l-4 border-l-primary shadow-sm">
          <div>
            <h1 className="text-2xl sm:text-3xl font-bold text-foreground flex items-center gap-3">
              <div className="p-2 bg-primary rounded-lg">
                <ClipboardList className="w-6 h-6 sm:w-7 sm:h-7 text-white" />
              </div>
              Procedimentos PT/PM
            </h1>
            <p className="text-muted-foreground mt-2 ml-0 sm:ml-11">
              📊 {procedimentos?.length || 0} procedimento(s) cadastrado(s)
            </p>
          </div>
          <div className="flex gap-3">
            <Button
              variant="outline"
              onClick={() => navigate('/procedimentos')}
              className="gap-2"
            >
              <ArrowLeft className="w-4 h-4" />
              Voltar
            </Button>
            <Link to="/procedimentos/pt-pm/novo">
              <Button className="gap-2 bg-gradient-to-r from-primary to-primary/80 hover:from-primary/90 hover:to-primary/70 shadow-md hover:shadow-lg transition-all duration-200 font-semibold text-base h-11">
                <Plus className="w-5 h-5" />
                Novo Procedimento PT/PM
              </Button>
            </Link>
          </div>
        </div>
      </div>

      {/* Filtros */}
      <div className="mb-6 flex flex-col sm:flex-row items-start sm:items-center gap-4 p-4 bg-gray-50 rounded-xl border shadow-sm">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-white rounded-lg shadow-sm">
            <Filter className="w-5 h-5 text-primary" />
          </div>
          <span className="font-semibold text-gray-700">Filtrar:</span>
        </div>
        <Select value={filtroStatus} onValueChange={setFiltroStatus}>
          <SelectTrigger className="w-full sm:w-[250px] border-2 hover:border-primary/50 transition-colors h-11">
            <SelectValue placeholder="Filtrar por status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="todos">📋 Todos os Status</SelectItem>
            <SelectItem value="Pendente">⏳ Pendente</SelectItem>
            <SelectItem value="Em andamento">🔄 Em andamento</SelectItem>
            <SelectItem value="Concluído">✅ Concluído</SelectItem>
          </SelectContent>
        </Select>
        <Badge variant="outline" className="bg-white border-2 px-3 py-1.5 text-sm font-semibold">
          {procedimentosFiltrados?.length || 0} resultado(s)
        </Badge>
      </div>

      {/* Grid de Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {!procedimentosFiltrados || procedimentosFiltrados.length === 0 ? (
          <div className="col-span-full">
            <Card className="p-12 text-center bg-gradient-to-br from-gray-50 to-white border-2 border-dashed border-gray-300 shadow-lg">
              <div className="p-4 bg-primary/10 rounded-full w-24 h-24 mx-auto mb-6 flex items-center justify-center">
                <ClipboardList className="w-12 h-12 text-primary" />
              </div>
              <h3 className="text-2xl font-bold mb-3 text-gray-800">
                Nenhum procedimento encontrado
              </h3>
              <p className="text-muted-foreground mb-8 text-lg">
                {filtroStatus === 'todos'
                  ? '✨ Comece criando seu primeiro procedimento PT/PM'
                  : '🔍 Não há procedimentos com este status'}
              </p>
              {filtroStatus === 'todos' && (
                <Link to="/procedimentos/pt-pm/novo">
                  <Button className="gap-2 bg-gradient-to-r from-primary to-primary/80 hover:from-primary/90 hover:to-primary/70 shadow-md hover:shadow-lg transition-all duration-200 font-semibold text-base h-12 px-8">
                    <Plus className="w-5 h-5" />
                    Criar Primeiro Procedimento
                  </Button>
                </Link>
              )}
            </Card>
          </div>
        ) : (
          procedimentosFiltrados.map((proc: any) => {
            const ultimaModificacao = getUltimaModificacao(proc);

            return (
              <Link
                key={proc.id}
                to={`/procedimentos/pt-pm/${proc.ordem_servico}`}
                className="block transition-all hover:scale-[1.02] active:scale-[0.98]"
              >
                <Card className="h-full hover:shadow-xl transition-all duration-300 cursor-pointer border-2 hover:border-primary group bg-gradient-to-br from-white to-gray-50/30">
                  <CardHeader className="pb-3">
                    <div className="flex justify-between items-start mb-3">
                      <div className="flex-1">
                        <span className="text-xs font-medium text-muted-foreground">
                          OS #{proc.ordem_servico.toString().padStart(6, '0')}
                        </span>
                        <CardTitle className="mt-1 text-2xl font-bold group-hover:text-primary transition-colors">
                          {proc.nome_paciente}
                        </CardTitle>
                        {proc.tipo_protese && (
                          <Badge variant="outline" className="mt-2 bg-purple-100 text-purple-800 border-purple-300">
                            {proc.tipo_protese === 'PT' ? 'Prótese Total' : 'Prótese Móvel'}
                          </Badge>
                        )}
                      </div>
                    </div>
                  </CardHeader>

                  <CardContent className="space-y-3 pt-0">
                    {/* Última modificação com cor do responsável */}
                    {ultimaModificacao ? (
                      <div className={`p-3 rounded-lg border-2 ${getCorResponsavelCard(ultimaModificacao.responsavel)}`}>
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-xs font-semibold uppercase tracking-wide opacity-75">
                            Última Etapa
                          </span>
                          <Badge variant="outline" className="text-xs font-bold bg-white/50">
                            {ultimaModificacao.responsavel}
                          </Badge>
                        </div>
                        <p className="font-bold text-base">{ultimaModificacao.etapaLabel}</p>
                        <p className="text-sm mt-1">
                          por <span className="font-semibold">{ultimaModificacao.executadoPor}</span>
                        </p>
                        {ultimaModificacao.executadoEm && (
                          <p className="text-xs mt-1 opacity-75">
                            {!isNaN(new Date(ultimaModificacao.executadoEm).getTime()) ? format(new Date(ultimaModificacao.executadoEm), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR }) : ''}
                          </p>
                        )}
                      </div>
                    ) : (
                      <div className="p-3 rounded-lg border-2 bg-gray-50 border-gray-200 text-gray-600">
                        <p className="text-sm font-medium">Aguardando início</p>
                      </div>
                    )}

                    {/* Data inicial */}
                    <div className="flex items-center justify-between text-sm p-2 rounded-lg bg-gray-50 border">
                      <div className="flex items-center gap-2 text-gray-600">
                        <Calendar className="w-4 h-4" />
                        <span className="font-medium">Início:</span>
                      </div>
                      <span className="font-bold text-gray-900">
                        {proc.data_inicial && !isNaN(new Date(proc.data_inicial).getTime()) ? format(new Date(proc.data_inicial), 'dd/MM/yyyy', {
                          locale: ptBR,
                        }) : '-'}
                      </span>
                    </div>

                    {/* Profissionais */}
                    <div className="grid grid-cols-2 gap-2 text-xs">
                      {proc.dentista && (
                        <div className="flex items-center gap-1.5 p-2 bg-blue-50/50 rounded border border-blue-100">
                          <User className="w-3 h-3 text-blue-600" />
                          <span className="font-medium text-blue-900 truncate">
                            {proc.dentista.nome}
                          </span>
                        </div>
                      )}
                      {proc.protetico && (
                        <div className="flex items-center gap-1.5 p-2 bg-orange-50/50 rounded border border-orange-100">
                          <User className="w-3 h-3 text-orange-600" />
