}

import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Calendar, User, CheckCircle, Clock, AlertCircle, Save, Home, ClipboardList, Package, PlusCircle, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { useProcedimentoById, useUpdateEtapa } from '@/hooks/useProcedimentos';
import { useDentistas } from '@/hooks/useDentistas';
import { useProteticos } from '@/hooks/useProteticos';
import { useEstoque } from '@/hooks/useEstoque';
import { ETAPAS_PPR, StatusEtapa, getCorResponsavel, TipoExecutor } from '@/types/procedimentos';
import { usePermissions } from '@/hooks/usePermissions';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { toast } from '@/hooks/use-toast';
import { getBrasiliaDate } from '@/utils/timezone';
import { useHistorico } from '@/hooks/useHistorico';
import { HistoricoTimeline } from '@/components/procedimentos/HistoricoTimeline';

export default function ProcedimentoDetail() {
  const { os: id } = useParams<{ os: string }>();
  const navigate = useNavigate();
  const { data: procedimento, isLoading } = useProcedimentoById(id || '');
  const { dentistas } = useDentistas();
  const { data: proteticos } = useProteticos();
  const { estoques, updateEstoque } = useEstoque();
  const updateEtapa = useUpdateEtapa();
  const { canExecuteEtapa, isAdmin } = usePermissions();
  const { itens: historico, isLoading: loadingHistorico, adicionarEvento } = useHistorico(procedimento?.id, 'PPR');

  const [etapaEditando, setEtapaEditando] = useState<string | null>(null);
  const [statusSelecionado, setStatusSelecionado] = useState<StatusEtapa>('Pendente');
  const [executorSelecionado, setExecutorSelecionado] = useState<string>('');
  const [materiaisConsumidos, setMateriaisConsumidos] = useState<{item_id: string, nome: string, quantidade: number}[]>([]);
  const [materialSelecionado, setMaterialSelecionado] = useState('');
  const [quantidadeMaterial, setQuantidadeMaterial] = useState(1);

  const handleIniciarEdicao = (etapaKey: string, statusAtual: StatusEtapa) => {
    setEtapaEditando(etapaKey);
    setStatusSelecionado(statusAtual);
    setExecutorSelecionado('');
    setMateriaisConsumidos([]);
  };

  const handleAddMaterial = () => {
    if (!materialSelecionado) return;
    const item = (estoques as any[]).find(e => e.id === materialSelecionado);
    if (!item) return;

    const novosMateriais = [...materiaisConsumidos];
    const indexExistente = novosMateriais.findIndex(m => m.item_id === materialSelecionado);

    if (indexExistente > -1) {
      novosMateriais[indexExistente].quantidade += quantidadeMaterial;
    } else {
      novosMateriais.push({
        item_id: materialSelecionado,
        nome: item.item,
        quantidade: quantidadeMaterial
      });
    }

    setMateriaisConsumidos(novosMateriais);
    setMaterialSelecionado('');
    setQuantidadeMaterial(1);
  };

  const handleSalvarEtapa = async (etapaKey: string, responsavel: TipoExecutor) => {
    if (!procedimento || !executorSelecionado) {
      console.error('Faltam dados:', { procedimento: !!procedimento, executorSelecionado });
      return;
    }

    let executor;
    let executorId: string | number | undefined;

    if (responsavel === 'DENTISTA') {
      executor = dentistas?.find(d => d.id === executorSelecionado);
      // Para dentistas, usamos UUID
      executorId = executorSelecionado;
    } else if (responsavel === 'PROTETICO') {
      executor = proteticos?.find(p => p.id.toString() === executorSelecionado);
      executorId = parseInt(executorSelecionado);
    } else {
      // SECRETARIA
      executor = { nome: 'Secretária' };
      executorId = undefined; // Não há ID para secretária
    }

    if (!executor) {
      console.error('Executor não encontrado:', executorSelecionado, { dentistas, proteticos });
      toast({
        title: 'Erro',
        description: 'Profissional não encontrado. Por favor, selecione novamente.',
        variant: 'destructive',
      });
      return;
    }

    console.log('Salvando etapa:', {
      etapaKey,
      status: statusSelecionado,
      executorId,
      executorNome: executor.nome,
      tipoExecutor: responsavel
    });

    await updateEtapa.mutateAsync({
      procedimentoId: procedimento.id,
      etapaKey,
      status: statusSelecionado,
      data: getBrasiliaDate(), // Data no fuso horário de Brasília
      executorId,
      executorNome: executor.nome,
      tipoExecutor: responsavel,
    });

    // Registrar no histórico
    await adicionarEvento({
      procedimento_id: procedimento.id,
      tipo_procedimento: 'PPR',
      ordem_servico: procedimento.ordem_servico,
      usuario_nome: executor.nome,
      acao: `Atualizou etapa "${etapaKey}" para ${statusSelecionado}`,
      detalhes: `Executor: ${executor.nome} (${responsavel})`,
      tipo: 'STATUS',
      paciente_id: procedimento.paciente_id
    });

    // Baixar estoque se houver materiais
    if (materiaisConsumidos.length > 0) {
      for (const mat of materiaisConsumidos) {
        const item = (estoques as any[]).find(e => e.id === mat.item_id);
        if (item) {
          await (updateEstoque as any).mutateAsync({
            id: item.id,
            estoque: item.estoque - mat.quantidade
          });
        }
      }
      toast({
        title: "Estoque atualizado",
        description: `${materiaisConsumidos.length} material(is) consumido(s).`,
      });
    }

    setEtapaEditando(null);
    setExecutorSelecionado('');
    setMateriaisConsumidos([]);
  };


  const getStatusIcon = (status: StatusEtapa) => {
    switch (status) {
      case 'Finalizado':
      case 'Concluido':
        return <CheckCircle className="w-5 h-5 text-green-600" />;
      case 'Aguardando':
        return <Clock className="w-5 h-5 text-yellow-600" />;
      case 'Enviado':
        return <AlertCircle className="w-5 h-5 text-blue-600" />;
      default:
        return <Clock className="w-5 h-5 text-gray-400" />;
    }
  };

  const getStatusColor = (status: StatusEtapa) => {
    switch (status) {
      case 'Finalizado':
      case 'Concluido':
        return 'bg-green-100 text-green-800 border-green-300';
      case 'Aguardando':
        return 'bg-yellow-100 text-yellow-800 border-yellow-300';
      case 'Enviado':
        return 'bg-blue-100 text-blue-800 border-blue-300';
      case 'Procedimento OK':
        return 'bg-green-100 text-green-800 border-green-300';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  // Retorna a cor de fundo da etapa baseada no status e responsável
  const getEtapaBackgroundColor = (status: StatusEtapa, responsavel: TipoExecutor) => {
    const isConcluido = status === 'Finalizado' || status === 'Concluido' || status === 'Procedimento OK';

    if (!isConcluido) {
      return 'bg-white border-gray-200';
    }

    switch (responsavel) {
      case 'DENTISTA':
        return 'bg-blue-50 border-blue-300';
      case 'PROTETICO':
        return 'bg-orange-50 border-orange-300';
      case 'SECRETARIA':
        return 'bg-green-50 border-green-300';
      default:
        return 'bg-white border-gray-200';
    }
  };

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="text-center">Carregando procedimento...</div>
      </div>
    );
  }

  if (!procedimento) {
    return (
      <div className="p-6">
        <div className="text-center">Procedimento não encontrado</div>
      </div>
    );
  }

  return (
    <div className="p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 mb-6">
          <Button
            variant="outline"
            onClick={() => navigate('/')}
            className="gap-2 border-2 hover:border-primary hover:bg-primary/5 transition-all duration-200 shadow-sm hover:shadow-md font-semibold"
          >
            <Home className="w-4 h-4" />
            <span className="hidden sm:inline">Voltar ao Menu</span>
            <span className="sm:hidden">Menu</span>
          </Button>
          <Button
            variant="ghost"
            onClick={() => navigate('/procedimentos/ppr')}
            className="gap-2 hover:bg-gray-100 transition-all duration-200 font-semibold"
          >
            <ArrowLeft className="w-4 h-4" />
            <span className="hidden sm:inline">Voltar para Procedimentos</span>
            <span className="sm:hidden">Procedimentos</span>
          </Button>
        </div>

        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 p-6 bg-gradient-to-r from-primary/5 via-primary/3 to-transparent rounded-xl border-l-4 border-l-primary shadow-sm">
          <div>
            <h1 className="text-3xl sm:text-4xl font-bold text-gray-900 flex items-center gap-3">
              <span className="text-primary">#</span>
              {procedimento.ordem_servico.toString().padStart(6, '0')}
            </h1>
            <p className="text-xl text-gray-600 mt-2 font-medium">{procedimento.nome_paciente}</p>
