import { useState, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Filter, Plus, ClipboardList, Calendar, User, Home, ArrowLeft } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { useProcedimentos } from '@/hooks/useProcedimentos';
import { StatusProcedimento, ETAPAS_PPR, TipoExecutor } from '@/types/procedimentos';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

// Função para obter a última modificação de um procedimento
function getUltimaModificacao(proc: any): {
  etapaLabel: string;
  responsavel: TipoExecutor;
  executadoPor: string;
  executadoEm: string | null;
} | null {
  let ultimaData: Date | null = null;
  let ultimaEtapa: { label: string; responsavel: TipoExecutor } | null = null;
  let executadoPor = '';
  let executadoEm: string | null = null;

  for (const etapa of ETAPAS_PPR) {
    const executadoEmKey = `${etapa.key}_executado_em` as keyof typeof proc;
    const executadoPorKey = `${etapa.key}_executado_por` as keyof typeof proc;
    const dataExecucao = proc[executadoEmKey];

    if (dataExecucao) {
      const data = new Date(dataExecucao);
      if (!ultimaData || data > ultimaData) {
        ultimaData = data;
        ultimaEtapa = { label: etapa.label, responsavel: etapa.responsavel };
        executadoPor = proc[executadoPorKey] || '';
        executadoEm = dataExecucao;
      }
    }
  }

  if (ultimaEtapa) {
    return {
      etapaLabel: ultimaEtapa.label,
      responsavel: ultimaEtapa.responsavel,
      executadoPor,
      executadoEm,
    };
  }

  return null;
}

// Função para obter a cor baseada no responsável
function getCorResponsavelCard(responsavel: TipoExecutor): string {
  switch (responsavel) {
    case 'DENTISTA':
      return 'bg-blue-50 border-blue-300 text-blue-800';
    case 'PROTETICO':
      return 'bg-orange-50 border-orange-300 text-orange-800';
    case 'SECRETARIA':
      return 'bg-green-50 border-green-300 text-green-800';
    default:
      return 'bg-gray-50 border-gray-300 text-gray-800';
  }
}

export default function ProcedimentosListPage() {
  const navigate = useNavigate();
  const { data: procedimentos, isLoading } = useProcedimentos();
  const [filtroStatus, setFiltroStatus] = useState<string>('todos');

  // Filtrar e ordenar por última modificação
  const procedimentosFiltrados = useMemo(() => {
    let filtered = filtroStatus === 'todos'
      ? procedimentos
      : procedimentos?.filter((p) => p.status_geral === filtroStatus);

    if (!filtered) return filtered;

    // Ordenar por última modificação (mais recente primeiro)
    return [...filtered].sort((a, b) => {
      const ultimaA = getUltimaModificacao(a);
      const ultimaB = getUltimaModificacao(b);

      if (!ultimaA?.executadoEm && !ultimaB?.executadoEm) {
        return b.ordem_servico - a.ordem_servico; // Fallback: ordem de serviço
      }
      if (!ultimaA?.executadoEm) return 1;
      if (!ultimaB?.executadoEm) return -1;

      return new Date(ultimaB.executadoEm).getTime() - new Date(ultimaA.executadoEm).getTime();
    });
  }, [procedimentos, filtroStatus]);

  const getStatusColor = (status: StatusProcedimento) => {
    switch (status) {
      case 'Concluído':
        return 'bg-green-100 text-green-800 border-green-300';
      case 'Em andamento':
        return 'bg-blue-100 text-blue-800 border-blue-300';
      case 'Pendente':
        return 'bg-yellow-100 text-yellow-800 border-yellow-300';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="mb-6">
          <Skeleton className="h-10 w-64 mb-2" />
          <Skeleton className="h-6 w-96" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
