                    <p className="text-xs">por {ultimaMod.executadoPor}</p>
                  </div>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>

      {procedimentosFiltrados?.length === 0 && (
        <div className="text-center py-12">
          <ClipboardList className="w-16 h-16 mx-auto text-gray-400 mb-4" />
          <p className="text-gray-600 text-lg">Nenhum procedimento encontrado</p>
          <Button
            onClick={() => navigate('/procedimentos/resina-impressa/novo')}
            className="mt-4 gap-2 bg-cyan-500 hover:bg-cyan-600"
          >
            <Plus className="w-4 h-4" />
            Criar Primeiro Procedimento
          </Button>
        </div>
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Filter, Plus, Calendar, Search, FileText, Smile, Sparkles, Home, ArrowLeft } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { useProcedimentos } from '@/hooks/useProcedimentos';
import { useProcedimentosPTPM } from '@/hooks/useProcedimentosPTPM';
import { useProcedimentosFixa } from '@/hooks/useProcedimentosFixa';
import { useProcedimentosProtocolo } from '@/hooks/useProcedimentosProtocolo';
import { useResinaImpressa } from '@/hooks/useResinaImpressa';
import { useCeramica } from '@/hooks/useCeramica';
import { usePlaca } from '@/hooks/usePlaca';
import { useProvisorio } from '@/hooks/useProvisorio';
import { useLabExterno } from '@/hooks/useLabExterno';
import { StatusProcedimento } from '@/types/procedimentos';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

export default function TodosProcedimentos() {
  const navigate = useNavigate();
  const { data: procedimentosPPR, isLoading: loadingPPR } = useProcedimentos();
  const { data: procedimentosPTPM, isLoading: loadingPTPM } = useProcedimentosPTPM();
  const { data: procedimentosFixa, isLoading: loadingFixa } = useProcedimentosFixa();
  const { data: procedimentosProtocolo, isLoading: loadingProtocolo } = useProcedimentosProtocolo();
  const { data: procedimentosResinaImpressa, isLoading: loadingResina } = useResinaImpressa();
  const { data: procedimentosCeramica, isLoading: loadingCeramica } = useCeramica();
  const { data: procedimentosPlaca, isLoading: loadingPlaca } = usePlaca();
  const { data: procedimentosProvisorio, isLoading: loadingProvisorio } = useProvisorio();
  const { data: procedimentosLabExterno, isLoading: loadingLabExterno } = useLabExterno();

  const [filtroTexto, setFiltroTexto] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<string>('todos');
  const [tabAtiva, setTabAtiva] = useState<string>('todos');
  const [modalAberto, setModalAberto] = useState(false);

  // Combinar todos os procedimentos
  const todosProcedimentos = useMemo(() => {
    const ppr = (procedimentosPPR || []).map((p: any) => ({ ...p, tipo: 'PPR' }));
    const ptpm = (procedimentosPTPM || []).map((p: any) => ({ ...p, tipo: 'PT/PM' }));
    const fixa = (procedimentosFixa || []).map((p: any) => ({ ...p, tipo: 'FIXA ORTOVITAL' }));
    const protocoloProvisorio = (procedimentosProtocolo?.filter((p: any) => p.tipo_protocolo === 'PROVISORIO') || []).map((p: any) => ({ ...p, tipo: 'PROTOCOLO PROVISORIO' }));
    const protocoloDefinitivo = (procedimentosProtocolo?.filter((p: any) => p.tipo_protocolo === 'DEFINITIVO') || []).map((p: any) => ({ ...p, tipo: 'PROTOCOLO DEFINITIVO' }));
    const resinaImpressa = (procedimentosResinaImpressa || []).map((p: any) => ({ ...p, tipo: 'RESINA IMPRESSA' }));
    const ceramica = (procedimentosCeramica || []).map((p: any) => ({ ...p, tipo: 'CERAMICA ORTOVITAL' }));
    const placa = (procedimentosPlaca || []).map((p: any) => ({ ...p, tipo: 'PLACA DE BRUXISMO/CLAREAMENTO' }));
    const provisorio = (procedimentosProvisorio || []).map((p: any) => ({ ...p, tipo: 'PROVISORIO/ADESIVA' }));
    const labExterno = (procedimentosLabExterno || []).map((p: any) => ({ ...p, tipo: 'LAB EXTERNO' }));
    return [...ppr, ...ptpm, ...fixa, ...protocoloProvisorio, ...protocoloDefinitivo, ...resinaImpressa, ...ceramica, ...placa, ...provisorio, ...labExterno].sort((a, b) => b.ordem_servico - a.ordem_servico);
  }, [procedimentosPPR, procedimentosPTPM, procedimentosFixa, procedimentosProtocolo, procedimentosResinaImpressa, procedimentosCeramica, procedimentosPlaca, procedimentosProvisorio, procedimentosLabExterno]);

  // Filtrar procedimentos por tab
  const getProcedimentosPorTab = (tab: string) => {
    let procedimentos = todosProcedimentos;

    switch (tab) {
      case 'removiveis':
        procedimentos = todosProcedimentos.filter((p: any) =>
          ['PPR', 'PT/PM'].includes(p.tipo)
        );
        break;
      case 'fixas':
        procedimentos = todosProcedimentos.filter((p: any) =>
          ['FIXA ORTOVITAL', 'PROTOCOLO PROVISORIO', 'PROTOCOLO DEFINITIVO'].includes(p.tipo)
        );
        break;
      case 'digitais':
        procedimentos = todosProcedimentos.filter((p: any) =>
          ['RESINA IMPRESSA', 'CERAMICA ORTOVITAL'].includes(p.tipo)
        );
        break;
      case 'outros':
        procedimentos = todosProcedimentos.filter((p: any) =>
          ['PLACA DE BRUXISMO/CLAREAMENTO', 'PROVISORIO/ADESIVA', 'LAB EXTERNO'].includes(p.tipo)
        );
        break;
      default:
        // 'todos'
        break;
    }

    return procedimentos;
  };

  // Contar procedimentos por categoria
  const contadoresPorCategoria = useMemo(() => {
    return {
      todos: todosProcedimentos?.length || 0,
      removiveis: todosProcedimentos?.filter((p: any) => ['PPR', 'PT/PM'].includes(p.tipo)).length || 0,
      fixas: todosProcedimentos?.filter((p: any) => ['FIXA ORTOVITAL', 'PROTOCOLO PROVISORIO', 'PROTOCOLO DEFINITIVO'].includes(p.tipo)).length || 0,
      digitais: todosProcedimentos?.filter((p: any) => ['RESINA IMPRESSA', 'CERAMICA ORTOVITAL'].includes(p.tipo)).length || 0,
      outros: todosProcedimentos?.filter((p: any) => ['PLACA DE BRUXISMO/CLAREAMENTO', 'PROVISORIO/ADESIVA', 'LAB EXTERNO'].includes(p.tipo)).length || 0,
    };
  }, [todosProcedimentos]);

  // Filtrar procedimentos
  const procedimentosFiltrados = getProcedimentosPorTab(tabAtiva).filter((proc: any) => {
    const matchTexto =
      proc.nome_paciente.toLowerCase().includes(filtroTexto.toLowerCase()) ||
      proc.ordem_servico.toString().includes(filtroTexto);

    const matchStatus = filtroStatus === 'todos' || proc.status_geral === filtroStatus;

    return matchTexto && matchStatus;
  });

  const getStatusColor = (status: StatusProcedimento) => {
    switch (status) {
      case 'Concluído':
        return 'bg-green-100 text-green-800 border-green-300';
      case 'Em andamento':
        return 'bg-blue-100 text-blue-800 border-blue-300';
      case 'Pendente':
        return 'bg-yellow-100 text-yellow-800 border-yellow-300';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  const getTipoBadge = (tipo: string, tipoProtese?: string) => {
    if (tipo === 'PPR') {
      return (
        <Badge variant="outline" className="bg-blue-100 text-blue-800 border-blue-300">
          <FileText className="w-3 h-3 mr-1" />
          PPR
        </Badge>
      );
    } else if (tipo === 'FIXA ORTOVITAL') {
      return (
        <Badge variant="outline" className="bg-emerald-100 text-emerald-800 border-emerald-300">
          <Smile className="w-3 h-3 mr-1" />
          FIXA
        </Badge>
      );
    } else if (tipo === 'PROTOCOLO PROVISORIO') {
      return (
        <Badge variant="outline" className="bg-purple-100 text-purple-800 border-purple-300">
          <Sparkles className="w-3 h-3 mr-1" />
          PROT. PROVISORIO
        </Badge>
      );
    } else if (tipo === 'PROTOCOLO DEFINITIVO') {
      return (
        <Badge variant="outline" className="bg-indigo-100 text-indigo-800 border-indigo-300">
          <Sparkles className="w-3 h-3 mr-1" />
          PROT. DEFINITIVO
        </Badge>
      );
    } else if (tipo === 'RESINA IMPRESSA') {
      return (
        <Badge variant="outline" className="bg-cyan-100 text-cyan-800 border-cyan-300">
          <Sparkles className="w-3 h-3 mr-1" />
          RESINA IMPRESSA
        </Badge>
      );
    } else if (tipo === 'CERAMICA ORTOVITAL') {
      return (
        <Badge variant="outline" className="bg-pink-100 text-pink-800 border-pink-300">
          <Sparkles className="w-3 h-3 mr-1" />
          CERAMICA
        </Badge>
      );
    } else if (tipo === 'PLACA DE BRUXISMO/CLAREAMENTO') {
      return (
        <Badge variant="outline" className="bg-lime-100 text-lime-800 border-lime-300">
          <Sparkles className="w-3 h-3 mr-1" />
          PLACA
        </Badge>
      );
    } else if (tipo === 'PROVISORIO/ADESIVA') {
      return (
        <Badge variant="outline" className="bg-orange-100 text-orange-800 border-orange-300">
          <Sparkles className="w-3 h-3 mr-1" />
          PROVISORIO
        </Badge>
      );
    } else if (tipo === 'LAB EXTERNO') {
      return (
        <Badge variant="outline" className="bg-indigo-100 text-indigo-800 border-indigo-300">
          <Sparkles className="w-3 h-3 mr-1" />
          LAB EXTERNO
        </Badge>
      );
    } else {
      return (
        <Badge variant="outline" className="bg-purple-100 text-purple-800 border-purple-300">
          <Smile className="w-3 h-3 mr-1" />
          {tipoProtese || 'PT/PM'}
        </Badge>
      );
    }
  };

  const handleNovoProcedimento = (tipo: 'ppr' | 'pt-pm' | 'fixa' | 'protocolo-provisorio' | 'protocolo-definitivo' | 'resina-impressa' | 'ceramica' | 'placa' | 'provisorio' | 'lab-externo') => {
    setModalAberto(false);
    if (tipo === 'ppr') {
      navigate('/procedimentos/ppr/novo');
    } else if (tipo === 'fixa') {
      navigate('/procedimentos/fixa/novo');
    } else if (tipo === 'protocolo-provisorio') {
      navigate('/procedimentos/protocolo-provisorio/novo');
    } else if (tipo === 'protocolo-definitivo') {
      navigate('/procedimentos/protocolo-definitivo/novo');
    } else if (tipo === 'resina-impressa') {
      navigate('/procedimentos/resina-impressa/novo');
    } else if (tipo === 'ceramica') {
      navigate('/procedimentos/ceramica/novo');
    } else if (tipo === 'placa') {
      navigate('/procedimentos/placa/novo');
    } else if (tipo === 'provisorio') {
      navigate('/procedimentos/provisorio/novo');
    } else if (tipo === 'lab-externo') {
      navigate('/procedimentos/lab-externo/novo');
    } else {
      navigate('/procedimentos/pt-pm/novo');
    }
  };

  const handleVerDetalhes = (proc: any) => {
    if (proc.tipo === 'PPR') {
      navigate(`/procedimentos/ppr/${proc.ordem_servico}`);
    } else if (proc.tipo === 'FIXA ORTOVITAL') {
      navigate(`/procedimentos/fixa/${proc.ordem_servico}`);
    } else if (proc.tipo === 'PROTOCOLO PROVISORIO') {
      navigate(`/procedimentos/protocolo-provisorio/${proc.ordem_servico}`);
    } else if (proc.tipo === 'PROTOCOLO DEFINITIVO') {
      navigate(`/procedimentos/protocolo-definitivo/${proc.ordem_servico}`);
    } else if (proc.tipo === 'RESINA IMPRESSA') {
      navigate(`/procedimentos/resina-impressa/${proc.ordem_servico}`);
    } else if (proc.tipo === 'CERAMICA ORTOVITAL') {
      navigate(`/procedimentos/ceramica/${proc.ordem_servico}`);
    } else if (proc.tipo === 'PLACA DE BRUXISMO/CLAREAMENTO') {
      navigate(`/procedimentos/placa/${proc.ordem_servico}`);
    } else if (proc.tipo === 'PROVISORIO/ADESIVA') {
      navigate(`/procedimentos/provisorio/${proc.ordem_servico}`);
    } else if (proc.tipo === 'LAB EXTERNO') {
      navigate(`/procedimentos/lab-externo/${proc.ordem_servico}`);
    } else {
      navigate(`/procedimentos/pt-pm/${proc.ordem_servico}`);
    }
  };

  const isLoading = loadingPPR || loadingPTPM || loadingFixa || loadingProtocolo || loadingResina || loadingCeramica || loadingPlaca || loadingProvisorio || loadingLabExterno;

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="flex items-center justify-center h-64">
          <div className="text-gray-500">Carregando procedimentos...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Todos os Procedimentos</h1>
          <p className="text-gray-600 mt-1">
            PPR, PT/PM, FIXA, PROTOCOLO, RESINA IMPRESSA, CERAMICA, PLACA, PROVISORIO e LAB EXTERNO
          </p>
        </div>
        <div className="flex gap-3">
          <Button
            variant="outline"
            onClick={() => navigate('/')}
            className="gap-2 border-2 hover:border-primary hover:bg-primary/5"
          >
            <Home className="w-4 h-4" />
            Dashboard
          </Button>
          <Button onClick={() => setModalAberto(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Novo Procedimento
          </Button>
        </div>
      </div>

      {/* Abas de Categorias - Melhoradas */}
      <Tabs value={tabAtiva} onValueChange={setTabAtiva} className="w-full">
        <div className="overflow-x-auto -mx-2 px-2 pb-2">
          <TabsList className="w-full min-w-max h-auto p-2 bg-gradient-to-br from-gray-100 to-gray-50 inline-flex flex-nowrap md:grid md:grid-cols-5 gap-2 shadow-inner">
            <TabsTrigger
              value="todos"
              className="data-[state=active]:bg-gradient-to-br data-[state=active]:from-white data-[state=active]:to-gray-50 data-[state=active]:shadow-md data-[state=active]:border-2 data-[state=active]:border-gray-300 text-xs md:text-sm font-semibold px-3 md:px-4 py-2 md:py-2.5 transition-all hover:scale-105 whitespace-nowrap"
            >
              TODOS ({contadoresPorCategoria.todos})
            </TabsTrigger>
            <TabsTrigger
              value="removiveis"
              className="data-[state=active]:bg-gradient-to-br data-[state=active]:from-purple-500 data-[state=active]:to-purple-600 data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:border-2 data-[state=active]:border-purple-700 text-xs md:text-sm font-semibold px-3 md:px-4 py-2 md:py-2.5 transition-all hover:scale-105 whitespace-nowrap"
            >
              REMOVÍVEIS ({contadoresPorCategoria.removiveis})
            </TabsTrigger>
            <TabsTrigger
              value="fixas"
              className="data-[state=active]:bg-gradient-to-br data-[state=active]:from-emerald-500 data-[state=active]:to-emerald-600 data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:border-2 data-[state=active]:border-emerald-700 text-xs md:text-sm font-semibold px-3 md:px-4 py-2 md:py-2.5 transition-all hover:scale-105 whitespace-nowrap"
            >
              FIXAS ({contadoresPorCategoria.fixas})
            </TabsTrigger>
            <TabsTrigger
              value="digitais"
              className="data-[state=active]:bg-gradient-to-br data-[state=active]:from-cyan-500 data-[state=active]:to-cyan-600 data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:border-2 data-[state=active]:border-cyan-700 text-xs md:text-sm font-semibold px-3 md:px-4 py-2 md:py-2.5 transition-all hover:scale-105 whitespace-nowrap"
            >
              DIGITAIS ({contadoresPorCategoria.digitais})
            </TabsTrigger>
            <TabsTrigger
              value="outros"
              className="data-[state=active]:bg-gradient-to-br data-[state=active]:from-orange-500 data-[state=active]:to-orange-600 data-[state=active]:text-white data-[state=active]:shadow-lg data-[state=active]:border-2 data-[state=active]:border-orange-700 text-xs md:text-sm font-semibold px-3 md:px-4 py-2 md:py-2.5 transition-all hover:scale-105 whitespace-nowrap"
            >
              OUTROS ({contadoresPorCategoria.outros})
            </TabsTrigger>
          </TabsList>
        </div>

        {/* Filtros Melhorados */}
        <Card className="mt-4">
          <CardContent className="pt-6">
            {/* Busca Rápida */}
            <div className="mb-4">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                <Input
                  placeholder="Buscar por paciente ou OS..."
                  value={filtroTexto}
                  onChange={(e) => setFiltroTexto(e.target.value)}
                  className="pl-11 h-12 text-base border-2 focus:border-primary"
                />
              </div>
              {filtroTexto && (
                <p className="text-xs text-muted-foreground mt-2">
                  {procedimentosFiltrados.length} resultado(s) encontrado(s)
                </p>
              )}
            </div>

            {/* Filtro de Status e Contador */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Select value={filtroStatus} onValueChange={setFiltroStatus}>
                <SelectTrigger className="h-11">
                  <Filter className="w-4 h-4 mr-2" />
                  <SelectValue placeholder="Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todos">Todos os status</SelectItem>
                  <SelectItem value="Pendente">Pendente</SelectItem>
                  <SelectItem value="Em andamento">Em andamento</SelectItem>
                  <SelectItem value="Concluído">Concluído</SelectItem>
                </SelectContent>
              </Select>

              <div className="text-sm text-gray-600 flex items-center justify-end bg-gray-50 rounded-lg px-4 py-2 border">
                <span className="font-bold text-lg text-primary">{procedimentosFiltrados.length}</span>
                <span className="ml-2">procedimentos</span>
              </div>
            </div>
          </CardContent>
        </Card>
      </Tabs>

      {/* Lista de Procedimentos */}
      <div className="grid gap-4">
        {procedimentosFiltrados.map((proc: any) => (
          <Card
            key={`${proc.tipo}-${proc.id}`}
            className="hover:shadow-md transition-shadow cursor-pointer"
            onClick={() => handleVerDetalhes(proc)}
          >
            <CardContent className="p-6">
              <div className="flex justify-between items-start">
                <div className="space-y-2 flex-1">
                  <div className="flex items-center gap-3 flex-wrap">
                    <h3 className="text-lg font-semibold text-gray-900">
                      OS #{proc.ordem_servico}
                    </h3>
                    {getTipoBadge(proc.tipo, proc.tipo_protese)}
                    <Badge variant="outline" className={getStatusColor(proc.status_geral)}>
                      {proc.status_geral}
                    </Badge>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">Paciente:</span>
                      <p className="font-medium text-gray-900">{proc.nome_paciente}</p>
                    </div>

                    {proc.arcada && (
                      <div>
                        <span className="text-gray-600">Arcada:</span>
                        <p className="font-medium text-gray-900">{proc.arcada}</p>
                      </div>
                    )}

                    {proc.dentista && (
                      <div>
                        <span className="text-gray-600">Dentista:</span>
                        <p className="font-medium text-gray-900">{proc.dentista.nome}</p>
                      </div>
                    )}

                    {proc.protetico && (
                      <div>
                        <span className="text-gray-600">Protético:</span>
                        <p className="font-medium text-gray-900">{proc.protetico.nome}</p>
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-4 text-sm text-gray-600">
                    <span className="flex items-center gap-1">
                      <Calendar className="w-4 h-4" />
                      Início: {format(new Date(proc.data_inicial), 'dd/MM/yyyy', { locale: ptBR })}
                    </span>
                    {proc.data_entrega && (
                      <span className="flex items-center gap-1">
                        <Calendar className="w-4 h-4" />
                        Entrega: {format(new Date(proc.data_entrega), 'dd/MM/yyyy', { locale: ptBR })}
                      </span>
                    )}
                  </div>
                </div>

                <Button
                  variant="outline"
                  size="sm"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleVerDetalhes(proc);
                  }}
                >
                  Ver Detalhes
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}

        {procedimentosFiltrados.length === 0 && (
          <Card>
            <CardContent className="p-12 text-center">
              <div className="max-w-md mx-auto">
                <Search className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                <h3 className="text-xl font-semibold text-gray-700 mb-3">
                  {filtroTexto ? 'Nenhum resultado encontrado' : 'Nenhum procedimento'}
                </h3>
                <p className="text-sm text-gray-500 mb-6">
                  {filtroTexto
                    ? `Não encontramos procedimentos com "${filtroTexto}"`
                    : tabAtiva === 'todos'
                    ? 'Não há procedimentos cadastrados no momento'
                    : `Não há procedimentos na categoria ${tabAtiva.toUpperCase()}`}
                </p>
                <div className="flex gap-3 justify-center">
                  {filtroTexto && (
                    <Button
                      variant="outline"
                      onClick={() => setFiltroTexto('')}
                      className="gap-2"
                    >
                      <Search className="w-4 h-4" />
                      Limpar busca
                    </Button>
                  )}
                  <Button onClick={() => setModalAberto(true)} className="gap-2">
                    <Plus className="w-4 h-4" />
                    Novo Procedimento
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Modal de Seleção de Tipo */}
      <Dialog open={modalAberto} onOpenChange={setModalAberto}>
        <DialogContent className="max-w-[95vw] sm:max-w-[90vw] lg:max-w-[1200px] max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-xl sm:text-2xl font-bold">Escolha o Tipo de Procedimento</DialogTitle>
            <DialogDescription className="text-sm sm:text-base">
              Selecione o tipo de procedimento que deseja criar
            </DialogDescription>
          </DialogHeader>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 sm:gap-4 mt-4">
            {/* Card PPR */}
            <Card
              className="cursor-pointer hover:shadow-lg hover:scale-105 transition-all border-2 hover:border-blue-500 group"
              onClick={() => handleNovoProcedimento('ppr')}
            >
              <CardContent className="p-4 sm:p-6">
                <div className="flex flex-col items-center text-center space-y-3">
                  <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-2xl bg-gradient-to-br from-blue-500 to-blue-600 flex items-center justify-center shadow-lg group-hover:shadow-xl transition-shadow">
                    <FileText className="w-7 h-7 sm:w-8 sm:h-8 text-white" />
                  </div>
                  <div>
                    <h3 className="font-bold text-base sm:text-lg text-blue-900 mb-1">PPR</h3>
                    <p className="text-xs sm:text-sm text-gray-600 hidden sm:block">Prótese Parcial Removível</p>
                    <p className="text-xs text-gray-500 mt-2">11 etapas</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Card PT/PM */}
            <Card
              className="cursor-pointer hover:shadow-lg hover:scale-105 transition-all border-2 hover:border-purple-500 group"
              onClick={() => handleNovoProcedimento('pt-pm')}
            >
              <CardContent className="p-4 sm:p-6">
                <div className="flex flex-col items-center text-center space-y-3">
                  <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-2xl bg-gradient-to-br from-purple-500 to-purple-600 flex items-center justify-center shadow-lg group-hover:shadow-xl transition-shadow">
                    <Smile className="w-7 h-7 sm:w-8 sm:h-8 text-white" />
                  </div>
                  <div>
                    <h3 className="font-bold text-base sm:text-lg text-purple-900 mb-1">PT/PM</h3>
                    <p className="text-xs sm:text-sm text-gray-600 hidden sm:block">Prótese Total/Móvel</p>
                    <p className="text-xs text-gray-500 mt-2">11 etapas</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Card FIXA ORTOVITAL */}
            <Card
              className="cursor-pointer hover:shadow-lg hover:scale-105 transition-all border-2 hover:border-emerald-500 group"
              onClick={() => handleNovoProcedimento('fixa')}
            >
              <CardContent className="p-4 sm:p-6">
                <div className="flex flex-col items-center text-center space-y-3">
                  <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-2xl bg-gradient-to-br from-emerald-500 to-emerald-600 flex items-center justify-center shadow-lg group-hover:shadow-xl transition-shadow">
                    <Sparkles className="w-7 h-7 sm:w-8 sm:h-8 text-white" />
                  </div>
                  <div>
                    <h3 className="font-bold text-base sm:text-lg text-emerald-900 mb-1">FIXA</h3>
                    <p className="text-xs sm:text-sm text-gray-600 hidden sm:block">Prótese Fixa Ortovital</p>
                    <p className="text-xs text-gray-500 mt-2">6 etapas</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Card PROTOCOLO PROVISORIO */}
            <Card
              className="cursor-pointer hover:shadow-lg hover:scale-105 transition-all border-2 hover:border-purple-500 group"
              onClick={() => handleNovoProcedimento('protocolo-provisorio')}
            >
              <CardContent className="p-4 sm:p-6">
                <div className="flex flex-col items-center text-center space-y-3">
                  <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-2xl bg-gradient-to-br from-purple-500 to-purple-600 flex items-center justify-center shadow-lg group-hover:shadow-xl transition-shadow">
                    <Sparkles className="w-7 h-7 sm:w-8 sm:h-8 text-white" />
                  </div>
                  <div>
                    <h3 className="font-bold text-sm sm:text-base text-purple-900 mb-1">PROT. PROV.</h3>
                    <p className="text-xs sm:text-sm text-gray-600 hidden sm:block">Protocolo Provisório</p>
                    <p className="text-xs text-gray-500 mt-2">8 etapas</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Card PROTOCOLO DEFINITIVO */}
            <Card
              className="cursor-pointer hover:shadow-lg hover:scale-105 transition-all border-2 hover:border-indigo-500 group"
              onClick={() => handleNovoProcedimento('protocolo-definitivo')}
            >
              <CardContent className="p-4 sm:p-6">
                <div className="flex flex-col items-center text-center space-y-3">
